INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_1283323d7754','bk_ncert_english','11-1-the-lament','11.1 The Lament',NULL,'public',41,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44914a450528','ch_1283323d7754','text','{"text": "It is twilight."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_279667818400','ch_1283323d7754','text','{"text": "A thick wet snow is slowly twirling around the newly lighted street lamps and lying in soft thin layers on roofs, on horses’ backs, on people’s shoulders and hats. The cabdriver, Iona Potapov, is quite white and looks like a phantom:"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6af460122058','ch_1283323d7754','text','{"text": "he is bent double as far as a human body can bend double; he is seated on his box; he never makes a move. If a whole snowdrift fell on him, it seems as if he would not find it necessary to shake it off."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e272b97652ec','ch_1283323d7754','text','{"text": "His little horse is also quite white, and remains motionless; its immobility, its angularity and its straight wooden-looking legs, even close by, give it the appearance of a gingerbread horse worth a kopek. It is, no doubt, plunged in deep thought. If you were snatched from the plough, from your usual gray surroundings, and were thrown into this slough full of monstrous lights, unceasing noise and hurrying people, you too would find it difficult not to think."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_684394fc2c05','ch_1283323d7754','text','{"text": "Iona and his little horse have not moved from their place for a long while. They left their yard before dinner and, up to now, not a fare. The evening mist is descending over the town, the white lights of the lamps are replacing brighter rays, and the hubbub of the street is getting louder."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6e4226ed24e','ch_1283323d7754','text','{"text": "‘Cabby for Viborg Way!’ suddenly hears Iona."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70c2fafeaf64','ch_1283323d7754','text','{"text": "‘Cabby!’ Iona jumps and, through his snow-covered eyelashes, sees an officer in a greatcoat, with his hood over his head."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_938007fa1379','ch_1283323d7754','text','{"text": "‘Viborg way!’ the officer repeats."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7863b3eb6066','ch_1283323d7754','text','{"text": "‘Are you asleep, eh? Viborg way!’ With a nod of assent Iona picks up the reins, in consequence of which layers of snow slip off the horse’s back and neck."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b618eb7b77f','ch_1283323d7754','text','{"text": "The officer seats himself in the sleigh, the cabdriver smacks his lips to encourage his horse, stretches out his neck like a swan, sits up and, more from habit than necessity, brandishes his whip. The little horse also stretches its neck, bends its wooden-looking legs, and makes a move undecidedly."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b19c16f56a2d','ch_1283323d7754','text','{"text": "‘What are you doing, werewolf!’ is the exclamation Iona hears from the dark mass moving to and fro, as soon as they have started."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db4172272685','ch_1283323d7754','text','{"text": "‘Where the devil are you going? To the r-r-right!’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3827baa113db','ch_1283323d7754','text','{"text": "‘You do not know how to drive. Keep to the right!’ calls the officer angrily. A coachman from a private carriage swears at him; a passerby, who has run across the road and rubbed his shoulder against the horse’s nose, looks at him furiously as he sweeps the snow from his sleeve. Iona shifts about on his seat as if he were on needles, moves his elbows as if he were trying to keep his equilibrium, and gasps about like someone suffocating, who does not understand why and wherefore he is there."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_225d060ae7cb','ch_1283323d7754','text','{"text": "‘What scoundrels they all are!’ jokes the officer;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ffd6a632c4e','ch_1283323d7754','text','{"text": "‘one would think they had all entered into an agreement to jostle you or fall under your horse.’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddd7e4c29016','ch_1283323d7754','text','{"text": "Iona looks around at the officer and moves his lips. He evidently wants to say something but the only sound that issues is a snuffle."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1cf89479b47e','ch_1283323d7754','text','{"text": "‘What?’ asks the officer. Iona twists his mouth into a smile and, with an effort, says hoarsely:"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5a764524cdc','ch_1283323d7754','text','{"text": "‘My son, Barin, died this week.’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29784793e904','ch_1283323d7754','text','{"text": "‘Hm! What did he die of?’ Iona turns with his whole body towards his fare and says:"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d845e3da9cae','ch_1283323d7754','text','{"text": "‘And who knows! They say high fever. He was three days in the hospital and then died… God’s will be done.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68353583173d','ch_1283323d7754','text','{"text": "‘Turn round! The devil!’ sounds from the darkness."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8b6a0b435b7','ch_1283323d7754','text','{"text": "‘Have you popped off, old doggie, eh? Use your eyes!’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea70b314c054','ch_1283323d7754','text','{"text": "‘Go on, go on,’ says the officer, ‘otherwise we shall not get there by tomorrow."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a92b713090a','ch_1283323d7754','text','{"text": "Hurry up a bit!’ The cabdriver again stretches his neck, sits up and, with a bad grace, brandishes his whip. Several times again he turns to look at his fare, but the latter has closed his eyes and, apparently, is not disposed to listen. Having deposited the officer in the Viborg, he stops by the tavern, doubles himself up on his seat, and again remains motionless, while the snow once more begins to cover him and his horse."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3755dcdf693','ch_1283323d7754','text','{"text": "An hour, and another… Then, along the footpath, with a squeak of galoshes, and quarrelling, come three young men, two of them tall and lanky, the third one short and humpbacked."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff63f0f06def','ch_1283323d7754','text','{"text": "‘Cabby, to the Police Bridge!’ in a cracked voice calls the humpback."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf0436b68a1b','ch_1283323d7754','text','{"text": "‘The three of us for two griveniks.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_893276c2f45a','ch_1283323d7754','text','{"text": "Iona picks up his reins and smacks his lips. Two griveniks is not a fair price, but he does not mind whether it is a rouble or five kopeks—to him it is all the same now, so long as they are fares. The young men, jostling each other and using bad language, approach the sleigh and all three at once try to get onto the seat; then begins a discussion as to which two shall sit and who shall be the one to stand."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96f0a9f6c34f','ch_1283323d7754','text','{"text": "After wrangling, abusing each other and much petulance, it is at last decided that the humpback shall stand as he is the smallest."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8dc0b262c7e','ch_1283323d7754','text','{"text": "‘Now then, hurry up!’ says the humpback in a twanging voice, as he takes his place and breathes in Iona’s neck."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dfe9e647f2e','ch_1283323d7754','text','{"text": "‘Old furry! Here, mate, what a cap you have! There is not a worse one to be found in all Petersburg! …’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_188d857e8533','ch_1283323d7754','text','{"text": "‘He-he—he-he’, giggles Iona."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e80de54f38bf','ch_1283323d7754','text','{"text": "‘Such a …’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b707a27a31a','ch_1283323d7754','text','{"text": "‘Now you, ‘such a’, hurry up, are you going the whole way at this pace? Are you...Do"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7045d5cbc859','ch_1283323d7754','text','{"text": "you want it in the neck?’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d6e2afdab5b','ch_1283323d7754','text','{"text": "‘My head feels like bursting,’ says one of the lanky ones."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_348b7fd3d1e8','ch_1283323d7754','text','{"text": "‘Last night at the Donkmasoves, Vaska and I drank the whole of four bottles of cognac.’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_354beac2029a','ch_1283323d7754','text','{"text": "‘I don’t understand what you lie for,’ says the other lanky one angrily;"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98745d999ed9','ch_1283323d7754','text','{"text": "‘you lie like a brute.’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51fee3774f31','ch_1283323d7754','text','{"text": "‘God strike me, it’s the truth!’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ef994d8e31c','ch_1283323d7754','text','{"text": "‘It’s as much the truth as that a louse coughs!’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba212fc799da','ch_1283323d7754','text','{"text": "‘He-he,’ grins Iona, ‘what gay young gentlemen!’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2962c456905a','ch_1283323d7754','text','{"text": "‘Pshaw, go to the devil!’ says the humpback indignantly."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_deb5b5f5360a','ch_1283323d7754','text','{"text": "‘Are you going to get on or not, you old pest? Is that the way to drive? Use the whip a bit! Go on, devil, go on, give it to him well!’ Iona feels at his back the little man wriggling, and the tremble in his voice."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca64187b3751','ch_1283323d7754','text','{"text": "He listens to the insults hurled at him, sees the people, and little by little the feeling of loneliness leaves him. The humpback goes on swearing until he gets mixed up in some elaborate six-foot oath, or chokes with coughing. The lankies begin to talk about a certain Nadejda Petrovna. Iona looks round at them several times; he waits for a temporary silence, then, turning round again, he murmurs:"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a40a0c651e8','ch_1283323d7754','text','{"text": "‘My son… died this week.’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07eb8770aada','ch_1283323d7754','text','{"text": "‘We must all die,’ sighs the humpback, wiping his lips after an attack of coughing."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7169a89be00','ch_1283323d7754','text','{"text": "‘Now, hurry up, hurry up! Gentlemen, I really cannot go any farther like this! When will he get us there?’"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4829918d0bc','ch_1283323d7754','text','{"text": "‘Well, just you stimulate him a little in the neck!’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98ba50922da3','ch_1283323d7754','text','{"text": "‘You old pest, do you hear, I’ll bone your neck for you! If one treated the like of you with ceremony, one would have to go on foot! Do you hear, old serpent Gorinytch! Or do you not care a spit!’ Iona hears rather than feels the blow they deal him."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75b8260345e3','ch_1283323d7754','text','{"text": "‘He-he’ he laughs."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c20641b73a0','ch_1283323d7754','text','{"text": "‘They are gay young gentlemen, God bless’em!’"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1fdb7600cdd','ch_1283323d7754','text','{"text": "‘Cabby, are you married?’ asks a lanky one."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74ca9e362e2e','ch_1283323d7754','text','{"text": "‘I? He-he, gay young gentlemen! Now I have only a wife and the moist ground…He, ho, ho, …that is to say, the grave. My son has died, and I am alive…A wonderful thing, death mistook the door…instead of coming to me, it went to my son…’ Iona turns round to tell them how his son died but, at this moment, the humpback, giving a little sigh, announces, ‘Thank God, we have at last reached our destination,’ and Iona watches them disappear through the dark entrance."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8afb13e820ff','ch_1283323d7754','text','{"text": "Once more he is alone, and again surrounded by silence… His grief, which has abated for a short while, returns and rends his heart with greater force. With an anxious and hurried look, he searches among the crowds passing on either side of the street to find whether there may be just one person who will listen to him. But the crowds hurry by without noticing him or his trouble. Yet it is such an immense, illimitable, grief."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2ab5a661ef7','ch_1283323d7754','text','{"text": "Should his heart break and the grief pour out, it would flow over the whole earth, so it seems, and yet no one sees it. It has managed to conceal itself in such an insignificant shell that no one can see it even by day and with a light. Iona sees a hall porter with some sacking and decides to talk to him."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5eaedb27f1d0','ch_1283323d7754','text','{"text": "‘Friend, what sort of time is it?’ he asks."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddc8a867cacb','ch_1283323d7754','text','{"text": "‘Past nine. What are you standing here for? Move on.’"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_554a3744971d','ch_1283323d7754','text','{"text": "Iona moves on a few steps, doubles himself up, and abandons himself to his grief. He sees it is useless to turn to people for help. In less than five minutes he straightens himself, holds up his head as if he felt some sharp pain, and gives a tug at the reins; he can bear it no longer."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcfced64b2f2','ch_1283323d7754','text','{"text": "‘The stables,’ he thinks, and the little horse, as if it understood, starts off at a trot."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce51bac2c7c3','ch_1283323d7754','text','{"text": "About an hour and a half later, Iona is seated by a large dirty stove. Around the stove, on the floor, on the benches, people are snoring; the air is thick and suffocatingly hot. Iona looks at the sleepers, scratches himself, and regrets having returned so early."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc6e19e2b414','ch_1283323d7754','text','{"text": "‘I have not even earned my fodder,’ he thinks."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3a0c4ac70c8','ch_1283323d7754','text','{"text": "‘That’s what’s my trouble. A man who knows his job, who has had enough to eat and his horse too, can always sleep peacefully.’"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec1166bb9ddf','ch_1283323d7754','text','{"text": "A young cabdriver, in one of the corners, half gets up, grunts sleepily, and stretches towards a bucket of water."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa7cea767152','ch_1283323d7754','text','{"text": "‘Do you want a drink?’ Iona asks him."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b7cd01f1bb4','ch_1283323d7754','text','{"text": "‘Don’t I want a drink!’"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74cab947829b','ch_1283323d7754','text','{"text": "‘That’s so? Your good health. But listen, mate—you know, my son is dead…Did you hear? This week, in the hospital…It’s a long story.’"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1e6a0222e4a','ch_1283323d7754','text','{"text": "Iona looks to see what effect his words have, but sees none—the young man has hidden his face and is fast asleep again. The old man sighs and scratches his head. Just as much as the young one wants to drink, the old man wants to talk. It will soon be a week since his son died, and he has not been able to speak about it properly to anyone. One must tell it slowly and carefully; how his son fell ill, how he suffered, what he said before he died, how he died."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42b1b966c1c0','ch_1283323d7754','text','{"text": "One must describe every detail of the funeral, and the journey to the hospital to fetch the dead son’s clothes. His daughter, Anissia, has remained in the village—one must talk about her too. It is nothing he has to tell? Surely the listener would gasp and sigh, and sympathise with him? It is better, too, to talk to women; two words are enough to make them sob."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a267d5da746d','ch_1283323d7754','text','{"text": "‘I’ll go and look after my horse,’ thinks Iona;"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d924a8eee6c','ch_1283323d7754','text','{"text": "‘there’s always time to sleep. No fear of that!’ He puts on his coat and goes to the stable to his horse; he thinks of the corn, the hay, the weather. When he is alone, he dare not think of his son; he can speak about him to anyone, but to think of him, and picture him to himself, is unbearably painful."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ebbf265e158','ch_1283323d7754','text','{"text": "‘Are you tucking in?’ Iona asks his horse, looking at its bright eyes:"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5461e509056a','ch_1283323d7754','text','{"text": "‘go on, tuck in, though we’ve not earned our corn, we can eat hay."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73ac612ee4e5','ch_1283323d7754','text','{"text": "Yes I am too old to drive—my son could have, not I. He was a first-rate cabdriver. If only he had lived!’ Iona is silent for a moment, then continues:"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bc1175cfcd4','ch_1283323d7754','text','{"text": "‘That’s how it is, my old horse. There’s no more Kuzma Ionitch. He has left us to live, and he went off pop. Now let’s say you had a foal, you were the foal’s mother and, suddenly, let’s say, that foal went and left you to live after him. It would be sad, wouldn’t it?’ The little horse munches, listens and breathes over its master’s hand… Iona’s feelings are too much for him and he tells the little horse the whole story."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ab0c9c94711','ch_1283323d7754','list','{"ordered": false, "items": ["Anton Chekhov"]}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9dfb62d01afd','ch_1283323d7754','heading','{"level": 2, "text": "About The Author"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd1cfc775c87','ch_1283323d7754','text','{"text": "Anton Chekhov (1810–1904) was born in a middle-class family in Russia. He studied medicine at Moscow University.  His first short story appeared in 1880 and, in the next seven years, he produced more than six hundred stories. He also wrote plays— Seagull, Uncle Vanya, The Three Sisters and The Cherry Orchards are among the more famous ones. His work greatly influenced the modern short story and drama."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68615d28e884','ch_1283323d7754','text','{"text": "The main theme of Chekov’s short stories is life’s pathos, caused by the inability of human beings to respond to, or even to communicate with, one another. The present story illustrates this point beautifully."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f6325e91de3','ch_1283323d7754','heading','{"level": 2, "text": "Understanding The Text"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7dad1506cbc0','ch_1283323d7754','text','{"text": "1. Comment on the indifference that meets Iona’s attempts to share his grief with his fellow human beings."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91988e6b666d','ch_1283323d7754','text','{"text": "2. What impression of the character of Iona do you get from this story?"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c3554a86d06','ch_1283323d7754','text','{"text": "3. How does the horse serve as a true friend and companion to Iona?"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ddae1cf044a','ch_1283323d7754','heading','{"level": 2, "text": "Talking About The Text"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b91148cb8864','ch_1283323d7754','text','{"text": "Discuss the following in pairs"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31abf2f4de59','ch_1283323d7754','text','{"text": "1. Empathy and understanding are going out of modern society. The individual experiences intense alienation from the society around him or her."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9dda21158374','ch_1283323d7754','text','{"text": "2. Behind the public face of the people in various occupations is a whole saga of personal suffering and joy which they wish to share with others."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_183468a5bbe9','ch_1283323d7754','heading','{"level": 2, "text": "Appreciation"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd8631127f78','ch_1283323d7754','text','{"text": "1. The story begins with a description of the setting. How does this serve as a fitting prelude to the events described in the story?"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08472f6208ec','ch_1283323d7754','text','{"text": "2. Comment on the graphic detail with which the various passengers who took Iona’s cab are described."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42c573e3c5b9','ch_1283323d7754','text','{"text": "3. This short story revolves around a single important event. Discuss how the narrative is woven around this central fact."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab4ea211795a','ch_1283323d7754','text','{"text": "4. The story begins and ends with Iona and his horse. Comment on the significance of this to the plot of the story."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1626d5e5dd9c','ch_1283323d7754','text','{"text": "*********"}',93);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_e96fc089ea3e','bk_ncert_english','11-2-a-pair-of-mustachios','11.2 A Pair of Mustachios',NULL,'public',42,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df3339cc7c3e','ch_e96fc089ea3e','text','{"text": "There are various kinds of mustachios worn in my country to mark the boundaries between the various classes of people."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_818bbf4e2497','ch_e96fc089ea3e','text','{"text": "Outsiders may think it stupid to lay down, or rather to raise, lines of demarcation of this kind, but we are notorious in the whole world for sticking to our queer old conventions, prides and prejudices, even as the Chinese or the Americans or, for that matter, the English… And, at any rate, some people may think it easier and more convenient to wear permanent boundary-lines, like mustachios, which only need a smear of grease to keep them bright and shiny, rather than to wear frock coats, striped trousers and top hats, which constantly need to be laundered and dry-cleaned, and the maintenance of which is already leading to the bankruptcy of the European ruling classes. With them clothes make the man but, to us, mustachios make the man. So we prefer the various styles of mustachios to mark the differences between the classes. And very unique and poetical symbols they are too. For instance, there is the famous lion moustache, the fearsome upstanding symbol of that great order of resplendent rajas, maharajas, nawabs and English army generals who are so well known for their devotion to the King Emperor. Then there is the tiger moustache, the uncanny, several-pointed moustache worn by the unbending, unchanging survivals from the ranks of the feudal gentry who have nothing left but pride in their greatness and a few mementoes of past glory, scrolls of honour granted by the former emperors, a few gold trinkets, heirlooms and bits of land. Next there is the goat moustache—a rather unsure brand, worn by the nouveau riche, the new commercial bourgeoisie and the shopkeeper class who somehow don’t belong—an indifferent, thin little line of a moustache, worn so that its tips can be turned up or down as the occasion demands—a show of power to some coolie or humility to a prosperous client. There is the Charlie Chaplin moustache worn by the lower middle class, by clerks and professional men, a kind of half-and-half affair, deliberately designed as a compromise between the traditional full moustache and the clean-shaven Curzon cut of the sahibs like them to keep mustachios at all. There is the sheep moustache of the coolies and the lower orders, the mouse moustache of the peasants, and so on. In fact, there are endless styles of mustachios, all appropriate to the wearers and indicative of the various orders, as rigorously adhered to as if they had all been patented by the Government of India or had been sanctioned by special appointment with His Majesty, the King, or Her Majesty, the Queen. And any poaching on the style of one class by members of another is resented, and the rising ratio of murders in my country is interpreted by certain authorities as being indicative of the increasing jealousy with which each class is guarding its rights and privileges in regard to the mark of the mustachio. Of course, the analysis of the expert is rather too abstract and not all the murders can be traced to this cause but, certainly, it is true that the preferences of the people in regard to their mustachios are causing a lot of trouble in our parts. For instance, there was a rumpus in my own village the other day about a pair of mustachios. It so happened that Seth Ramanand, the grocer and moneylender, who had been doing well out of the recent fall in the price of wheat by buying up whole crops cheap from the hard-pressed peasants and then selling them at higher prices, took it into his head to twist the goat moustache, integral to his order and position in society, at the tips, so that it looked nearly like a tiger moustache. Nobody seemed to mind very much because most of the mouse-moustached peasants in our village are beholden to the local moneylender, either because they owe him interest on a loan, or an instalment on a mortgage of jewellery or land. Besides, the Seth had been careful enough to twist his moustache so that it seemed nearly, though not quite, like a tiger moustache. But there lives in the vicinity of our village, in an old dilapidated Moghul style house, a mussulman named Khan Azam Khan, who claims descent from an ancient Afghan family whose heads were noblemen and councillors in the court of the great Moghuls. Khan Azam Khan, a tall, middleaged man, is a handsome and dignified person, and he wears a tiger moustache and remains adorned with the faded remnants of a gold-brocaded waistcoat, though he hasn’t even a patch of land left. Some people, notably the landlord of our village and the moneylender, maliciously say that he is an impostor, and that all his talk about his blue blood is merely the bluff of a rascal. Others, like the priest of the temple, concede that his ancestors were certainly attached to the Court of the Great Moghuls, but as sweepers. The landlord, the moneylender and the priest are manifestly jealous of anyone’s long ancestry, however, because they have all risen from nothing—and it is obvious from the stately ruins around Khan Azam Khan what grace was once his and his forefathers. Only Khan Azam Khan’s pride is greatly in excess of his present possessions and he is inordinately jealous of his old privileges and rather foolish and headstrong in safeguarding every sacred brick of his tottering house against vandalism. Khan Azam Khan happened to go to the moneylender’s shop to pawn his wife’s gold nose-ring one morning and he noticed the upturning tendency of the hair on Ramanand’s upper lip which made the moneylender’s goat moustache look almost like his own tiger moustache."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7bed88540cc','ch_e96fc089ea3e','text','{"text": "‘Since when have the lentil-eating shopkeepers become noblemen?’ he asked sourly."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_069d45d7c5af','ch_e96fc089ea3e','text','{"text": "‘I don’t know what you mean, Khan’, Ramanand answered."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b9c4a184843','ch_e96fc089ea3e','text','{"text": "‘You know what I mean, seed of a donkey!’ said the Khan."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7c6bb8af8d8','ch_e96fc089ea3e','text','{"text": "Look at the way you have turned the tips of your moustache upwards. It almost looks like my tiger moustache. Turn the tips down to the style proper to the goat that you are! Fancy the airs of people nowadays!’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f5843c8807a','ch_e96fc089ea3e','text','{"text": "‘Oh, Khan, don’t get so excited,’ said the moneylender, who was nothing if he was not amenable, having built up his business on the maxim that the customer is always right."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6808a99c4909','ch_e96fc089ea3e','text','{"text": "‘I tell you, turn the tip of your moustache down if you value your life!’ raged Khan Azam Khan."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14fd699c6f1d','ch_e96fc089ea3e','text','{"text": "‘If that is all the trouble, here you are’, said Ramanand, brushing one end of his moustache with his oily hand so that it dropped like a dead fly."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e789cf7c848c','ch_e96fc089ea3e','text','{"text": "‘Come, show me the trinkets. How much do you want for them?’ Now that Khan Azam Khan’s pride was appeased, he was like soft wax in the merchant’s sure hand. His need, and the need of his family, for food, was great and he humbly accepted the value which the moneylender put on his wife’s nose-ring. But as he was departing, after negotiating his business, he noticed that though one end of the moneylender’s moustache had come down at his behest, the other end was still up."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c33e9195671f','ch_e96fc089ea3e','text','{"text": "‘A strange trick you have played on me, you swine,’ the Khan said."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edf9a065a0df','ch_e96fc089ea3e','text','{"text": "‘I have paid you the best value for your trinket, Khan, that any moneylender will pay in these parts,’ he said, ‘especially in these days when the sarkars of the whole world are threatening to go off the gold standard.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d3445128468','ch_e96fc089ea3e','text','{"text": "‘It has nothing to do with the trinket,’ said Azam Khan, ‘but one end of your moustache is still up like my tiger moustache though you have brought down the other to your proper goat’s style."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a20bbd79f97e','ch_e96fc089ea3e','text','{"text": "Bring that other end down also so that there is no aping by your moustache of mine.’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4549a9a546b','ch_e96fc089ea3e','text','{"text": "‘Now Khan,’ said the moneylender, ‘I humbled myself because you are doing business with me."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dd69ef2aa47','ch_e96fc089ea3e','text','{"text": "You can’t expect me to become a mere worm just because you have pawned a trinket with me. If you were pledging some more expensive jewellery I might consider obliging you a little more. Anyhow, my humble milk-skimmer doesn’t look a bit like your valiant tiger moustache.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4467ab02ba48','ch_e96fc089ea3e','text','{"text": "‘Bring that tip down!’ Khan Azam Khan roared, for, the more he had looked at the moneylender’s moustache the more the still upturned tip seemed to him like an effort at an imitation of his own."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fecd816b7ed','ch_e96fc089ea3e','text','{"text": "‘Now, be sensible, Khan,’ the moneylender said, waving his hand with an imperturbable calm."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e95f7c8f68a','ch_e96fc089ea3e','text','{"text": "‘I tell you, turn that tip down or I shall wring your neck,’ said the Khan."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_066c53c8d559','ch_e96fc089ea3e','text','{"text": "‘All right, the next time you come to do business with me, I shall bring that tip down,’ answered the moneylender cunningly."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_714cc6ad521f','ch_e96fc089ea3e','text','{"text": "‘That is fair,’ said Chaudhary Chottu Ram, the landlord of the village, who was sitting under the tree opposite."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba14dba93c06','ch_e96fc089ea3e','text','{"text": "‘To be sure! To be sure!’ some peasants chimed in sheepishly."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6448bf78f1aa','ch_e96fc089ea3e','text','{"text": "Khan Azam Khan managed to control his murderous impulses and walked away. But he could not quell his pride, the pride of generations of his ancestors who had worn the tiger moustache as a mark of their high position. To see the symbol of his honour imitated by a moneylender—this was too much for him. He went home and fetched a necklace which had come down to his family through seven generations and, placing it before the moneylender, said:"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a07e9ba12c0f','ch_e96fc089ea3e','text','{"text": "‘Now will you bring that tip of your moustache down?’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcd219ad62c4','ch_e96fc089ea3e','text','{"text": "‘By all means, Khan,’ said the moneylender."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37de8f9fabeb','ch_e96fc089ea3e','text','{"text": "‘But let us see about this necklace. How much do you want for it?’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f6519005919','ch_e96fc089ea3e','text','{"text": "‘Any price will do, so long as you bring the tip of your moustache down,’ answered Azam Khan. After they had settled the business, the moneylender said:"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ad21a2162de','ch_e96fc089ea3e','text','{"text": "‘Now Khan, I shall carry out your will.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26731a0fd33f','ch_e96fc089ea3e','text','{"text": "And he ceremoniously brushed the upturned tip of his moustache down. As Azam Khan was walking away, however, he noticed that the other tip of the moneylender’s moustache had now gone up and stood dubiously like the upturned end of his own exalted tiger moustache. He turned on his feet and shouted:"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b203ad0850a','ch_e96fc089ea3e','text','{"text": "‘I shall kill you if you don’t brush that moustache into the shape appropriate to your position as a lentil-eating moneylender!’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdbfa654ab17','ch_e96fc089ea3e','text','{"text": "‘Now, now, Khan, come to your senses. You know it is only the illusion of a tiger’s moustache and nowhere like your brave and wonderful adornment,’ said the greasy moneylender."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7333c5d9915','ch_e96fc089ea3e','text','{"text": "‘I tell you I won’t have you insulting the insignia of my order!’ shouted Azam Khan."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f133a51f0afe','ch_e96fc089ea3e','text','{"text": "‘You bring that tip down!’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c917914751ea','ch_e96fc089ea3e','text','{"text": "‘I wouldn’t do it, Khan, even if you pawned all the jewellery you possess to me,’ said the moneylender."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4cf102eedfb5','ch_e96fc089ea3e','text','{"text": "‘I would rather lose all my remaining worldly possessions, my pots and pans, my clothes, even my house, than see the tip of your moustache turned up like that!’ spluttered Azam Khan."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5cbd378757d7','ch_e96fc089ea3e','text','{"text": "‘Achcha, if you care so little for all your goods and chattels you sell them to me and then I shall turn that tip of my moustache down,’ said the moneylender."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3482f2f262be','ch_e96fc089ea3e','text','{"text": "‘And what is more, I shall keep it flat. Now, is that a bargain?’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af99b6638f95','ch_e96fc089ea3e','text','{"text": "‘That seems fair enough,’ said the landlord from under the tree where he was preparing for a siesta."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64d558192054','ch_e96fc089ea3e','text','{"text": "‘But what proof have I that you will keep your word?’ said Azam Khan."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbb076dc261a','ch_e96fc089ea3e','text','{"text": "‘You oily lentil-eaters never keep your promises.’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1565e7376f7d','ch_e96fc089ea3e','text','{"text": "‘We shall draw up a deed, here and now,’ said the moneylender."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb9322905878','ch_e96fc089ea3e','text','{"text": "‘And we shall have it signed by the five elders of the village who are seated under that tree. What more do you want?’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0557c5ed00d7','ch_e96fc089ea3e','text','{"text": "‘Now, there is no catch in that,’ put in the landlord."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41b0f374c333','ch_e96fc089ea3e','text','{"text": "‘I and four other elders will come to court as witnesses on your behalf if he doesn’t keep his moustache to the goat style ever afterwards.’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7427bba04c0','ch_e96fc089ea3e','text','{"text": "‘I shall excommunicate him from religion if he doesn’t keep his word,’ added the priest, who had arrived on the scene on hearing the hubbub."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82347275051c','ch_e96fc089ea3e','text','{"text": "‘Achcha,’ agreed Azam Khan. And he forthwith had a deed prepared by the petition writer of the village, who sat smoking his hubble-bubble under the tree. And this document, transferring all his household goods and chattels, was signed in the presence of the five elders of the village and sealed. And the moneylender forthwith brought both tips of his moustache down and kept them glued in the goat style appropriate to his order."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aee55e9afdb3','ch_e96fc089ea3e','text','{"text": "Only, as soon as Khan Azam Khan’s back was turned he muttered to the peasants seated nearby:"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2346890b478','ch_e96fc089ea3e','text','{"text": "‘My father was a Sultan.’"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54debcc01b79','ch_e96fc089ea3e','text','{"text": "And they laughed to see the Khan give a special twist to his moustache as he walked away maintaining the valiant uprightness to the symbol of his ancient and noble family, though he had become a pauper"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9bf27a2f1d38','ch_e96fc089ea3e','list','{"ordered": false, "items": ["Mulk Raj Anand"]}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35da79ae506a','ch_e96fc089ea3e','heading','{"level": 2, "text": "About The Author"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b194e9ba78fa','ch_e96fc089ea3e','text','{"text": "Mulk Raj Anand (1905–2004), one of the most celebrated Indian novelists who wrote in English, was born in Peshawar and educated at the universities of Lahore, London and Cambridge."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ff3e5405a27','ch_e96fc089ea3e','text','{"text": "His novels include The Untouchable, Coolie, The Sword and the Sickle, Private Life of an Indian Prince, Seven Summers and"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aba38f9bfb67','ch_e96fc089ea3e','text','{"text": "Morning Face. He also published a number of short stories which reveal a lively sense of humour, a keen eye for the pretensions of the people and a feeling of warm compassion."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a94d67289974','ch_e96fc089ea3e','heading','{"level": 2, "text": "Suggested Reading"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bebe3ed4e36d','ch_e96fc089ea3e','text','{"text": "1. The Barber’s Trade Union and Other Stories by Mulk Raj Anand."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78ee067f9abb','ch_e96fc089ea3e','text','{"text": "Read and Enjoy"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b19a18faf0f','ch_e96fc089ea3e','heading','{"level": 2, "text": "May The Best Beard Win"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04422c6d2606','ch_e96fc089ea3e','text','{"text": "HANDLEBAR HEROES: There were men with Fu Manchu moustaches and contestants with long flowing Gandalf beards."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7fb3cb2a790f','ch_e96fc089ea3e','text','{"text": "Some 220 contestants from all over the world have gathered in Berlin for Saturday’s biannual world beard and moustache championships."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82003785c850','ch_e96fc089ea3e','text','{"text": "THE WACKIER THE BETTER: German Elmar Weisser supports a Brandenburg Gate on his chin. Countryman Juergen Reinl’s spikes give porcupines a complex. And, finally, grandpa Willi Chevalier is in a class of his own."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3524a1cbcbb2','ch_e96fc089ea3e','text','{"text": "BUT BEAT THIS SANTA : Entrants in the freestyle section turned up with Christmas tree beards."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8dbf1516641f','ch_e96fc089ea3e','text','{"text": "From the Hindustan Times, 2-10-05."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a6de1ae0ecd','ch_e96fc089ea3e','text','{"text": "*********"}',64);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_c34b2a455f84','bk_ncert_english','11-3-the-rocking-horse-winner','11.3 The Rocking-horse Winner',NULL,'public',43,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2931d3a4b135','ch_c34b2a455f84','text','{"text": "There was a woman who was beautiful, who started with all the advantages, yet she had no luck. She married for love and love turned to dust. She had bonny children, yet, she felt they had been thrust upon her and she could not love them. They looked at her coldly as if they were finding fault with her."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5104fb721fea','ch_c34b2a455f84','text','{"text": "And hurriedly she felt she must cover up some fault in herself. Yet what it was that she must cover up she never knew. Nevertheless, when her children were present, she always felt the centre of her heart go hard. This troubled her and, in her manner, she was all the more gentle and anxious for her children as if she loved them very much. Only she herself knew that at the centre of her heart was a hard little place that could not feel love, no, not for anybody. Everybody else said of her:"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03b123792b9d','ch_c34b2a455f84','text','{"text": "‘She is such a good mother. She adores her children.’"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ca36ae657b1','ch_c34b2a455f84','text','{"text": "Only she herself, and her children themselves, knew it was not so. They read it in each other’s eyes. There were a boy and two little girls. They lived in a pleasant house, with a garden, and they had discreet servants, and felt themselves superior to anyone in the neighbourhood. Although they lived in style, they felt always an anxiety in the house. There was never enough money."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a0eb95d98c3','ch_c34b2a455f84','text','{"text": "The mother had a small income and the father had a small income but not nearly enough for the social position which they had to keep up. The father went into town to some office. But though he had good prospects, these prospects never materialised. There was always the grinding sense of the shortage of money though the style was always kept up. At last the mother said:"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a63582914b62','ch_c34b2a455f84','text','{"text": "‘I will see if I can’t make something.’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_139c5fabb7bb','ch_c34b2a455f84','text','{"text": "But she did not know where to begin. She racked her brains, and tried this thing and the other but could not find anything successful. The failure made deep lines come into her face. Her children were growing up; they would have to go to school. There must be more money, there must be more money. The father, who was always very handsome and expensive in his tastes, seemed as if he never would be able to do anything worth doing."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce270dd07f8c','ch_c34b2a455f84','text','{"text": "And the mother, who had a great belief in herself, did not succeed any better, and her tastes were just as expensive. And so the house came to be haunted by the unspoken phrase:"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9120fda0f26a','ch_c34b2a455f84','text','{"text": "‘There must be more money! There must be more money!’ The children could hear it all the time, though nobody said it aloud."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_284fa168d986','ch_c34b2a455f84','text','{"text": "They heard it at Christmas, when expensive and splendid toys filled the nursery. Behind the shining modern rocking-horse, behind the smart doll’s house, a voice would start whispering:"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_862e185d6c78','ch_c34b2a455f84','text','{"text": "‘There must be more money! There must be more money!’ And the children would stop playing, to listen for a moment."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_829e4b186c65','ch_c34b2a455f84','text','{"text": "They would look into each other’s eyes to see if they had all heard. And each one saw in the eyes of the other two that they too had heard."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ee4df02be7d','ch_c34b2a455f84','text','{"text": "‘There must be more money! There must be more money!’ It came whispering from the springs of the still-swaying rocking-horse and even the horse, bending his wooden, champing head, heard it."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92a04766bdb8','ch_c34b2a455f84','text','{"text": "The big doll, sitting so pink and smirking in her new pram, could hear it quite plainly and seemed to be smirking all the more self-consciously because of it. The foolish puppy, too, that took the place of the teddy-bear, he was looking so extraordinarily foolish for no other reason but that he heard the secret whisper all over the house:"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7dac8299e71','ch_c34b2a455f84','text','{"text": "‘There must be more money!’ Yet nobody ever said it aloud."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c732a9904f1','ch_c34b2a455f84','text','{"text": "The whisper was everywhere and therefore no one spoke it. Just as no one ever says"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d2308cd189a','ch_c34b2a455f84','text','{"text": "‘we are breathing’ in spite of the fact that breath is coming and going all the time."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da882630d6c6','ch_c34b2a455f84','text','{"text": "‘Mother,’ said the boy Paul one day, ‘why don’t we keep a car of our own? Why do we always use uncle’s, or else a taxi?’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_491c670af630','ch_c34b2a455f84','text','{"text": "‘Because we’re the poor members of the family,’ said the mother."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83e970426151','ch_c34b2a455f84','text','{"text": "‘But why are we, mother?’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_245feb6c9bc7','ch_c34b2a455f84','text','{"text": "‘Well—I suppose,’ she said slowly and bitterly, ‘it’s because your father has no luck.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2402162398e5','ch_c34b2a455f84','text','{"text": "The boy was silent for some time."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd9ac26f7b0b','ch_c34b2a455f84','text','{"text": "‘Is luck money, mother?’ he asked, rather timidly."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ded20dce18fd','ch_c34b2a455f84','text','{"text": "‘No, Paul, not quite. It’s what causes you to have money.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98511dea515a','ch_c34b2a455f84','text','{"text": "‘Oh!’, said Paul vaguely."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8a7fbfdcf0b','ch_c34b2a455f84','text','{"text": "‘I thought when Uncle Oscar said filthy lucre, it meant money.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8cc16a41c086','ch_c34b2a455f84','text','{"text": "‘Filthy lucre does mean money,’ said the mother."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b60059881b9','ch_c34b2a455f84','text','{"text": "‘But it’s lucre, not luck.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e43846de6d42','ch_c34b2a455f84','text','{"text": "‘Oh,’ said the boy."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c713c6e2bcee','ch_c34b2a455f84','text','{"text": "‘Then what is luck, mother?’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8feabc21ec96','ch_c34b2a455f84','text','{"text": "‘It’s what causes you to have money. If you’re lucky you have money. That’s why it’s better to be born lucky than rich. If you’re rich, you may lose your money. But if you’re lucky, you will always get more money.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de86cd570b18','ch_c34b2a455f84','text','{"text": "‘Oh! Will you? And is father not lucky?’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85a391bf42fc','ch_c34b2a455f84','text','{"text": "‘Very unlucky, I should say,’ she said bitterly."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4777adc6de14','ch_c34b2a455f84','text','{"text": "The boy watched her with unsure eyes."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ead7235f2a61','ch_c34b2a455f84','text','{"text": "‘Why?’ he asked."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fedd0dc27a0c','ch_c34b2a455f84','text','{"text": "‘I don’t know."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54ff246f45dd','ch_c34b2a455f84','text','{"text": "Nobody ever knows why one person is lucky and another unlucky.’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3a69e18da97','ch_c34b2a455f84','text','{"text": "‘Do they? Nobody at all? Does nobody know?’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b94f1da3e42c','ch_c34b2a455f84','text','{"text": "‘Perhaps God. But He never tells.’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af4f64707f10','ch_c34b2a455f84','text','{"text": "‘He ought to, then. And aren’t you lucky either, mother?’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6e35fb97be4','ch_c34b2a455f84','text','{"text": "‘I can’t be, if I married an unlucky husband.’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2322decca80f','ch_c34b2a455f84','text','{"text": "‘But by yourself, aren’t you?’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb71ad2790fe','ch_c34b2a455f84','text','{"text": "‘I used to think I was, before I married. Now I think I am very unlucky indeed.’"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b47cc51fa97c','ch_c34b2a455f84','text','{"text": "‘Why?’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1128bf22d48','ch_c34b2a455f84','text','{"text": "‘Well—never mind! Perhaps I’m not really,’ she said."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8f68c0dff14','ch_c34b2a455f84','text','{"text": "The child looked at her to see if she meant it. But he saw, by the lines of her mouth, that she was only trying to hide something from him."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1566f202a6f1','ch_c34b2a455f84','text','{"text": "‘Well, anyhow,’ he said stoutly, ‘I’m a lucky person.’"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ffaa8b57620','ch_c34b2a455f84','text','{"text": "‘Why?’ said his mother, with a sudden laugh. He stared at her. He didn’t even know why he had said it."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d722225f9f6','ch_c34b2a455f84','text','{"text": "‘God told me,’ he asserted, brazening it out."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98a70655182e','ch_c34b2a455f84','text','{"text": "‘1 hope He did, dear,’ she said, again with a laugh, but rather bitter."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4836110d82e','ch_c34b2a455f84','text','{"text": "‘He did, mother!’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ada9e4a4b499','ch_c34b2a455f84','text','{"text": "‘Excellent!’ said the mother, using one of her husband’s exclamations. The boy saw she did not believe him; or rather, that she paid no attention to his assertion. This angered him somewhat and made him want to compel her attention. He went off by himself, vaguely, in a childish way, seeking for the clue to"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68b4db6b20a0','ch_c34b2a455f84','text','{"text": "‘luck’. Absorbed, taking no heed of other people, he went about with a sort of stealth, seeking inwardly for luck. He wanted luck. He wanted it, he wanted it. When the two girls were playing dolls in the nursery, he would sit on his big rocking-horse, charging madly into space, with a frenzy that made the little girls peer at him uneasily. Wildly the horse careered. The waving dark hair of the boy tossed, his eyes had a strange glare in them. The little girls dared not speak to him."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9c38047cc9b','ch_c34b2a455f84','text','{"text": "When he had ridden to the end of his mad little journey, he climbed down and stood in front of his rocking-horse, staring fixedly into its lowered face. Its red mouth was slightly open, its big eye was wide and glassy-bright."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b547dcc2703a','ch_c34b2a455f84','text','{"text": "‘Now!’ he would silently command the snorting steed."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d7b8c872f5c','ch_c34b2a455f84','text','{"text": "‘Now, take me to where there is luck. Now take me!’ And he would slash the horse on the neck with the little whip he had asked Uncle Oscar for. He knew the horse could take him to where there was luck if only he forced it. So he would mount again and start on his furious ride, hoping at last to get there. He knew he could get there."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc3eee3f1b57','ch_c34b2a455f84','text','{"text": "‘You’ll break your horse, Paul!’ said the nurse."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b8d15542a86','ch_c34b2a455f84','text','{"text": "‘He’s always riding like that, I wish he’d leave off ’, said his sister, Joan. But he only glared down on them in silence. Nurse gave him up. She could make nothing of him. Anyhow, he was growing beyond her. One day his mother and his Uncle Oscar came in when he was on one of his furious rides. He did not speak to them."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c95fe0474ff','ch_c34b2a455f84','text','{"text": "‘Hello, you young jockey! Riding a winner?’ said his uncle."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a55cc2030f9e','ch_c34b2a455f84','text','{"text": "‘Aren’t you growing too big for a rocking-horse? You’re not a very little boy any longer, you know,’ said his mother. But Paul only gave a blue glare from his big, rather close-set eyes. He would speak to nobody when he was in full tilt. His mother watched him with an anxious expression on her face. At last he suddenly stopped forcing his horse into the mechanical gallop and slid down."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1693dfec2faa','ch_c34b2a455f84','text','{"text": "‘Well, I got there,’ he announced fiercely, his blue eyes still flaring and his sturdy long legs straddling apart."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5224522678f8','ch_c34b2a455f84','text','{"text": "‘Where did you get to?’ asked his mother."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9d3d5250fe0','ch_c34b2a455f84','text','{"text": "‘Where I wanted to go,’ he flared back at her."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d43663740af','ch_c34b2a455f84','text','{"text": "‘That’s right, son!’ said Uncle Oscar, ‘Don’t you stop till you get there. What’s the horse’s name?’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_725009905dcc','ch_c34b2a455f84','text','{"text": "‘He doesn’t have a name,’ said the boy."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0565954466d8','ch_c34b2a455f84','text','{"text": "‘Gets on without all right?’ asked the uncle."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c05d53bfa55','ch_c34b2a455f84','text','{"text": "‘Well, he has different names. He was called Sansovino last week.’"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3404a1913ff3','ch_c34b2a455f84','text','{"text": "‘Sansovino, eh? Won the Ascot. How did you know his name?’"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f5914626fd6','ch_c34b2a455f84','text','{"text": "‘He always talks about horse-races with Bassett,’ said Joan."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94d7fc51a6b8','ch_c34b2a455f84','text','{"text": "The uncle was delighted to find that his small nephew was posted with all the racing news. Bassett, the young gardener, who had been wounded in the left foot in the war and had got his present job through Oscar Cresswell whose batman he had been, was a perfect blade of the"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_508aa150e8fe','ch_c34b2a455f84','text','{"text": "‘turf’. He lived in the racing events, and the small boy lived with him. Oscar Cresswell got it all from Bassett."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69811a2a9a3f','ch_c34b2a455f84','text','{"text": "‘Master Paul comes and asks me so I can’t do more than tell him, sir,’ said Bassett, his face terribly serious, as if he were speaking of religious matters."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba085d953e56','ch_c34b2a455f84','text','{"text": "‘And does he ever put anything on a horse he fancies?’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2f4a54bfbfc','ch_c34b2a455f84','text','{"text": "‘Well—I don’t want to give him away—he’s a young sport, a fine sport, sir."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4261c1979765','ch_c34b2a455f84','text','{"text": "Would you mind asking himself? He sort of takes a pleasure in it and perhaps he’d feel I was giving him away, sir, if you don’t mind.’"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8e0e16215c6','ch_c34b2a455f84','text','{"text": "Bassett was serious as a church. The uncle went back to his nephew and took him off for a ride in the car."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7e06eb1395b','ch_c34b2a455f84','text','{"text": "‘Say, Paul, old man, do you ever put anything on a horse?’ the uncle asked."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1e42bc05bce','ch_c34b2a455f84','text','{"text": "The boy watched the handsome man closely."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8a2622f1f88','ch_c34b2a455f84','text','{"text": "‘Why, do you think I oughtn’t to?’ he parried."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8eda028839b8','ch_c34b2a455f84','text','{"text": "‘Not a bit of it! I thought perhaps you might give me a tip for the Lincoln.’"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7da2820d677','ch_c34b2a455f84','text','{"text": "The car sped on into the country, going down to Uncle Oscar’s place in Hampshire."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0555d3df288f','ch_c34b2a455f84','text','{"text": "‘Honour bright?’ said the nephew."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30ef37361906','ch_c34b2a455f84','text','{"text": "‘Honour bright, son!’ said the uncle."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a836b5cd6f2e','ch_c34b2a455f84','text','{"text": "‘Well, then, Daffodil.’"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7164019b3de5','ch_c34b2a455f84','text','{"text": "‘Daffodil! I doubt it, sonny. What about Mirza?’"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe61c4c12521','ch_c34b2a455f84','text','{"text": "‘I only know the winner,’ said the boy."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_673c6193f876','ch_c34b2a455f84','text','{"text": "‘That’s Daffodil.’"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d5f0b3b66d4','ch_c34b2a455f84','text','{"text": "‘Daffodil, eh?’ There was a pause."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3851c017302e','ch_c34b2a455f84','text','{"text": "Daffodil was an obscure horse comparatively."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20b988c4b7c8','ch_c34b2a455f84','text','{"text": "‘Uncle!’"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_652f10b2215e','ch_c34b2a455f84','text','{"text": "‘Yes, son?’"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcf13da23056','ch_c34b2a455f84','text','{"text": "‘You won’t let it go any further, will you? I promised Bassett.’"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c31cbba47d5a','ch_c34b2a455f84','text','{"text": "‘Bassett be damned, old man! What’s he got to do with it?’"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab02f3a15c9e','ch_c34b2a455f84','text','{"text": "‘We’re partners. We’ve been partners from the first. Uncle, he lent me my first five shillings which I lost. I promised him. Honour bright, it was only between me and him; only you gave me that ten-shilling note I started winning with so I thought you were lucky. You won’t let it go any further, will you?’ The boy gazed at his uncle from those big, hot, blue eyes, set rather close together. The uncle stirred and laughed uneasily."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e7ca38a7867','ch_c34b2a455f84','text','{"text": "‘Right you are, son! I’ll keep your tip private. Daffodil, eh? How much are you putting on him?’"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ab1e646303c','ch_c34b2a455f84','text','{"text": "‘All except twenty pounds,’ said the boy."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c45cdba46239','ch_c34b2a455f84','text','{"text": "‘I keep that in reserve.’"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_286403743a9c','ch_c34b2a455f84','text','{"text": "The uncle thought it a good joke."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d897a8a3bd64','ch_c34b2a455f84','text','{"text": "‘You keep twenty pounds in reserve, do you, you young romancer? What are you betting, then?’ I’m betting three hundred,’ said the boy gravely."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_123c45c158a8','ch_c34b2a455f84','text','{"text": "‘But it’s between you and me Uncle Oscar! Honour bright?’ The uncle burst into a roar of laughter."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f6e00559748','ch_c34b2a455f84','text','{"text": "‘It’s between you and me all right, you young Nat Gould,’ he said, laughing."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79ae7e5e680c','ch_c34b2a455f84','text','{"text": "‘But where’s your three hundred?’"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a3270406655','ch_c34b2a455f84','text','{"text": "‘Bassett keeps it for me. We’re partners.’"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c21c24abcc17','ch_c34b2a455f84','text','{"text": "‘You are, are you? And what is Bassett putting on Daffodil?’"}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95424cdfc84a','ch_c34b2a455f84','text','{"text": "‘He won’t go quite as high as I do, I expect."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8517b1ab3f73','ch_c34b2a455f84','text','{"text": "Perhaps he’ll go a hundred and fifty.’"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f03c7cc9471e','ch_c34b2a455f84','text','{"text": "‘What pennies?’ laughed the uncle."}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83deae3f0bae','ch_c34b2a455f84','text','{"text": "‘Pounds,’ said the child, with a surprised look at his uncle."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbcca02dcf79','ch_c34b2a455f84','text','{"text": "‘Bassett keeps a bigger reserve than I do.’"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6000bef0415d','ch_c34b2a455f84','text','{"text": "Between wonder and amusement, Uncle Oscar was silent. He pursued that matter no further but he determined to take his nephew with him to the Lincoln races."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc7a82b044f9','ch_c34b2a455f84','text','{"text": "‘Now, son,’ he said, ‘I’m putting twenty on Mirza and I’ll put five on for you on any horse you fancy. What’s your pick?’"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2cb4620b55f4','ch_c34b2a455f84','text','{"text": "‘Daffodil, uncle.’"}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_566033f6eb7d','ch_c34b2a455f84','text','{"text": "‘No, not the fiver on Daffodil.’"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f925d22536e','ch_c34b2a455f84','text','{"text": "‘I should if it was my own fiver,’ said the child."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_757c9df79939','ch_c34b2a455f84','text','{"text": "‘Good! Good! Right you are! A fiver for me and a fiver for you on Daffodil.’"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb6e7a088cf3','ch_c34b2a455f84','text','{"text": "The child had never been to a race-meeting before, and his eyes were blue fire. He pursed his mouth tight and watched. A Frenchman, just in front, had put his money on Lancelot. Wild with excitement, he flayed his arms up and down, yelling"}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4c5d02a6f09','ch_c34b2a455f84','text','{"text": "‘Lancelot! Lancelot!’ in his French accent."}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e7298caf05e','ch_c34b2a455f84','text','{"text": "Daffodil came in first, Lancelot second, Mirza third. The child, flushed and with eyes blazing, was curiously serene. His uncle brought him four five-pound notes, four to one."}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_559126a48df8','ch_c34b2a455f84','text','{"text": "‘What am I to do with these?’ he cried, waving them before the boy’s eyes."}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a55293889a5c','ch_c34b2a455f84','text','{"text": "‘I suppose we’ll talk to Bassett,’ said the boy."}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b98ceb6e4de','ch_c34b2a455f84','text','{"text": "‘I expect I have fifteen hundred now and twenty in reserve; and this twenty.’"}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be540cb8376b','ch_c34b2a455f84','text','{"text": "His uncle studied him for some moments."}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0177dfe914c','ch_c34b2a455f84','text','{"text": "‘Look here, son!’ he said, ‘You’re not serious about Bassett and that fIfteen hundred, are you?’"}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8510726d5c75','ch_c34b2a455f84','text','{"text": "‘Yes, I am. But it’s between you and me, uncle. Honour bright?’"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d396849f69f7','ch_c34b2a455f84','text','{"text": "‘Honour bright all right, son! But I must talk to Bassett.’"}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21463a583180','ch_c34b2a455f84','text','{"text": "‘If you’d like to be a partner, uncle, with Bassett and me, we could all be partners."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a8c755b132d','ch_c34b2a455f84','text','{"text": "Only, you’d have to promise, Honour bright, uncle, not to let it go beyond us three. Bassett and I are lucky, and you must be lucky, because it was your ten shillings I started winning with...’"}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_317984f3f97c','ch_c34b2a455f84','text','{"text": "Uncle Oscar took both Bassett and Paul into Richmond Park for an afternoon, and there they talked."}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8353f076bd79','ch_c34b2a455f84','text','{"text": "‘It’s like this, you see, sir,’ Bassett said."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec5ce20a4ab5','ch_c34b2a455f84','text','{"text": "‘Master Paul would get me talking about racing events, spinning yarns, you know, sir. And he was always keen on knowing if I’d made or if I’d lost. It’s about a year since now that I put five shillings on Blush of Dawn for him; and we lost. Then the luck turned, with that ten shillings he had from you:"}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9331491265b6','ch_c34b2a455f84','text','{"text": "that we put on Singhalese. And since that time, it’s been pretty steady, all things considering."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ec25a5d7910','ch_c34b2a455f84','text','{"text": "‘What do you say, Master Paul?’"}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5b9f907ed27','ch_c34b2a455f84','text','{"text": "‘We’re all right when we’re sure,’ said Paul."}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aefc748d84be','ch_c34b2a455f84','text','{"text": "‘It’s when we’re not quite sure that we go down.’"}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67cc4c66f6e7','ch_c34b2a455f84','text','{"text": "‘Oh, but we’re careful then,’ said Bassett."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_836447acd727','ch_c34b2a455f84','text','{"text": "‘But when are you sure?’ smiled Uncle Oscar."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3793169f0cc7','ch_c34b2a455f84','text','{"text": "‘It’s Master Paul, sir,’ said Bassett in a secret, religious voice."}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_267b3d9bc9b6','ch_c34b2a455f84','text','{"text": "‘It’s as if he had it from heaven. Like Daffodil, now, for the Lincoln. That was as sure as eggs.’"}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76ad6e91eccd','ch_c34b2a455f84','text','{"text": "‘Did you put anything on Daffodil?’ asked Oscar Cresswell."}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e4864e5e78a','ch_c34b2a455f84','text','{"text": "‘Yes, sir. I made my bit.’"}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c766a0fbb7c9','ch_c34b2a455f84','text','{"text": "‘And my nephew?’ Bassett was obstinately silent, looking at Paul."}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d0497623f73','ch_c34b2a455f84','text','{"text": "‘I made twelve hundred, didn’t I, Bassett? I told uncle I was putting three hundred on Daffodil.’"}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_747a88f274ae','ch_c34b2a455f84','text','{"text": "‘That’s right,’ said Bassett, nodding."}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6c54e6fdb64','ch_c34b2a455f84','text','{"text": "‘But where’s the money?’ asked the uncle."}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91d10fd4ce71','ch_c34b2a455f84','text','{"text": "‘I keep it safe locked up, sir. Master Paul, he can have it any minute he likes to ask for it.’"}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8f89d36a02b','ch_c34b2a455f84','text','{"text": "‘What, fifteen hundred pounds?’"}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b74fb45fb9c0','ch_c34b2a455f84','text','{"text": "‘And twenty. And forty, that is, with the twenty he made on the course.’"}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61dc65ed7b03','ch_c34b2a455f84','text','{"text": "‘It’s amazing,’ said the uncle."}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6402bad0add1','ch_c34b2a455f84','text','{"text": "‘If Master Paul offers you to be partners, sir, I would, if I were you:"}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19418509c805','ch_c34b2a455f84','text','{"text": "if you’ll excuse me,’ said Bassett."}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32f503d39783','ch_c34b2a455f84','text','{"text": "Oscar Cresswell thought about it."}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9a3a2687f04','ch_c34b2a455f84','text','{"text": "‘I’ll see the money,’ he said. They drove home again and, sure enough, Bassett came round to the garden-house with fifteen hundred pounds in notes. The twenty pounds reserve was left with Joe Gleen, in the Turf Commission deposit."}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8ea24173712','ch_c34b2a455f84','text','{"text": "‘You see, it’s all right, uncle, when I’m sure."}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3c6afa41b56','ch_c34b2a455f84','text','{"text": "Then we go strong, for all we’re worth. Don’t we, Bassett?’"}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15360883b01b','ch_c34b2a455f84','text','{"text": "‘We do that, Master Paul.’"}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d99e9e51c0d2','ch_c34b2a455f84','text','{"text": "‘And when are you sure?’ said the uncle, laughing."}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb144204d78b','ch_c34b2a455f84','text','{"text": "‘Oh, well, sometimes I’m absolutely sure, like about Daffodil,’ said the boy;"}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9010f93a09d3','ch_c34b2a455f84','text','{"text": "‘and sometimes I have an idea; and sometimes I haven’t even an idea, have I, Bassett? Then we’re careful, because we mostly go down.’"}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c5973d7b637','ch_c34b2a455f84','text','{"text": "‘You do, do you? And when you’re sure, like about Daffodil, what makes you sure, sonny?’"}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23a350220c79','ch_c34b2a455f84','text','{"text": "‘Oh, well, I don’t know,’ said the boy uneasily."}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f351668ee147','ch_c34b2a455f84','text','{"text": "‘I’m sure, you know, uncle; that’s all.’"}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1e7fe3008d3','ch_c34b2a455f84','text','{"text": "‘It’s as if he had it from heaven, sir,’ Bassett reiterated."}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f58168ab0aab','ch_c34b2a455f84','text','{"text": "‘I should say so!’ said the uncle."}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03efd4859e59','ch_c34b2a455f84','text','{"text": "But he became a partner. And when the Leger was coming on, Paul was"}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d4e3092ffc9','ch_c34b2a455f84','text','{"text": "‘sure’ about Lively Spark which was a quite inconsiderable horse. The boy insisted on putting a thousand on the horse, Bassett went for five hundred and Oscar Cresswell two hundred. Lively Spark came in first and the betting had been ten to one against him. Paul had made ten thousand."}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_750a72ac44a4','ch_c34b2a455f84','text','{"text": "‘You see,’ he said, ‘I was absolutely sure of him.’"}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9ceac33f0af','ch_c34b2a455f84','text','{"text": "Even Oscar Cresswell had cleared two thousand."}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ae391e7c48b','ch_c34b2a455f84','text','{"text": "‘Look here, son,’ he said, ‘this sort of thing makes me nervous.’"}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b8301146969','ch_c34b2a455f84','text','{"text": "‘It needn’t, uncle! Perhaps I shan’t be sure again for a long time.’"}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c0051bf412c','ch_c34b2a455f84','text','{"text": "‘But what are you going to do with your money?’ asked the uncle."}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6c82d3a8db5','ch_c34b2a455f84','text','{"text": "‘Of course,’ said the boy, ‘I started it for mother."}',171);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea41c01dc2aa','ch_c34b2a455f84','text','{"text": "She said she had no luck because father is unlucky, so I thought if I was lucky, it might stop whispering.’"}',172);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdbefc2824a4','ch_c34b2a455f84','text','{"text": "‘What might stop whispering?’"}',173);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b37dcd192922','ch_c34b2a455f84','text','{"text": "‘Our house. I hate our house for whispering.’"}',174);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7feb2fe160c9','ch_c34b2a455f84','text','{"text": "‘What does it whisper?’"}',175);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_167466704439','ch_c34b2a455f84','text','{"text": "‘Why—why—’ the boy fidgeted—‘why, I don’"}',176);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82a83de38f97','ch_c34b2a455f84','text','{"text": "t know. But it’s always short of money, you know, uncle.’"}',177);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2a2ee25d31c','ch_c34b2a455f84','text','{"text": "‘I know it, son, I know it.’"}',178);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b61640424525','ch_c34b2a455f84','text','{"text": "‘You know people send mother writs, don’t you, uncle?’"}',179);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48aa8197cf76','ch_c34b2a455f84','text','{"text": "‘I’m afraid I do,’ said the uncle."}',180);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01d49726dfd4','ch_c34b2a455f84','text','{"text": "‘And then the house whispers, like people laughing at you behind your back. It’s awful, that is why I thought if I was lucky—’"}',181);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_273edfdf8ae1','ch_c34b2a455f84','text','{"text": "‘You might stop it,’ added the uncle."}',182);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de527d33a374','ch_c34b2a455f84','text','{"text": "The boy watched him with big blue eyes that had an uncanny cold fire in them, and he said never a word."}',183);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a74d5f9bad47','ch_c34b2a455f84','text','{"text": "‘Well, then,’ said the uncle."}',184);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a800bbb54bec','ch_c34b2a455f84','text','{"text": "‘What are we doing?’"}',185);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_228998b55ce2','ch_c34b2a455f84','text','{"text": "‘I shouldn’t like mother to know I was lucky,’ said the boy."}',186);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_270f30600828','ch_c34b2a455f84','text','{"text": "‘Why not, son?’"}',187);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af52f6fa785d','ch_c34b2a455f84','text','{"text": "‘She’d stop me.’"}',188);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad4cc332b546','ch_c34b2a455f84','text','{"text": "‘I don’t think she would.’"}',189);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a25af00c9b9','ch_c34b2a455f84','text','{"text": "‘Oh!’—and the boy writhed in an odd way—‘I don’"}',190);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e49c849941cd','ch_c34b2a455f84','text','{"text": "t want her to know, uncle.’"}',191);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20bcbf5b1eeb','ch_c34b2a455f84','text','{"text": "‘All right, son! We’ll manage it without her knowing.’"}',192);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fead033f019','ch_c34b2a455f84','text','{"text": "They managed it very easily. Paul, at the other’s suggestion, handed over five thousand pounds to his uncle, who deposited it with the family lawyer, who was then to inform Paul’s mother that a relative had put five thousand pounds into his hands, which sum was to be paid out a thousand pounds at a time, on the mother’s birthday, for the next five years."}',193);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf658dc6c549','ch_c34b2a455f84','text','{"text": "‘So she’ll have a birthday present of a thousand pounds for five successive years,’ said Uncle Oscar."}',194);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3344c17524ad','ch_c34b2a455f84','text','{"text": "‘I hope it won’t make it all the harder for her later.’"}',195);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0daaaf28c112','ch_c34b2a455f84','text','{"text": "‘Paul’s mother had her birthday in November. The house had been"}',196);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a83930e2c9c','ch_c34b2a455f84','text','{"text": "‘whispering’ worse than ever lately and, even in spite of his luck, Paul could not bear up against it. He was very anxious to see the effect of the birthday letter telling his mother about the thousand pounds. When there were no visitors, Paul now took his meals with his parents as he was beyond the nursery control. His mother went into town nearly every day."}',197);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e964f4fbdbf','ch_c34b2a455f84','text','{"text": "She had discovered that she had an odd knack of sketching furs and dress materials, so she worked secretly in the studio of a friend who was the chief"}',198);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9e4d04d2314','ch_c34b2a455f84','text','{"text": "‘artist’ for the leading drapers. She drew the figures of ladies in furs and ladies in silk and sequins for the newspaper advertisements. This young woman artist earned several thousand pounds a year; but Paul’s mother only made several hundreds and she was again dissatisfied. She so wanted to be first in something, and she did not succeed, even in making sketches for drapery advertisements. She was down to breakfast on the morning of her birthday. Paul watched her face as she read her letters."}',199);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5aab77be11fc','ch_c34b2a455f84','text','{"text": "He knew the lawyer’s letter. As his mother read it, her face hardened and became more expressionless. Then, a cold determined look came on her mouth. She hid the letter under the pile of others and said not a word about it."}',200);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c291c29b464','ch_c34b2a455f84','text','{"text": "‘Didn’t you have anything nice in the post for your birthday, mother?’ said Paul."}',201);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ab7f375e295','ch_c34b2a455f84','text','{"text": "‘Quite moderately nice,’ she said, her voice cold and absent."}',202);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a0e02e477d9','ch_c34b2a455f84','text','{"text": "She went away to town without saying more. But in the afternoon Uncle Oscar appeared. He said Paul’s mother had had a long interview with the lawyer, asking if the whole five thousand could not be advanced at once, as she was in debt."}',203);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abdee3ea322f','ch_c34b2a455f84','text','{"text": "‘What do you think, uncle?’ said the boy."}',204);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5bbe820fb04','ch_c34b2a455f84','text','{"text": "‘I leave it to you, son.’"}',205);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd09b15353fa','ch_c34b2a455f84','text','{"text": "‘Oh, let her have it, then! We can get some more with the other,’ said the boy."}',206);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de7266f39f39','ch_c34b2a455f84','text','{"text": "‘A bird in the hand is worth two in the bush, laddie!’ said Uncle Oscar."}',207);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0197e410f282','ch_c34b2a455f84','text','{"text": "‘But I’m sure to know for the Grand National; or the Lincolnshire; or else the Derby."}',208);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b6c754fce6e','ch_c34b2a455f84','text','{"text": "I’m sure to know for one of them,’ said Paul. So Uncle Oscar signed the agreement and Paul’s mother touched the whole five thousand. Then something very curious happened. The voices in the house suddenly went mad, like a chorus of frogs on a spring evening. There were certain new furnishings, and Paul had a tutor. He was really going to Eton, his father’s school, in the following autumn. There were flowers in the winter and a blossoming of the luxury Paul’s mother had been used to."}',209);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f60d2c7df54','ch_c34b2a455f84','text','{"text": "And yet the voices in the house, behind the sprays of mimosa and almond-blossoms, and from under the piles of iridescent cushions, simply trilled and screamed in a sort of ecstasy:"}',210);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3262710936a','ch_c34b2a455f84','text','{"text": "‘There must be more money! Oh-h-h! There must be more money! Oh, now, now-w! Now-w-w there must be more money—more than ever! More than ever!’ It frightened Paul terribly."}',211);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_281842d4c413','ch_c34b2a455f84','text','{"text": "He studied away at his Latin and Greek with his tutor. But his intense hours were spent with Bassett. The Grand National had gone by; he had not"}',212);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e5963e3bc72','ch_c34b2a455f84','text','{"text": "‘known,’ and had lost a hundred pounds. Summer was at hand. He was in agony for the Lincoln. But even for the Lincoln he didn’t"}',213);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59cf64a7da4f','ch_c34b2a455f84','text','{"text": "‘know,’ and he lost fifty pounds. He became wild-eyed and strange as if something were going to explode in him."}',214);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea47e01b522e','ch_c34b2a455f84','text','{"text": "‘Let it alone, son! Don’t you bother about it,’ urged Uncle Oscar."}',215);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edfbff001afa','ch_c34b2a455f84','text','{"text": "But it was as if the boy couldn’t really hear what his uncle was saying."}',216);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e41e25c0fbe0','ch_c34b2a455f84','text','{"text": "‘I’ve got to know for the Derby! I’ve got to know for the Derby!’ the child reiterated, his big blue eyes blazing with a sort of madness. His mother noticed how overwrought he was. You’d better go to the seaside. Wouldn’t you like to go now to the seaside, instead of waiting? I think you’d better,’ she said, looking down at him anxiously, her heart curiously heavy because of him. But the child lifted his uncanny blue eyes."}',217);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a34f03557c20','ch_c34b2a455f84','text','{"text": "‘I couldn’t possibly go before the Derby, mother!’ he said."}',218);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02d86bbda49e','ch_c34b2a455f84','text','{"text": "‘I couldn’t possibly!’"}',219);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72a5024e553f','ch_c34b2a455f84','text','{"text": "‘Why not?’ she said, her voice becoming heavy when she was opposed."}',220);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df1934a2fcb6','ch_c34b2a455f84','text','{"text": "‘Why not? You can still go from the seaside to see the Derby with your Uncle Oscar, if that’s what you wish."}',221);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_678a1ca55efa','ch_c34b2a455f84','text','{"text": "No need for you to wait here. Besides, I think you care too much about these races. It’s a bad sign. My family had been a gambling family and you won’t know till you grow up how much damage it has done. But it has done damage. I shall have to send Bassett away and ask Uncle Oscar not to talk racing to you, unless you promise to be reasonable about it:"}',222);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08d5f38a7554','ch_c34b2a455f84','text','{"text": "go away to the seaside and forget it. You’re all nerves!’"}',223);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_683253a405ba','ch_c34b2a455f84','text','{"text": "‘I’ll do what you like, mother, so long as you don’t send me away till after the Derby’, the boy said."}',224);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99d0cd4b39b5','ch_c34b2a455f84','text','{"text": "‘Send you away from where? Just from this house?’"}',225);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cd4b7c6e796','ch_c34b2a455f84','text','{"text": "‘Yes,’ he said, gazing at her."}',226);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_206c5848be48','ch_c34b2a455f84','text','{"text": "‘Why, you curious child, what makes you care about this house so much, suddenly? I never knew you loved it.’"}',227);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec194050c775','ch_c34b2a455f84','text','{"text": "He gazed at her without speaking. He had a secret within a secret, something he had not divulged, even to Bassett or to his Uncle Oscar. But his mother, after standing undecided and a little bit sullen for some moments, said:"}',228);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7bc29becf75d','ch_c34b2a455f84','text','{"text": "‘Very well, then! Don’t go to the seaside till after the Derby, if you don’t wish it."}',229);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_425754ea56a5','ch_c34b2a455f84','text','{"text": "But promise me you won’t let your nerves go to pieces. Promise you won’t think so much about horse-racing and events, as you call them.’"}',230);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bf9d78d1a63','ch_c34b2a455f84','text','{"text": "‘Oh, no,’ said the boy casually."}',231);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9488cac9e354','ch_c34b2a455f84','text','{"text": "‘I won’t think much about them, mother."}',232);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c0ec9d1a9e1','ch_c34b2a455f84','text','{"text": "You needn’t worry. I wouidn’t worry, mother, if I were you.’"}',233);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c1a410d504c','ch_c34b2a455f84','text','{"text": "‘If you were me and I were you,’ said his mother, ‘I wonder what we should do!’"}',234);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c698fd0e0cc','ch_c34b2a455f84','text','{"text": "‘But you know you needn’t worry, mother, don’t you?’ the boy repeated."}',235);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f91cf1cf3a7f','ch_c34b2a455f84','text','{"text": "‘I should be awfully glad to know it,’ she said wearily."}',236);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2973585d21c9','ch_c34b2a455f84','text','{"text": "‘Oh, well, you can, you know, I mean, you ought to know, you needn’t worry,’ he insisted."}',237);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b9ab542bddf','ch_c34b2a455f84','text','{"text": "‘Ought I? Then I’ll see about it,’ she said."}',238);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce8fed5a5650','ch_c34b2a455f84','text','{"text": "Paul’s secret of secrets was his wooden horse, that which had no name. Since he was emancipated from a nurse and a nursery-governess, he had had his rockinghorse removed to his own bedroom at the top of the house."}',239);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_110aed4e3828','ch_c34b2a455f84','text','{"text": "‘Surely you’re too big for a rocking-horse’, his mother had remonstrated."}',240);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42f3899399a3','ch_c34b2a455f84','text','{"text": "‘Well, you see, mother, till I can have a real horse, I like to have some sort of animal about,’ had been his quaint answer."}',241);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02b54e7ce2b6','ch_c34b2a455f84','text','{"text": "‘Do you feel he keeps you company?’ She laughed."}',242);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f7c82dc60c8','ch_c34b2a455f84','text','{"text": "‘Oh, yes! He’s very good, he always keeps me company when I’m there,’ said Paul."}',243);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6362a8178fb1','ch_c34b2a455f84','text','{"text": "So the horse, rather shabby, stood in an arrested prance in the boy’s bedroom. The Derby was drawing near and the boy grew more and more tense. He hardly heard what was spoken to him, he was very frail, and his eyes were really uncanny. His mother had sudden strange seizures of uneasiness about him. Sometimes for half an hour, she would feel a sudden anxiety about him that was almost anguish. She wanted to rush to him at once and know that he was safe."}',244);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67cf467bc1a5','ch_c34b2a455f84','text','{"text": "Two nights before the Derby, she was at a big party in town, when one of her rushes of anxiety about her boy, her fIrstborn, gripped her heart till she could hardly speak. She fought with the feeling, might and main, for she believed in common sense. But it was too strong. She had to leave the dance and go downstairs to telephone to the country. The children’s nursery-governess was terribly surprised and startled at being rung up in the night."}',245);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b4fc4f454a3','ch_c34b2a455f84','text','{"text": "‘Are the children all right, Miss Wilmot?’"}',246);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18aa4362f023','ch_c34b2a455f84','text','{"text": "‘Oh yes, they are quite all right.’"}',247);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7fc1a1deb10','ch_c34b2a455f84','text','{"text": "‘Master Paul? Is he all right?’"}',248);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7173eff66af','ch_c34b2a455f84','text','{"text": "‘He went to bed as right as a trivet. Shall I run up and look at him?’"}',249);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ca668767eca','ch_c34b2a455f84','text','{"text": "‘No,’ said Paul’s mother reluctantly."}',250);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_368042902e47','ch_c34b2a455f84','text','{"text": "‘No. Don’t trouble. It’s all right. Don’t sit up. We shall be home fairly soon.’"}',251);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73f551050cb9','ch_c34b2a455f84','text','{"text": "She did not want her son’s privacy intruded upon."}',252);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ef3e7eaaad0','ch_c34b2a455f84','text','{"text": "‘Very good,’ said the governess."}',253);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16a69d4e29e4','ch_c34b2a455f84','text','{"text": "It was about one o’clock when Paul’s mother and father drove up to their house. All was still. Paul’s mother went to her room and slipped off her white fur cloak. She had told her maid not to wait up for her. She heard her husband downstairs, mixing a whisky and soda. And then, because of the strange anxiety at her heart, she stole upstairs to her son’s room. Noiselessly she went along the upper corridor."}',254);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2eb610ab5994','ch_c34b2a455f84','text','{"text": "Was there a faint noise? What was it? She stood, with arrested muscles, outside his door, listening. There was a strange, heavy and yet not loud noise. Her heart stood still. It was a soundless noise, yet rushing and powerful. Something huge in violent, hushed motion. What was it? What in God’s name was it? She ought to know. She felt that she knew the noise. She knew what it was. Yet she could not place it. She couldn’t say what it was. And on and on it went, like a madness."}',255);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_895557cd3ecf','ch_c34b2a455f84','text','{"text": "Softly, frozen with anxiety and fear, she turned the door handle. The room was dark. Yet in the space near the window, she heard and saw something move to and fro. She gazed in fear and amazement. Then suddenly she switched on the light and saw her son, in his green pyjamas, madly surging on the rockinghorse. The blaze of light suddenly lit him up, as he urged the wooden horse, and lit her up, as she stood, blonde, in her dress of pale green and crystal in the doorway."}',256);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50a4c75177e1','ch_c34b2a455f84','text','{"text": "‘Paul,’ she cried."}',257);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1045b8c619fd','ch_c34b2a455f84','text','{"text": "‘Whatever are you doing?’"}',258);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bdc6bb1aec3','ch_c34b2a455f84','text','{"text": "‘It’s Malabar!’ he screamed in a powerful, strange voice. It’s Malabar!’ His eyes blazed at her for one strange and senseless second, as he ceased urging his wooden horse. Then he fell with a crash to the ground and she, all her tormented motherhood flooding upon her, rushed to gather him up. But he was unconscious, and unconscious he remained, with some brain-fever. He talked and tossed, and his mother sat stonily by his side."}',259);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc2bc1d4dda4','ch_c34b2a455f84','text','{"text": "‘Malabar! It’s Malabar! Bassett! Bassett, I know! It’s Malabar!’ So the child cried, trying to get up and urge the rockinghorse that gave him his inspiration."}',260);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abebcbf91a38','ch_c34b2a455f84','text','{"text": "‘What does he mean by Malabar?’ asked the heartfrozen mother."}',261);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c5f1c24fa15','ch_c34b2a455f84','text','{"text": "‘I don’t know,’ said the father stonily."}',262);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84eb6fdb0f4c','ch_c34b2a455f84','text','{"text": "‘What does he mean by Malabar?’ she asked her brother Oscar."}',263);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_114282b63631','ch_c34b2a455f84','text','{"text": "‘It’s one of the horses running for the Derby,’ was the answer. And, in spite of himself, Oscar Cresswell spoke to Bassett, and himself put a thousand on Malabar:"}',264);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_358547bdb2ff','ch_c34b2a455f84','text','{"text": "at fourteen to one. The third day of the illness was critical:"}',265);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63f9b3d181a8','ch_c34b2a455f84','text','{"text": "they were waiting for a change. The boy, with his rather long, curly hair, was tossing ceaselessly on the pillow. He neither slept nor regained consciousness, and his eyes were like blue stones. His mother sat, feeling her heart had gone, turned actually into a stone."}',266);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43a8ad791527','ch_c34b2a455f84','text','{"text": "In the evening, Oscar Cresswell did not come, but Bassett sent a message, saying could he come up for a moment, just one moment? Paul’s mother was very angry at the intrusion but, on second thought, she agreed. The boy was the same. Perhaps Bassett might bring him to consciousness."}',267);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_826346f24615','ch_c34b2a455f84','text','{"text": "The gardener, a shortish fellow with a little brown moustache and sharp little brown eyes, tiptoed into the room, touched his imaginary cap to Paul’s mother, and stole to the bedside, staring with glittering, smallish eyes at the tossing, dying child."}',268);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddd918412246','ch_c34b2a455f84','text','{"text": "‘Master Paul,’ he whispered, ‘Master Paul! Malabar came in first all right, a clean win."}',269);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d97e6f6408a2','ch_c34b2a455f84','text','{"text": "I did as you told me. You’ve made over seventy thousand pounds, you have; you’ve got over eighty thousand. Malabar came in all right, Master Paul.’"}',270);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_729be5781c4d','ch_c34b2a455f84','text','{"text": "‘Malabar! Malabar! Did I say Malabar, mother? Did I say Malabar? Do you think I’m lucky, mother? I knew Malabar, didn’t I? Over eighty thousand pounds! I call that lucky, don’t you, mother? Over eighty thousand pounds! I knew, didn’t I know I knew? Malabar came in all right."}',271);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa2e776c3f0f','ch_c34b2a455f84','text','{"text": "If I ride my horse till I’m sure, then I tell you, Bassett, you can go as high as you like. Did you go for all you were worth, Bassett?"}',272);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ae55a9cea55','ch_c34b2a455f84','text','{"text": "‘I went a thousand on it, Master Paul.’"}',273);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bf6102a06a2','ch_c34b2a455f84','text','{"text": "‘I never told you, mother, that if I can ride my horse, and get there, then I’m absolutely sure—oh, absolutely mother, did I ever tell you? I am lucky!’"}',274);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86cfc4e1316b','ch_c34b2a455f84','text','{"text": "‘No, you never did,’ said his mother."}',275);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab0811a8d18e','ch_c34b2a455f84','text','{"text": "But the boy died in the night. And even as he lay dead, his mother heard her brother’s voice saying to her:"}',276);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc425572f49f','ch_c34b2a455f84','text','{"text": "‘My God, Hester, you’re eighty-odd thousand to the good, and a poor devil of a son to the bad."}',277);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5955d172a0a9','ch_c34b2a455f84','text','{"text": "But, poor devil, poor devil, he’s best gone out of a life where he rides his rocking-horse to find a winner.’"}',278);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2ce891c13f7','ch_c34b2a455f84','list','{"ordered": false, "items": ["D.H. Lawrence"]}',279);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_060134213316','ch_c34b2a455f84','heading','{"level": 2, "text": "About The Author"}',280);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e7e85a5cbd3','ch_c34b2a455f84','text','{"text": "D.H. Lawrence (1895–1930) was born in a mining village near Nottingham in England. His father was a coal miner and his mother a genteel and ambitious lady who had worked previously as a schoolmistress. Their conflicting interests had had a powerful impact on the physical and imaginative build-up of young Lawrence."}',281);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a574a2561f5a','ch_c34b2a455f84','text','{"text": "Lawrence wrote novels, poems, short stories, criticism and miscellaneous prose. His work, at its best, is marked by intensity of feeling, psychological insight and vivid evocation of events, places and nature."}',282);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c7d2dc9a92c','ch_c34b2a455f84','heading','{"level": 2, "text": "Understanding The Text"}',283);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_717bdfbacac7','ch_c34b2a455f84','text','{"text": "1. What was the reason for young Paul’s restlessness at the beginning of the story? How did it find expression?"}',284);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c3f12840fa2','ch_c34b2a455f84','text','{"text": "2. Why do you think Paul’s mother was not satisfied with the yearly birthday gift of 1,000 pounds for five years?"}',285);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9bba116872cc','ch_c34b2a455f84','text','{"text": "3. What was the reason for the anxiety of Paul’s mother as he grew older?"}',286);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42986fbfbb02','ch_c34b2a455f84','text','{"text": "4. Paul’s final bet made the family rich but cost him his life."}',287);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54468d6351b9','ch_c34b2a455f84','heading','{"level": 2, "text": "Talking About The Text"}',288);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cad47f5347cc','ch_c34b2a455f84','text','{"text": "1. ‘Luck is necessary for success in life’."}',289);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d82f3e29d20','ch_c34b2a455f84','text','{"text": "2. Although Paul’s mother liked to be rich she did not approve of betting on horses."}',290);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8d0e7ae8853','ch_c34b2a455f84','text','{"text": "3. What were the voices that Paul heard? Did they lead him to success in the real sense?"}',291);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4178022fb54','ch_c34b2a455f84','heading','{"level": 2, "text": "Language Work"}',292);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d39ff4d9e55e','ch_c34b2a455f84','text','{"text": "1. ‘A bird in hand is worth two in the bush’."}',293);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4212451862e5','ch_c34b2a455f84','text','{"text": "a. Explain the above statement in the literal sense."}',294);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea7d8f7d4896','ch_c34b2a455f84','text','{"text": "b. Explain it in the context in which it is mentioned in the story."}',295);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fadf756a2aef','ch_c34b2a455f84','text','{"text": "c. Is there a corresponding proverb in your own language?"}',296);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5efa1256134b','ch_c34b2a455f84','text','{"text": "2. Explain the following phrases"}',297);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c193c7eef27f','ch_c34b2a455f84','text','{"text": "? Sure as eggs"}',298);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4228535c97e','ch_c34b2a455f84','text','{"text": "? Spinning yarns"}',299);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e90adc6adc46','ch_c34b2a455f84','text','{"text": "? Turned to dust"}',300);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1489edd67c4a','ch_c34b2a455f84','text','{"text": "Use them in sentences of your own."}',301);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e73d09c09bd','ch_c34b2a455f84','text','{"text": "3. Given below is the dictionary meaning of"}',302);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b25b9a759c3','ch_c34b2a455f84','text','{"text": "Smirk : to smile in a silly or unpleasant way that shows that you are pleased with yourself."}',303);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70df9be1145e','ch_c34b2a455f84','text','{"text": "Look up the dictionary for the following words which are also related to facial expressions and write down the meaning of each"}',304);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba42a72f8d94','ch_c34b2a455f84','heading','{"level": 2, "text": "Suggested Reading"}',305);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b5dda626404','ch_c34b2a455f84','text','{"text": "1.\t‘Sun and Moon’ by Katherine Mansfield."}',306);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8afa15db2c7d','ch_c34b2a455f84','text','{"text": "*********"}',307);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_cbd22f8b3df4','bk_ncert_english','11-4-the-adventure-of-the-three-garridebs','11.4 The Adventure of the Three Garridebs',NULL,'public',44,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46f0f085c15d','ch_cbd22f8b3df4','text','{"text": "It may have been a comedy, or it may have been a tragedy. It cost one man his reason, it cost me a blood-letting, and it cost yet another man the penalties of the law. Yet there was certainly an element of comedy. Well, you shall judge for yourselves."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb94a3271372','ch_cbd22f8b3df4','text','{"text": "I remember the date very well, for, it was in the same month that Holmes refused a knighthood for services which may perhaps some day be described. I only refer to the matter in passing, for, in my position of partner and confidant I am obliged to be particularly careful to avoid any indiscretion. I repeat, however, that this enables me to fix the date, which was the latter end of June 1902, shortly after the conclusion of the South African War. Holmes had spent several days in bed, as was his habit from time to time, but he emerged that morning with a long foolscap document in his hand and a twinkle of amusement in his austere grey eyes."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1c2d77b5d52','ch_cbd22f8b3df4','text','{"text": "‘There is a chance for you to make some money, friend Watson,’ said he. ‘Have you ever heard the name of Garrideb?’ I admitted that I had not."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42e3f87ae7bd','ch_cbd22f8b3df4','text','{"text": "‘Well, if you can lay your hand upon a Garrideb, there’s money in it.’"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c1130e138f6','ch_cbd22f8b3df4','text','{"text": "‘Why?’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_003bb75475a6','ch_cbd22f8b3df4','text','{"text": "‘Ah, that’s a long story—rather a whimsical one, too. I don’t think in all our explorations of human complexities we have ever come upon anything more singular. The fellow will be here presently for cross-examination, so I won’t open the matter up till he comes. But meanwhile, that’s the name we want.’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04a073b2a409','ch_cbd22f8b3df4','text','{"text": "The telephone directory lay on the table beside me and I turned over the pages in a rather hopeless quest. But to my amazement there was this strange name in its due place. I gave a cry of triumph."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3052d3b89dfe','ch_cbd22f8b3df4','text','{"text": "Here you are Holmes! Here it is!’ Holmes took the book from my hand."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea7808199dac','ch_cbd22f8b3df4','text','{"text": "‘Garrideb, N.’ he read, ‘136, Little Ryder Street, W. Sorry to disappoint you, my dear Watson, but this is the man himself. That is the address upon his letter. We want another to match him.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_499afff67e65','ch_cbd22f8b3df4','text','{"text": "Mrs Hudson had come in with a card upon a tray. I took it up and glanced at it."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_936cbd92a471','ch_cbd22f8b3df4','text','{"text": "‘Why, here it is!’ I cried in amazement. ‘This is a different initial. John Garrideb, Counsellor at Law, Moorville, Kansas, U.S.A.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae23d3be4bbe','ch_cbd22f8b3df4','text','{"text": "Holmes smiled as he looked at the card. ‘I am afraid you must make yet another effort, Watson,’ said he. ‘This gentleman is also in the plot already, though I certainly did not expect to see him this morning. However, he is in a position to tell us a good deal which I want to know.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bc72d6bb8f1','ch_cbd22f8b3df4','text','{"text": "A moment later he was in the room. Mr John Garrideb, Counsellor at Law, was a short, powerful man with the round, fresh clean-shaven face characteristic of so many American men of affairs. The general effect was chubby and rather childlike, so that one received the impression of quite a young man with a broad set smile upon his face. His eyes, however, were arresting. Seldom in any human head have I seen a pair which bespoke a more intense inward life, so bright were they, so alert, so responsive to every change of thought. His accent was American but was not accompanied by any eccentricity of speech."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_334a745b4de8','ch_cbd22f8b3df4','text','{"text": "‘Mr Holmes?’ he asked, glancing from one to the other. ‘Ah, yes! Your pictures are not unlike  you, sir, if I may say so I believe you have had a letter from my namesake, Mr Nathan Garrideb, have you not?’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7629dd1f9f26','ch_cbd22f8b3df4','text','{"text": "‘Pray sit down,’ said Sherlock Holmes. We shall, I fancy, have a good deal to discuss.’ He took up his sheets of foolscap."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca6421139fce','ch_cbd22f8b3df4','text','{"text": "You are, of course, the Mr John Garrideb mentioned in this document. But surely you have been in England some time?’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1700015c27ef','ch_cbd22f8b3df4','text','{"text": "‘Why do you say that, Mr Holmes?’ I seemed to read sudden suspicion in those expressive eyes."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1f1dc6a31b2','ch_cbd22f8b3df4','text','{"text": "‘Your whole outfit is English.’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_737dfb441f54','ch_cbd22f8b3df4','text','{"text": "Mr Garrideb forced a laugh. ‘I’ve read of your tricks, Mr Holmes, but I never thought I would be the subject of them. Where do you read that?’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f3fe801860d','ch_cbd22f8b3df4','text','{"text": "‘The shoulder cut of your coat, the toes of your boots— could anyone doubt it?’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3eb21feed4c5','ch_cbd22f8b3df4','text','{"text": "‘Well, well, I had no idea I was so obvious a Britisher. But business brought me over here some time ago and so, as you say, my outfit is nearly all London. However, I guess your time is of value and we did not meet to talk about the cut of my socks. What about getting down to that paper you hold in your hand?’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7cd080053b6a','ch_cbd22f8b3df4','text','{"text": "Holmes had, in some way, ruffled our visitor, whose chubby face had assumed a far less amiable expression."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_224c574f0181','ch_cbd22f8b3df4','text','{"text": "‘Patience! Patience, Mr Garrideb!’ said my friend in a soothing voice. ‘Dr Watson would tell you that these little digressions of mine sometimes prove in the end to have some bearing on the matter. But why did Mr Nathan Garrideb not come with you?’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0165e4596b8','ch_cbd22f8b3df4','text','{"text": "‘Why did he ever drag you into it at all?’ asked our visitor, with a sudden outflame of anger. ‘What in thunder had you to do with it? Here was a bit of professional business between two gentlemen, and one of them must need call in a detective! I saw him this morning and he told me this fool-trick he had played on me, and that’s why I am here. But I feel bad about it, all the same.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94773e110a19','ch_cbd22f8b3df4','text','{"text": "‘There was no reflection upon you, Mr Garrideb. It was simply zeal upon his part to gain your end—an end which is, I understand, equally vital for both of you. He knew that I had means of getting information and, therefore, it was very natural that he should apply to me.’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_914aa1d36d9b','ch_cbd22f8b3df4','text','{"text": "Our visitor’s angry face gradually cleared."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0868763c5838','ch_cbd22f8b3df4','text','{"text": "‘Well, that puts it different,’ said he, ‘When I went to see him this morning and he told me he had sent for a detective, I just asked for your address and came right away. I don’t want police butting into a private matter. But if you are content just to help us find the man, there can be no harm in that.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f9edf7d93ebf','ch_cbd22f8b3df4','text','{"text": "‘Well, that is just how it stands,’ said Holmes. ‘And now, sir, since you are here, we had best have a clear account from your own lips. My friend here knows nothing of the details.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28e8bd638c1b','ch_cbd22f8b3df4','text','{"text": "Mr Garrideb surveyed me with not too friendly a gaze. ‘Need he know?’ he asked."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17bc64ad328d','ch_cbd22f8b3df4','text','{"text": "‘We usually work together.’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_590d5f50b1f9','ch_cbd22f8b3df4','text','{"text": "‘Well, there’s no reason it should be kept a secret. I’ll give you the facts as short as I can make them. If you came from Kansas I would not need to explain to you who Alexander Hamilton Garrideb was. He made his money in real estate and, afterwards, in the wheat pit at Chicago, but he spent it in buying up as much land as would make one of your counties, lying along the Arkansas River, west of Fort Dodge. It’s grazing land and lumber land and Arabic land and mineralised land, and just every sort of land that brings dollars to the man that owns it."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46e5f0f59d91','ch_cbd22f8b3df4','text','{"text": "‘He had no kith nor kin—or, if he had, I never heard of it. But he took a kind of pride in the queerness of his name. That was what brought us together. I was in the law at Topeka, and one day I had a visit from the old man and he was tickled to death to meet another man with his own name. It was his pet fad and he was dead set to find out if there were any more Garridebs in the world. ‘Find me another!’ said he. I told him I was a busy man and could not spend my life hiking round the world in search of Garridebs. ‘None the less,’ said he, ‘that is just what you will do if things pan out as I planned them.’ I thought he was joking, but there was a powerful lot of meaning in the words, as I was soon to discover."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af152efb81a4','ch_cbd22f8b3df4','text','{"text": "‘For he died within a year of saying them and he left a will behind him. It was the queerest will that has ever been filed in the State of Kansas. His property was divided into three parts and I was to have one on condition that I found two Garridebs who would share the remainder. It’s five million dollars for each if it is a cent, but we can’t lay a finger on it until we all three stand in a row."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c35930d523cd','ch_cbd22f8b3df4','text','{"text": "‘It was so big a chance that I just let my legal practice slide and I set forth looking for Garridebs. There is not one in the United States. I went through it, sir, with a finetoothed comb and never a Garrideb could I catch. Then I tried the old country. Sure enough there was the name in the London Telephone Directory. I went after him two days ago and explained the whole matter to him. But he is a lone man, like myself, with some women relations, but no men. It says three adult men in the will. So you see we still have a vacancy and if you can help to fill it we will be very ready to pay your charges.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b0d2f434057','ch_cbd22f8b3df4','text','{"text": "‘Well, Watson,’ said Holmes, with a smile, ‘I said it was rather whimsical, did I not? I should have thought, sir, that your obvious way was to advertise in the agony"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_690812c5f728','ch_cbd22f8b3df4','text','{"text": "columns of the papers.’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2a7a90d8433','ch_cbd22f8b3df4','text','{"text": "‘I have done that, Mr Holmes. No replies.’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24c01400531e','ch_cbd22f8b3df4','text','{"text": "‘Dear me! Well, it is certainly a most curious little problem. I may take a glance at it in my leisure. By the way, it is curious that you should have come from Topeka. I used to have a correspondent—he is dead now—old Dr Lysander Starr, who was Mayor in 1890.’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f9639cb75398','ch_cbd22f8b3df4','text','{"text": "‘Good old Dr Starr!’ said our visitor. ‘His name is still honoured. Well, Mr Holmes, I suppose all we can do is to report to you and let you know how we progress. I reckon you will hear within a day or two.’ With this assurance our American bowed and departed."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8dc670d50af0','ch_cbd22f8b3df4','text','{"text": "Holmes had lit his pipe, and he sat for some time with a curious smile upon his face."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d5b4c2b07f4','ch_cbd22f8b3df4','text','{"text": "‘Well?’ I asked at last."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7d9fde54ee1','ch_cbd22f8b3df4','text','{"text": "‘I am wondering, Watson—just wondering!’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf44e8e2ce8d','ch_cbd22f8b3df4','text','{"text": "‘At what?’"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_672ac642c762','ch_cbd22f8b3df4','text','{"text": "Holmes took his pipe from his lips."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_287df0c99348','ch_cbd22f8b3df4','text','{"text": "‘I was wondering, Watson, what on earth could be the object of this man in telling us such a rigmarole of lies. I nearly asked him so—for there are times when a brutal frontal attack is the best policy—but I judged it better to let him think he had fooled us. Here is a man with an English coat frayed at the elbow and trousers bagged at the knee with a year’s wear, and yet by this document and by his own account he is a provincial American lately landed in London. There have been no advertisements in the agony columns. You know that I miss nothing there. They are my favourite covert for putting up a bird and I would never have overlooked such a cock pheasant as that. I never knew a Dr Lysander Starr of Topeka. Touch him where you would he was false. I think the fellow is really an American, but he has worn his accent smooth with years of London. What is his game, then, and what motive lies behind this preposterous search for Garridebs? It’s worth our attention, for, granting that the man is a rascal, he is certainly a complex and ingenious one. We must now find out if our other correspondent is a fraud also. Just ring him up, Watson.’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81727db2e8d2','ch_cbd22f8b3df4','text','{"text": "I did so, and heard a thin, quavering voice at the other end of the line."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c14f787fd064','ch_cbd22f8b3df4','text','{"text": "‘Yes, yes, I am Mr Nathan Garrideb. Is Mr Holmes there? I should very much like to have a word with Mr Holmes.’"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e1c3b33d4f3','ch_cbd22f8b3df4','text','{"text": "My friend took the instrument and I heard the usual syncopated dialogue."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be5917395ad7','ch_cbd22f8b3df4','text','{"text": "‘Yes, he has been here. I understand that you don’t know him… How long? Only two days!... Yes, yes, of course it is a most captivating prospect. Will you be at home this evening? I suppose your namesake will not be there?... Very good, we will come then, for I would rather have a chat without him… Dr Watson will come with me… I understood from your note that  you did not go out often… Well, we shall be round about six. You need not mention it to the American lawyer… Very good. Good-bye!’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f514da7314f4','ch_cbd22f8b3df4','text','{"text": "It was twilight of a lovely spring evening and even Little Ryder Street, one of the smaller offshoots from the Edgware Road, within a stone-cast of old Tyburn Tree of evil memory, looked golden and wonderful in the slanting rays of the setting sun. The particular house to which we were directed was a large, old-fashioned, Early Georgian edifice with a fat brick face broken only by two deep bay windows on the ground floor. It was on this ground floor that our client lived and, indeed, the low windows proved to be the front of the huge room in which he spent his waking hours. Holmes pointed as we passed to the small brass plate which bore the curious name."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92f345d01b04','ch_cbd22f8b3df4','text','{"text": "‘Up some years, Watson,’ he remarked, indicating its discoloured surface. ‘It’s his real name, anyhow, and that is something to note.’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6e50dee7832','ch_cbd22f8b3df4','text','{"text": "The house had a common stair and there were a number of names painted in the hall, some indicating offices and some private chambers. It was not a collection of residential flats, but rather the abode of Bohemian bachelors. Our client opened the door for us himself and apologised by saying that the woman in charge left at four o’clock. Mr Nathan Garrideb proved to be a very tall, loose jointed, round-backed person, gaunt and bald, some sixtyodd years of age. He had a cadaverous face, with the dull dead skin of a man to whom exercise was unknown. Large round spectacles and a small projecting goat’s beard combined with his stooping attitude to give him an expression of peering curiosity. The general effect, however, was amiable, though eccentric."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14f6afff8d82','ch_cbd22f8b3df4','text','{"text": "The room was as curious as its occupant. It looked like a small museum. It was both broad and deep, with cupboards and cabinets all round, crowded with specimens, geological and anatomical. Cases of butterflies and moths flanked each side of the entrance. A large table in the centre was  littered with all sorts of debris, while the tall brass tube of a powerful microscope bristled up amongst them. As I glanced round I was surprised at the universality of the man’s interests. Here was a case of ancient coins. There was a cabinet of flint instruments. Behind his central table was a large cupboard of fossil bones. Above was a line of plaster skulls with such names as ‘Neanderthal’,"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbf137de99da','ch_cbd22f8b3df4','text','{"text": "‘Heidelberg,’ ‘Cromagnan’ printed beneath them. It was clear that he was a student of many subjects. As he stood in front of us now, he held a piece of chamois leather in his right hand with which he was polishing a coin. ‘Syracusan—of the best period,’ he explained, holding it up. ‘They degenerated greatly towards the end. At their best I hold them supreme, though some prefer the Alexandrian school. You will find a chair here, Mr Holmes. Pray allow me to clear these bones. And you, sir—ah, yes, Dr Watson—if you would have the goodness to put the Japanese vase to one side. You see round me my little interests in life. My doctor lectures me about never going out, but why should I go out when I have so much to hold me here? I can assure you that the adequate cataloguing of one of those cabinets would take me three good months.’ Holmes looked round him with curiosity."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8d23f966031','ch_cbd22f8b3df4','text','{"text": "‘But do you tell me that you never go out?’ he said."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63e49aa7fcc6','ch_cbd22f8b3df4','text','{"text": "‘Now and again I drive down to Sotheby’s or Christie’s. Otherwise I very seldom leave my room. I am not too strong and my researches are very absorbing. But you can imagine, Mr Holmes, what a terrific shock—pleasant but terrific—it was for me when I heard of this unparalleled good fortune. It only needs one more Garrideb to complete the matter and surely we can find one; I had a brother, but he is dead, and female relatives are disqualified. But there must surely be others in the world. I had heard that you handled strange cases, and that was why I sent for you. Of course, this American gentleman is quite right, and I should have taken his advice first, but I acted for the best.’"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccb335940133','ch_cbd22f8b3df4','text','{"text": "‘I think you acted very wisely indeed,’ said Holmes."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5acb58b7440','ch_cbd22f8b3df4','text','{"text": "‘But are you really anxious to acquire an estate in America?’"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d46fcea6432','ch_cbd22f8b3df4','text','{"text": "‘Certainly not, sir. Nothing would induce me to leave my collection. But this gentleman has assured me that he will buy me out as soon as we have established our claim. Five million dollars was the sum named. There are a dozen specimens in the market at the present moment which fill gaps in my collection, and which I am unable to purchase for want of a few hundred pounds. Just think what I could do with five million dollars. Why, I have the nucleus of a national collection. I shall be the Hans Sloane of my age.’"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0aeab09a6585','ch_cbd22f8b3df4','text','{"text": "His eyes gleamed behind his great spectacles. It was very clear that no pains would be spared by Mr Nathan Garrideb in finding a namesake."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0c476e2aec6','ch_cbd22f8b3df4','text','{"text": "‘I merely called to make your acquaintance and there is no reason why I should interrupt your studies,’ said Holmes. ‘I prefer to establish personal touch with those with whom I do business. There are few questions I need ask, for I have your very clear narrative in my pocket and I filled up the blanks when this American gentleman called. I understand that up to this week you were unaware of his existence.’"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f5154f0f639','ch_cbd22f8b3df4','text','{"text": "‘That is so. He called last Tuesday.’"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ada9a567ece','ch_cbd22f8b3df4','text','{"text": "‘Did he tell you of our interview today?’"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89a99a6019d8','ch_cbd22f8b3df4','text','{"text": "‘Yes, he came straight back to me. He had been very angry.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f721caa2d57','ch_cbd22f8b3df4','text','{"text": "‘Why should he be angry?’"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_caf2dfe20dea','ch_cbd22f8b3df4','text','{"text": "‘He seemed to think it was some reflection on his honour. But he was quite cheerful again when he returned.’"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1e86c6528d0','ch_cbd22f8b3df4','text','{"text": "‘Did he suggest any course of action?’"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39d8b1cb5098','ch_cbd22f8b3df4','text','{"text": "‘No, sir, he did not.’"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7199000d5117','ch_cbd22f8b3df4','text','{"text": "‘Has he had, or asked for, any money from you?’"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_556c08842472','ch_cbd22f8b3df4','text','{"text": "‘No, sir, never!’"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22f424726793','ch_cbd22f8b3df4','text','{"text": "‘You see no possible object he has in view?’"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6162cbd8354','ch_cbd22f8b3df4','text','{"text": "‘None, except what he states.’"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_86ff9917ebd2','ch_cbd22f8b3df4','text','{"text": "‘Did you tell him of our telephone appointment?’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_951e4b4acbd1','ch_cbd22f8b3df4','text','{"text": "‘Yes, sir, I did.’"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bcbabd4d8d41','ch_cbd22f8b3df4','text','{"text": "Holmes was lost in thought. I could see that he was puzzled."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b630fe5560c2','ch_cbd22f8b3df4','text','{"text": "‘Have you any articles of great value in your collection?’"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a97f34357fdf','ch_cbd22f8b3df4','text','{"text": "‘No, sir. I am not a rich man. It is a good collection, but not a very valuable one.’"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba2f27772538','ch_cbd22f8b3df4','text','{"text": "‘You have no fear of burglars?’"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a0c2c3c6b86','ch_cbd22f8b3df4','text','{"text": "‘Not the least.’"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfac43532a29','ch_cbd22f8b3df4','text','{"text": "‘How long have you been in these rooms?’"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ad5b9be2277','ch_cbd22f8b3df4','text','{"text": "‘Nearly five years.’"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b58d59ae84f1','ch_cbd22f8b3df4','text','{"text": "Holmes’s cross-examination was interrupted by an imperative knocking at the door. No sooner had our client unlatched it than the American lawyer burst excitedly into the room."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1188d6de3f83','ch_cbd22f8b3df4','text','{"text": "‘Here you are!’ he cried, waving a paper over his head. ‘I thought I should be in time to get you. Mr Nathan Garrideb, my congratulations! You are a rich man, sir. Our business is happily finished and all is well. As to you, Mr Holmes, we can only say we are sorry if we have given you any useless trouble.’"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8591f651475','ch_cbd22f8b3df4','text','{"text": "He handed over the paper to our client, who stood staring at a marked advertisement. Holmes and I leaned forward and read it over his shoulder. This is how it ran—"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_005c17daafe1','ch_cbd22f8b3df4','heading','{"level": 2, "text": "Howard Garrideb"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0299eda5afcc','ch_cbd22f8b3df4','text','{"text": "Constructor of Agricultural Machinery. Binders, reapers’ steam and hand plows, drills, harrows, farmers’ carts, buck-boards, and all other appliances. Estimates for Artesian Wells. Apply Grosvenor Buildings, Aston."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90a50d75a20f','ch_cbd22f8b3df4','text','{"text": "‘Glorious!’ gasped our host. ‘That makes our third man.’"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c74cf4172400','ch_cbd22f8b3df4','text','{"text": "‘I had opened up inquiries in Birmingham,’ said the American, ‘and my agent there has sent me this advertisement from a local paper. We must hustle and put the thing through. I have written to this man and told him that you will see him in his office tomorrow afternoon at four o’clock.’"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ebb9842d9a5','ch_cbd22f8b3df4','text','{"text": "‘You want me to see him?’"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fde824a14a59','ch_cbd22f8b3df4','text','{"text": "‘What do you say, Mr Holmes? Don’t you think it would be wiser? Here am I, a wandering American with a wonderful tale. Why should he believe what I tell him? But you are a Britisher with solid references and he is bound to take notice of what you say. I would go with you if you wished, but I have a very busy day tomorrow and I could always follow you if you are in any trouble.’"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c11ba05110b4','ch_cbd22f8b3df4','text','{"text": "‘Well, I have not made such a journey for years.’"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8849778d3b5','ch_cbd22f8b3df4','text','{"text": "‘It is nothing, Mr Garrideb. I have figured out your connections. You leave at twelve and should be there soon after two. Then you can be back the same night. All you have to do is to see this man, explain the matter and get an affidavit of his existence. By the Lord!’ he added, hotly, ‘considering I’ve come all the way from the centre of America, it is surely little enough if you go a hundred miles in order to put this matter through.’"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf41f50b3e70','ch_cbd22f8b3df4','text','{"text": "‘Quite so,’ said Holmes. ‘I think what this gentleman says is very true.’"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1614e8ab46fc','ch_cbd22f8b3df4','text','{"text": "Mr Nathan Garrideb shrugged his shoulders with a disconsolate air. ‘Well, If you insist I shall go,’ said he. ‘It is certainly hard for me to refuse you anything, considering the glory of hope that you have brought into my life.’"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a95d2a48960f','ch_cbd22f8b3df4','text','{"text": "‘Then that is agreed,’ said Holmes, ‘and no doubt you will let me have a report as soon as you can.’"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c6c528d8340','ch_cbd22f8b3df4','text','{"text": "‘I’ll see to that,’ said the American. ‘Well,’ he added, looking at his watch, ‘I’ll have to get on. I’ll call tomorrow, Mr Nathan, and see you off to Birmingham. Coming my way, Mr Holmes? Well, then, good-bye and we may have good news for you tomorrow night.’"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e19e98049a21','ch_cbd22f8b3df4','text','{"text": "I noticed that my friend’s face cleared when the American left the room and the look of thoughtful perplexity had vanished."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_635eb7c3130c','ch_cbd22f8b3df4','text','{"text": "‘I wish I could look over your collection, Mr Garrideb,’ said he. ‘In my profession all sorts of odd knowledge comes useful and this room of yours is a storehouse of it.’"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31f108fe1391','ch_cbd22f8b3df4','text','{"text": "Our client shone with pleasure and his eyes gleamed from behind his big glasses."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb75ebc8134d','ch_cbd22f8b3df4','text','{"text": "‘I had always heard, sir, that you were a very intelligent man,’ said he. ‘I could take you round now, if you have the time.’"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84a6df2c5d05','ch_cbd22f8b3df4','text','{"text": "‘Unfortunately, I have not. But these specimens are so well labelled and classified that they hardly need your personal explanation. If I should be able to look in tomorrow, I presume that there would be no objection to my glancing over them?’"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74e835767af4','ch_cbd22f8b3df4','text','{"text": "‘None at all. You are most welcome. The place will, of course, be shut up, but Mrs Saunders is in the basement up to four o’clock and would let you in with her key.’"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc1f3f6c6ac6','ch_cbd22f8b3df4','text','{"text": "‘Well, I happen to be clear tomorrow afternoon. If you would say a word to Mrs Saunders it would be quite in order. By the way, who is your house-agent?’"}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0505fd63e25','ch_cbd22f8b3df4','text','{"text": "Our client was amazed at the sudden question."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04fdec49ea62','ch_cbd22f8b3df4','text','{"text": "‘Holloway and Steele, in the Edgware Road. But why?’"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f85599785e16','ch_cbd22f8b3df4','text','{"text": "‘I am a bit of an archaeologist myself when it comes to houses,’ said Holmes, laughing. ‘I was wondering if this was Queen Anne or Georgian.’"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46e1f4f51e5b','ch_cbd22f8b3df4','text','{"text": "‘Georgian, beyond doubt.’"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3cdab30a0fd','ch_cbd22f8b3df4','text','{"text": "‘Really. I should have thought a little earlier. However, it is easily ascertained. Well, good-bye, Mr Garrideb and may you have every success in your Birmingham journey.’ The house-agent’s was close by, but we found that it was closed for the day, so we made our way back to Baker Street. It was not till after dinner that Holmes reverted to the subject."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_756a78cdb7dc','ch_cbd22f8b3df4','text','{"text": "‘Our little problem draws to a close,’ said he. ‘No doubt you have outlined the solution in your own mind.’"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cf23ca1de85','ch_cbd22f8b3df4','text','{"text": "‘I can make neither head nor tail of it.’"}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0cf2733fb691','ch_cbd22f8b3df4','text','{"text": "‘The head is surely clear enough and the tail we should see tomorrow. Did you notice nothing curious about that advertisement?’"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb126b17d53b','ch_cbd22f8b3df4','text','{"text": "‘I saw that the word ‘plough’ was misspelt.’"}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d79e138f66f8','ch_cbd22f8b3df4','text','{"text": "‘Oh, you did notice that, did you? Come, Watson, you improve all the time. Yes, it was bad English but good American. The printer had set it up as received. Then the buckboards. That is American also. And artesian wells are commoner with them than with us. It was a typical American advertisement, but purporting to be from an English firm. What do you make of that?’"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63b90f973c50','ch_cbd22f8b3df4','text','{"text": "‘I can only suppose that this American lawyer put it in himself. What his object was I fail to understand.’"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_349e44b8df5b','ch_cbd22f8b3df4','text','{"text": "‘Well, there are alternative explanations. Anyhow, he wanted to get this good old fossil up to Birmingham. That is very clear. I might have told him that he was clearly going on a wild-goose chase, but, on second thoughts, it seemed better to clear the stage by letting him go. Tomorrow, Watson—well, tomorrow will speak for itself.’"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a5706fb227e','ch_cbd22f8b3df4','text','{"text": "Holmes was up and out early. When he returned at lunch-time I noticed  that his face was very grave."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_639418f9c3a9','ch_cbd22f8b3df4','text','{"text": "‘This is a more serious matter than I had expected, Watson,’ said he. ‘It is fair to tell you so, though I know it will only be an additional reason to you for running your head into danger. I should know my Watson by now. But there is danger, and you should know it.’"}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b3baf64e244','ch_cbd22f8b3df4','text','{"text": "‘Well, it is not the first we have shared, Holmes. I hope it may not be the last. What is the particular danger this time?’"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa24b8100e0e','ch_cbd22f8b3df4','text','{"text": "‘We are up against a very hard case. I have identified Mr John Garrideb, Counsellor at Law. He is none other than ‘Killer’ Evans, of sinister and murderous reputation.’"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_526991d5ae85','ch_cbd22f8b3df4','text','{"text": "‘I fear I am none the wiser.’"}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b31f7ee3d665','ch_cbd22f8b3df4','text','{"text": "‘Ah, it is not part of your profession to carry about a portable Newgate Calendar in your memory. I have been down to see friend Lestrade at the Yard. There may be an occasional want of imaginative intuition down there, but they lead the world for thoroughness and method. I had an idea that we might get on the track of our American friend in their records. Sure enough, I found his chubby face smiling up at me from the Rogues’ Portrait Gallery. James Winter, alias Morecroft, alias Killer Evans, was the inscription below.’ Holmes drew an envelope from his pocket. ‘I scribbled down a few points from his dossier. Aged forty four. Native of Chicago. Known to have shot three men in the States. Escaped from penitentiary through political influence. Came to London in 1893. Shot a man over cards in a night club in the Waterloo Road in January, 1895. Man died, but he was shown to have been the aggressor in the row. Dead man was identified as Rodger Presbury, famous as forger and coiner in Chicago. Killer Evans released in 1901. Has been under police supervision since, but so far as known has led an honest life. Very dangerous man, usually carries arms and is prepared to use them. That is our bird, Watson—a sporting bird, as you must admit.’"}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92af0ffdb3c1','ch_cbd22f8b3df4','text','{"text": "‘But what is his game?’"}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_435c5626a3b4','ch_cbd22f8b3df4','text','{"text": "‘Well, it begins to define itself. I have been to the houseagents. Our client, as he told us, has been there five years. It was unlet for a year before then. The previous tenant was a gentleman at large named Waldron. Waldron’s appearance was well remembered at the office. He had suddenly vanished and nothing more been heard of him. He was a tall, bearded man with very dark features. Now, Presbury, the man whom Killer Evans had shot, was, according to Scotland Yard, a tall, dark man with a beard. As a working hypothesis, I think we may take it that Presbury, the American criminal, used to live in the very room which our innocent friend now devotes to his museum."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b363323a424b','ch_cbd22f8b3df4','text','{"text": "So at last we get a link, you see.’"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_451379405ccd','ch_cbd22f8b3df4','text','{"text": "‘And the next link?’"}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb19e2a1c838','ch_cbd22f8b3df4','text','{"text": "‘Well, we must go now and look for that.’"}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b92138562896','ch_cbd22f8b3df4','text','{"text": "He took a revolver from the drawer and handed it to me."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7f3b112d95b','ch_cbd22f8b3df4','text','{"text": "‘I have my old favourite with me. If our Wild West friend tries to live up to his nickname, we must be ready for him. I’ll give you an hour for a siesta, Watson, and then I think it will be time for our Ryder Street adventure.’"}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7727f12256d5','ch_cbd22f8b3df4','text','{"text": "It was just four o’clock when we reached the curious apartment of Nathan Garrideb. Mrs Saunders, the caretaker, was about to leave but she had no hesitation in admitting us, for the door shut with a spring lock and Holmes promised to see that all was safe before we left. Shortly afterwards the outer door closed, her bonnet passed the bow window and we knew that we were alone in the lower floor of the house. Holmes made a rapid examination of the premises. There was one cupboard in a dark corner which stood out a little from the wall. It was behind this that we eventually crouched, while Holmes in a whisper outlined his intentions."}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7564949c788d','ch_cbd22f8b3df4','text','{"text": "‘He wanted to get our amiable friend out of his room— that is very clear and, as the collector never went out, it took some planning to do it. The whole of this Garrideb invention was apparently for no other end. I must say, Watson, that there is a certain devilish ingenuity about it, even if the queer name of the tenant did give him an opening which he could hardly have expected. He wove his plot with remarkable cunning.’"}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afca9436f8bf','ch_cbd22f8b3df4','text','{"text": "‘But what did he want?’"}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d977d4df3ec7','ch_cbd22f8b3df4','text','{"text": "‘Well, that is what we are here to find out. It has nothing whatever to do with our client, so far as I can read the situation. It is something connected with the man he murdered—the man who may have been his confederate in crime. There is some guilty secret in the room. That is how I read it. At first I thought our friend might have something in his collection more valuable than he knew—something worth the attention of a big criminal. But the fact that Rodger Presbury of evil memory inhabited these rooms points to some deeper reason. Well, Watson, we can but possess our souls in patience and see what the hour may bring.’"}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2af96901891','ch_cbd22f8b3df4','text','{"text": "That hour was not long in striking. We crouched closer in the shadow as we heard the outer door open and shut. Then came the sharp, metallic snap of a key and the American was in the room. He closed the door softly behind him, took a sharp glance around him to see that all was safe, threw off his overcoat and walked up to the central table with the brisk manner of one who knows exactly what he has to do and how to do it. He pushed the table to one side, tore up the square of carpet on which it rested, rolled it completely back and then, drawing a jimmy from his inside pocket, he knelt down and worked vigorously upon the floor. Presently we heard the sound of sliding boards and, an instant later, a square had opened in the planks. Killer Evans struck a match, lit a stump of candle, and vanished from our view."}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab5c17c93374','ch_cbd22f8b3df4','text','{"text": "Clearly our moment had come. Holmes touched my wrist as a signal and together we stole across to the open trapdoor. Gently as we moved, however, the old floor must have creaked under our feet, for the head of our American, peering anxiously round, emerged suddenly from the open space. His face turned upon us with a glare of baffled rage, which gradually softened into a rather shamefaced grin as he realised that two pistols were pointed at his head."}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac54e19dd6b4','ch_cbd22f8b3df4','text','{"text": "‘Well, well!’ said he, coolly as he scrambled to the surface. ‘I guess you have been one too many for me, Mr Holmes. Saw through my game, I suppose and played me for a sucker from the first. Well, sir, I hand it to you; you have me beat and—’"}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_740933f9219a','ch_cbd22f8b3df4','text','{"text": "In an instant he had whisked out a revolver from his breast  pocket and had fired two shots. I felt a sudden hot sear as if a red-hot iron had been pressed to my thigh. There was a crash as Holmes’s pistol came down on the man’s head. I had a vision of him sprawling upon the floor with blood running down his face while Holmes rummaged him for weapons. Then my friend’s wiry arms were round me and he was leading me to a chair."}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fee64cbb632d','ch_cbd22f8b3df4','text','{"text": "‘You’re not hurt, Watson? For God’s sake, say that you are not hurt!’"}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f8f0c84aea1','ch_cbd22f8b3df4','text','{"text": "It was worth a wound—it was worth many wounds—to know the depth of loyalty and love which lay behind that cold mask. The clear, hard eyes were dimmed for a moment and the firm lips were shaking. For the one and only time I caught a glimpse of a great heart as well as of a great brain. All my years of humble but single-minded service culminated in that moment of revelation."}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_81fd7f1e895d','ch_cbd22f8b3df4','text','{"text": "‘It’s nothing, Holmes. It’s a mere scratch.’"}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8caa2cc3b93d','ch_cbd22f8b3df4','text','{"text": "He had ripped up my trousers with his pocket-knife."}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5e72f00777d','ch_cbd22f8b3df4','text','{"text": "‘You are right,’ he cried, with an immense sigh of relief. ‘It is quite superficial.’ His face set like flint as he glared at our prisoner who was sitting up with a dazed face. ‘By the Lord, it is as well for you. If you had killed Watson, you would not have got out of this room alive. Now, sir, what have you to say for yourself?’"}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0eaa357aebc0','ch_cbd22f8b3df4','text','{"text": "He had nothing to say for himself. He only lay and scowled. I leaned on Holmes’s arm and together we looked down into the small cellar which had been disclosed by the secret flap. It was still illuminated by the candle which Evans had taken down with him. Our eyes fell upon a mass of rusted machinery, great rolls of paper, a litter of bottles and, neatly arranged upon a small table, a number of neat little bundles."}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_017a99deb554','ch_cbd22f8b3df4','text','{"text": "‘A printing press—a counterfeiter’s outfit,’ said Holmes."}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c3c37658bf7','ch_cbd22f8b3df4','text','{"text": "‘Yes, sir,’ said our prisoner, staggering slowly to his feet and then sinking into the chair. ‘The greatest counterfeiter London ever saw. That’s Presbury’s machine and those bundles on the table are two thousand of Presbury’s notes worth a hundred each and fit to pass anywhere. Help yourselves, gentlemen. Call it a deal and let me beat it.’"}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c3403268702','ch_cbd22f8b3df4','text','{"text": "Holmes laughed."}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65ddd8907db8','ch_cbd22f8b3df4','text','{"text": "‘We don’t do things like that, Mr Evans. There is no bolt-hole for you in this country. You shot this man, Presbury, did you not?’"}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d25bb753ef1a','ch_cbd22f8b3df4','text','{"text": "‘Yes, sir, and got five years for it, though it was he who pulled on me. Five years—when I should have had a medal the size of a soup plate. No living man could tell a Presbury from a Bank of England, and if I hadn’t put him out he would have flooded London with them. I was the only one in the world who knew where he made them. Can you wonder that I wanted to get to the place? And can you wonder that when I found this crazy boob of a bughunter with the queer name squatting right on the top of it, and never quitting his room, I had to do the best I could to shift him? Maybe I would have been wiser if I had put him away. It would have been easy enough, but I’m a soft-hearted guy that can’t begin shooting unless the other man has a gun also. But say, Mr Holmes, what have I done wrong, anyhow? I’ve not used this plant. I’ve not hurt this old stiff. Where do you get me?’"}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb0cfc01ad4b','ch_cbd22f8b3df4','text','{"text": "‘Only attempted murder, so far as I can see,’ said Holmes. ‘But that’s not our job. They take that at the next stage. What we wanted at present was just your sweet self. Please give the Yard a call, Watson. It won’t be entirely unexpected.’"}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efbda847327e','ch_cbd22f8b3df4','text','{"text": "So those were the facts about Killer Evans and his remarkable invention of the three Garridebs. We heard later that our poor old friend never got over the shock of his dissipated dreams. When his castle in the air fell down, it buried him beneath the ruins. He was last heard of at a nursing home in Brixton. It was a glad day at the Yard when the Presbury outfit was discovered for, though they knew that it existed, they had never been able, after the death of the man, to find out where it was. Evans had indeed done great service and caused several worthy CID men to sleep the sounder, for the counterfeiter stands in a class by himself as a public danger. They would willingly have subscribed to that soup-plate medal of which the criminal had spoken, but an unappreciative Bench took a less favourite view and the Killer returned to those shades from which he had just emerged."}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6602a6241d9a','ch_cbd22f8b3df4','list','{"ordered": false, "items": ["Arthur Conan Doyle"]}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49e18cd21462','ch_cbd22f8b3df4','heading','{"level": 2, "text": "About The Author"}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1693966925a','ch_cbd22f8b3df4','text','{"text": "Arthur Conan Doyle (1859–1930), who was a medical practitioner, is well known for his detective stories. His creations—the detective Sherlock Holmes and the chronicler, Dr Watson—are well known the world over. The collections of his short stories include The Adventures of Sherlock Holmes and The Return of Sherlock Holmes. The stories are full of suspense, excitement and humour. At the same time, they develop a structure of keen, analytical intelligence, with a deep human appeal."}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abfebd28a9ad','ch_cbd22f8b3df4','heading','{"level": 2, "text": "Understanding The Text"}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24ffd4ac1412','ch_cbd22f8b3df4','text','{"text": "1. What clues did Sherlock Holmes work upon to get at the fact that the story of the three Garridebs was a ruse?"}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c93f5ab755f','ch_cbd22f8b3df4','text','{"text": "2. What was John Garrideb’s objective in inventing the story of Alexander Hamilton Garrideb and his legacy?"}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e444c09694e7','ch_cbd22f8b3df4','text','{"text": "3. Why didn’t John Garrideb like the idea of including Holmes in the hunt for the third Garrideb?"}',156);
