INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d12b3bd84c2','ch_310674480970','text','{"text": "2. Within a few pages the author has packed the important events in the lives of John Ipe and his wife. Discuss how conciseness and economy of expression can achieve effective portrayal of entire lives."}',31);
