INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e57d4402b164','ch_310674480970','heading','{"level": 2, "text": "Reading For The Blind"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10a4d73ccd25','ch_310674480970','text','{"text": "Until 1819, learning material for the blind was provided by using letters of the alphabet made of wood, lead, twigs or, sometimes, pins arranged in large pincushions. The Royal Institute for Young Blind Persons in Paris used three-inch deep letters made from cloth."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_456bf4543d97','ch_310674480970','text','{"text": "In 1918, a ten year old blind boy named Louis Braille enrolled at the Institute. It was around this time that Captain Barbier de la Serre devised an alphabet of raised dots and dashes embossed on strips of cardboard. He called it ‘night writing’ because soldiers could use it to ‘read’ with their fingertips when in action at night."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53543295172d','ch_310674480970','text','{"text": "His system, however, was not a success because it was too complicated: it used an arrangement of twelve dots to each letter. Braille, now a teenager, became interested in this system. He simplified it and developed the present internationally used Braille system."}',36);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_1ad843ed6a0e','bk_ncert_english','11-6-the-third-and-final-continent','11.6 The Third and Final Continent',NULL,'public',46,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df38dcc435a3','ch_1ad843ed6a0e','text','{"text": "I left India in 1964 with a certificate in commerce and the equivalent, in those days, of ten dollars to my name. For three weeks I sailed on the SS Roma, an Italian cargo vessel, in a third-class cabin next to the ship’s engine, across the Arabian Sea, the Red Sea, the Mediterranean and, finally, to England. I lived in north London, in Finsbury Park, in a house occupied entirely by penniless Bengali bachelors like myself, at least a dozen and sometimes more, all struggling to educate and establish ourselves abroad."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c46f2aa7128e','ch_1ad843ed6a0e','text','{"text": "I attended lectures at the LSE and worked at the university library to get by. We lived three or four to a room, shared a single, icy toilet, and took turns cooking pots of egg curry, which we ate with our hands on a table covered with newspapers. Apart from our jobs we had few responsibilities. On weekends we lounged barefoot in drawstring pyjamas, drinking tea and smoking Rothmans, or set out to watch cricket at Lord’s. Some weekends the house was crammed with still more Bengalis to whom we had introduced ourselves at the greengrocer or on the Tube, and we made yet more egg curry, and played Mukesh on a Grundig reel-to-reel, and soaked our dirty dishes in the bathtub. Every now and then someone in the house moved out to live with a woman whom his family back in Calcutta had determined he was to wed. In 1969, when I was thirtysix years old, my own marriage was arranged. Around the same time, I was offered a full-time job in America, in the processing department of a library at MIT. The salary was generous enough to support a wife, and I was honoured to be  hired by a world-famous university, and so I obtained a sixth-preference green card and prepared to travel farther still."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bda3d935afc1','ch_1ad843ed6a0e','text','{"text": "By now I had enough money to go by plane. I flew first to Calcutta, to attend my wedding, and a week later I flew first to Boston, to begin my new job. During the flight I read The Student Guide to North America, a paperback volume that I’d bought before leaving London, for seven shillings six pence on Tottenham Court Road for, although I was no longer a student, I was on a budget all the same. I learned that Americans drove on the right side of the road, not the left, and that they called a lift an elevator and an engaged phone busy. ‘The pace of life in North America is different from Britain as you will soon discover,’ the guidebook informed me. ‘Everybody feels he must get to the top. Don’t expect an English cup of tea.’ As the plane began its descent over Boston Harbour, the pilot announced the weather and time, and that President Nixon had declared a national holiday: two American men had landed on the moon. Several passengers cheered. ‘God bless America!’ one of them hollered. Across the aisle, I saw a woman praying."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5162db9ab152','ch_1ad843ed6a0e','text','{"text": "I spent my first night at the YMCA in Central Square, Cambridge, an  inexpensive accommodation recommended by my guidebook. It was walking distance from MIT, and steps away from the post office and a supermarket called Purity Supreme. The room contained a cot, a desk and a small wooden cross on one wall. A sign on the door said cooking was strictly forbidden. A bare window overlooked Massachusetts Avenue, a major thoroughfare with traffic in both directions. Car horns, shrill and prolonged, blared one after another. Flashing sirens heralded endless emergencies and a fleet of buses rumbled past, their doors opening and closing with a powerful hiss, throughout the night. The noise was constantly distracting, at times suffocating. I felt it deep in my ribs, just as I had felt the furious drone of the engine on the SS Roma. But there was no ship’s deck to escape to, no glittering ocean to thrill my soul, no breeze to cool my face, no one to talk to. I was too tired to pace the gloomy corridors of the YMCA in my drawstring pyjamas. Instead I sat at the desk and stared out the window, at the city hall of Cambridge and a row of small shops. In the morning I reported to my job at the Dewey Library, a beige fortlike building by Memorial Drive. I also opened a bank account, rented a post office box, and bought a plastic bowl and a spoon at Woolworth’s, a store whose name I recognised  from London. I went to Purity Supreme, wandering up and down the aisles, converting ounces to grams and comparing prices to things in England. In the end I bought a small carton of milk and a box of cornflakes. This was my first meal in America. I ate it at my desk. I preferred it to hamburgers or hot dogs, the only alternative I could afford in the coffee shops on Massachusetts Avenue, and, besides, at the time I had yet to consume any beef. Even the simple chore of buying milk was new to me; in London we’d had bottles delivered each morning to our door."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f47b9c29b70','ch_1ad843ed6a0e','text','{"text": "In a week I had adjusted, more or less. I ate cornflakes and milk, morning and night, and bought some bananas for variety, slicing them into the bowl with the edge of my spoon. In addition I bought tea bags and a flask, which the salesman in Woolworth’s referred to as a thermos (a flask, he informed me, was used to store whiskey, another thing I had never consumed). For the price of one cup of tea at a coffee shop, I filled the flask with boiling water on my way to work each morning, and brewed the four cups I drank in the course of a day. I bought a larger carton of milk, and learned to leave it on the shaded part of the windowsill, as I had seen another resident at the YMCA do. To pass the time in the evenings I read the Boston Globe downstairs, in a spacious room with stained glass windows. I read every article and advertisement so that I would grow familiar with things and, when my eyes grew tired, I slept. Only I did not sleep well. Each night I had to keep the window wide open; it was the only source of air in the stifling room, and the noise was intolerable. I would lie on the cot with my fingers pressed into my ears but when I drifted off to sleep, my hands fell away and the noise of the traffic would wake me up again. Pigeon feathers drifted onto the windowsill and, one evening, when I poured milk over my cornflakes, I saw that it had soured. Nevertheless I resolved to stay at the YMCA for six weeks, until my wife’s passport and green card were ready. Once she arrived I would have to rent a proper apartment and so, from time to time, I studied the classified section of the newspaper, or stopped in at the housing office at MIT during my lunch-break, to see what was available in my price range. It was in this manner that I discovered a room, for immediate occupancy, in a house on a quiet street, the listing said, for eight dollars per week. I copied the number into my guidebook and dialled from a pay telephone, sorting through the coins with which I was still unfamiliar, smaller and lighter than shillings, heavier and brighter than paisas."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcba0f52a2db','ch_1ad843ed6a0e','text','{"text": "‘Who is speaking?’ a woman demanded. Her voice was bold and clamorous."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3db50cf05d90','ch_1ad843ed6a0e','text','{"text": "‘Yes, good afternoon, madame. I am calling about the room, for rent.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fde875c2d6c3','ch_1ad843ed6a0e','text','{"text": "‘Harvard or Tech?’"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b72da6300e5a','ch_1ad843ed6a0e','text','{"text": "‘I beg your pardon?’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bcd5255b688','ch_1ad843ed6a0e','text','{"text": "‘Are you from Harvard or Tech?’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57db5aeeee70','ch_1ad843ed6a0e','text','{"text": "Gathering that Tech referred to the Massachusetts Institute of Technology, I replied, ‘I work at Dewey Library’, adding tentatively, ‘at Tech’."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d164eea7286','ch_1ad843ed6a0e','text','{"text": "I was given an address and an appointment for seven o’clock that evening. Thirty minutes before the hour I set out, my guidebook in my pocket, my breath fresh with Listerine. I turned down a street shaded with trees, perpendicular to Massachusetts Avenue. Stray blades of grass poked between the cracks of the footpath. In spite of the heat I wore a coat and a tie, regarding the event as I would any other interview; I had never lived in the home of a person who was not Indian. The house, surrounded by a chain-link fence, was off-white with dark brown trim. Unlike the stucco row house I’d lived in, in London, this house, fully detached, was covered with wooded shingles, with a tangle of forsythia bushes plastered against the front and sides. When I pressed the calling bell, the woman with whom I had spoken on the phone hollered from what seemed to be just the other side of the door, ‘One minute please!’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abb738c99078','ch_1ad843ed6a0e','text','{"text": "Several minutes later the door was opened by a tiny, extremely old woman. A mass of snowy hair was arranged like a small sack on top of her head. As I stepped into the house, she sat down on a wooden bench positioned at the bottom of a narrow carpeted staircase. Once she was settled on the bench, in a small pool of light, she peered up at me with undivided attention. She wore a long black skirt that spread like a stiff tent to the floor, and a starched white shirt edged with ruffles at the throat and cuffs. Her hands, folded together in her lap, had long pallid fingers, with swollen knuckles and tough yellow nails. Age had battered her features so that she almost resembled a man, with sharp, shrunken eyes and prominent creases on either side of her nose. Her lips, chapped and faded, had nearly disappeared, and her eyebrows were missing altogether. Nevertheless she looked fierce."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1e463c8e5a7','ch_1ad843ed6a0e','text','{"text": "‘Look up!’ she commanded. She shouted even though I stood only a few feet away. ‘Fasten the chain and firmly press that button on the knob! This is the first thing you shall do when you enter, is that clear?’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00b98da581fb','ch_1ad843ed6a0e','text','{"text": "I locked the door as directed and examined the house. Next to the bench on which the woman sat was a small round table, its legs fully concealed, much like the woman’s, by a skirt of lace. The table held a lamp, a transistor radio, a leather change purse with a silver clasp and a telephone. A thick wooden cane coated with a layer of dust was propped against one side. There was a parlour to my right, lined with bookcases and filled with shabby claw-footed furniture. In the corner of the parlour I saw a grand piano with its top down, piled with papers. The piano’s bench was missing; it seemed to be the one on which the woman was sitting. Somewhere in the house a clock chimed seven times."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b16a669816e4','ch_1ad843ed6a0e','text','{"text": "‘You’re punctual!’ the woman proclaimed. ‘ I expect you shall be so with the rent!’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f58a131d0ad7','ch_1ad843ed6a0e','text','{"text": "‘I have a letter, madame.’ In my jacket pocket was a letter confirming my employment from MIT, which I had brought along to prove that I was indeed from Tech."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b63f25a2ab9','ch_1ad843ed6a0e','text','{"text": "She stared at the letter, then handed it back to me carefully, gripping it with her fingers as if it were a dinner plate heaped with food instead of a sheet of paper. She did not wear glasses and I wondered if she’d read a word of it. ‘The last boy was always late! Still owes me eight dollars! Harvard boys aren’t what they used to be! Only Harvard and Tech in this house! How’s Tech, boy?’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5d1abd2b62b','ch_1ad843ed6a0e','text','{"text": "‘It is very well.’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99b75795a423','ch_1ad843ed6a0e','text','{"text": "‘You checked the lock?’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25ef5e8925bc','ch_1ad843ed6a0e','text','{"text": "‘Yes, madame.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6dbc4913d0e','ch_1ad843ed6a0e','text','{"text": "She slapped the space beside her on the bench with one hand and told me to sit down. For a moment she was silent. Then she intoned, as if she alone possessed this knowledge:"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3cba696bf3cc','ch_1ad843ed6a0e','text','{"text": "‘There is an American flag on the moon!’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfa60ccb5d3c','ch_1ad843ed6a0e','text','{"text": "‘Yes, madame.’ Until then I had not thought very much about the moon shot. It was in the newspaper, of course, article upon article. The astronauts had landed on the shores of the Sea of Tranquillity, I had read, travelling farther than anyone in the history of civilization. For a few hours they explored the moon’s surface. They gathered rocks in their pockets, described their surroundings (a magnificent desolation, according to one astronaut), spoke by phone to the President and planted a flag in lunar soil. The voyage was hailed as man’s most awesome achievement. I had seen full-page photographs in the Globe, of the astronauts in their inflated costumes, and read about what certain people in Boston had been doing at the exact moment the astronauts landed, on a Sunday afternoon. A man said that he was operating a swan boat with a radio pressed to his ear; a woman had been baking rolls for her grandchildren."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd11de538c0c','ch_1ad843ed6a0e','text','{"text": "The woman bellowed, ‘A flag on the moon, boy! I heard it on the radio! Isn’t that splendid?’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f291d00ce1a','ch_1ad843ed6a0e','text','{"text": "‘Yes, madame.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c46b6f735832','ch_1ad843ed6a0e','text','{"text": "But she was not satisfied with my reply. Instead she commanded, ‘Say ‘splendid’!’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7db137063a38','ch_1ad843ed6a0e','text','{"text": "I was both baffled and somewhat insulted by the request. It reminded me of the way I was taught multiplication tables as a child, repeating after the master, sitting cross-legged, without shoes or pencils, on the floor of my one-room Tollygunge school. It also reminded me of my wedding when I had repeated endless Sanskrit verses after the priest, verses I barely understood, which joined me to my wife. I said nothing."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c845afb56ad8','ch_1ad843ed6a0e','text','{"text": "‘Say ‘splendid’!’ the woman bellowed once again."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e038a7ca2e8e','ch_1ad843ed6a0e','text','{"text": "‘Splendid,’ I murmured. I had to repeat the word a second time at the top of my lungs so she could hear. I am soft-spoken by nature and was especially reluctant to raise my voice to an elderly woman whom I had met only moments ago, but she did not appear to be offended. If anything the reply pleased her because her next command was:"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9be95c5e9ff7','ch_1ad843ed6a0e','text','{"text": "‘Go see the room!’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4f2687ebff3','ch_1ad843ed6a0e','text','{"text": "I rose from the bench and mounted the narrow carpeted staircase. There were five doors, two on either side of an equally narrow hallway and one at the opposite end. Only one door was partly open. The room contained a twin bed under a sloping ceiling, a brown oval rug, a basin with an exposed pipe, and a chest of drawers. One door, painted white, led to a closet, another to a toilet and a tub. The walls were covered with gray and ivory striped paper. The window was open; net curtains stirred in the breeze. I lifted them away and inspected the view: a small backyard, with a few fruit trees and an empty clothesline. I was satisfied. From the bottom of the stairs I heard the woman demand, ‘What is your decision?’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fde5bc460a4','ch_1ad843ed6a0e','text','{"text": "When I returned to the foyer and told her, she picked up the leather change purse on the table, opened the clasp, fished about with her fingers, and produced a key on a thin wire hoop. She informed me that there was a kitchen at the back of the house, accessible through the parlour. I was welcome to use the stove as long as I left it as I found it. Sheets and towels were provided but keeping them clean was my own responsibility. The rent was due Friday mornings on the ledge above the piano keys. ‘And no lady visitors!’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6329803c430c','ch_1ad843ed6a0e','text','{"text": "‘I am a married man, madame.’ It was the first time I had announced this fact to anyone."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd4ae1b7d411','ch_1ad843ed6a0e','text','{"text": "But she had not heard. ‘No lady visitors!’ she insisted."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_396db60d3d3c','ch_1ad843ed6a0e','text','{"text": "She introduced herself as Mrs Croft."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1178b6a76db','ch_1ad843ed6a0e','text','{"text": "My wife’s name was Mala. The marriage had been arranged by my older brother and his wife. I regarded the proposition with neither objection nor enthusiasm. It was a duty expected of me as it was expected of every man. She was the daughter of a school teacher in Beleghata. I was told that she could cook, knot, embroider, sketch landscapes and recite poems by Tagore, but these talents could not make up for the fact that she did not possess a fair complexion and so a string of men had rejected her to her face. She was twenty-seven, an age when her parents had begun to fear that she would never marry, and so they were willing to ship their only child halfway across the world in order to save her from spinsterhood."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f1ea636f7c9','ch_1ad843ed6a0e','text','{"text": "For five nights we shared a bed. Each of those nights, after applying cold cream and braiding her hair, which she tied up at the end with a black cotton string, she turned from me and wept; she missed her parents. Although I would be leaving the country in a few days, custom dictated that she was now a part of my household, and for the next six weeks she was to live with my brother and his wife, cooking, cleaning, serving tea and sweets to guests. I did nothing to console her. I lay on my own side of the bed, reading my guidebook by flashlight and anticipating my journey. At times I thought of the tiny room on the other side of the wall which had belonged to my mother. Now the room was practically empty; the wooden pallet on which she’d once slept was piled with trunks and old bedding. Nearly six years ago, before leaving for London, I had watched her die on that bed, had found her playing with her excrement in her final days. Before we cremated her I had cleaned each of her fingernails with a hairpin and then, because my brother could not bear it, I had assumed the role of eldest son, and had touched the flame to her temple, to release her tormented soul to heaven."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e2d21e0523f','ch_1ad843ed6a0e','text','{"text": "The next morning I moved into the room in Mrs Croft’s house. When I unlocked the door, I saw that she was sitting on the piano bench, on the same side as the previous evening. She wore the same black skirt, the same starched white blouse and had her hands folded together the same way in her lap. She looked so much the same that I wondered if she’d spent the whole night on the bench. I put my suitcase upstairs, filled my flask with boiling water in the kitchen, and headed off to work. That evening when I came home from the university, she was still there."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c09ca07b64c7','ch_1ad843ed6a0e','text','{"text": "‘Sit down, boy!’ She slapped the space beside her."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab380f0127d3','ch_1ad843ed6a0e','text','{"text": "I perched beside her on the bench. I had a bag of groceries with me—more milk, more cornflakes and more bananas, for, my inspection of the kitchen earlier in the day had revealed no spare pots, pans, or cooking utensils. There were only two saucepans in the refrigerator, both containing some orange broth, and a copper kettle on the stove."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a97c2c423af7','ch_1ad843ed6a0e','text','{"text": "‘Good evening, madame.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59d562e89a00','ch_1ad843ed6a0e','text','{"text": "She asked me if I had checked the lock. I told her I had."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4442dddc3091','ch_1ad843ed6a0e','text','{"text": "For a moment she was silent. Then suddenly she declared, with equal measures of disbelief and delight as the night before, ‘There’s an American flag on the moon, boy!’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8c7ae0c086a','ch_1ad843ed6a0e','text','{"text": "‘Yes, madame.’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51e4208b14d0','ch_1ad843ed6a0e','text','{"text": "‘A flag on the moon! Isn’t that splendid?’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5672d00441ac','ch_1ad843ed6a0e','text','{"text": "I nodded, dreading what I knew was coming. ‘Yes, madame.’"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d1e8410368a','ch_1ad843ed6a0e','text','{"text": "‘Say ‘splendid’!’"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea6894e9bd18','ch_1ad843ed6a0e','text','{"text": "This time I paused, looking to either side in case anyone were there to overhear me, though I knew perfectly well that the house was empty. I felt like an idiot. But is was a small enough thing to ask. ‘splendid!’ I cried out."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7528b9744c0','ch_1ad843ed6a0e','text','{"text": "Within days it became our routine. In the mornings, when I left for the library, Mrs Croft was either hidden away in her bedroom, on the other side of the staircase, or she was sitting on the bench, oblivious to my presence, listening to the news or classical music on the radio. But each evening when I returned the same thing happened: she slapped the bench, ordered me to sit down, declared that there was a flag on the moon, and declared that it was splendid. I said it was splendid, too, and then we sat in silence. As awkward as it was, and as endless as it felt to me then, the nightly encounter lasted only about ten minutes; inevitably she would drift off to sleep, her head falling abruptly toward her chest, leaving me free to retire to my room. By then, of course, there was no flag on the moon. The astronauts, I had read in the paper, had taken it down before flying back to earth. But I did not have the heart to tell her."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_312fe397b2ec','ch_1ad843ed6a0e','text','{"text": "Friday morning, when my first week’s rent was due, I went to the piano in the parlour to place my money on the ledge. The piano keys were dull and discoloured. When I pressed one, it made no sound at all. I had put eight onedollar bills in an envelope and written Mrs Croft’s name on the front of it; I was not in the habit of leaving money unmarked and unattended. From where I stood I could see the profile of her tent-shaped skirt. She was sitting on the bench, listening to the radio. It seemed unnecessary to make her get up and walk all the way to the piano. I never saw her walking about and assumed, from the cane always propped against the round table at her side, that she did so with difficulty. When I approached the bench, she peered up at me and demanded:"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71cd76f3fede','ch_1ad843ed6a0e','text','{"text": "‘What is your business?’"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7878c4c6c8a7','ch_1ad843ed6a0e','text','{"text": "‘The rent, madame.’"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43d08412ddaa','ch_1ad843ed6a0e','text','{"text": "‘On the ledge above the piano keys!’"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f373f593fc2e','ch_1ad843ed6a0e','text','{"text": "‘I have it here.’ I extended the envelope toward her, but her fingers, folded together in her lap, did not budge. I bowed slightly and lowered the envelope, so that it hovered just above her hands. After a moment she accepted, and nodded her head."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80d0ec40348d','ch_1ad843ed6a0e','text','{"text": "That night when I came home, she did not slap the bench but out of habit I sat beside her as usual. She asked me if I had checked the lock but she mentioned nothing about the flag on the moon. Instead she said:"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd089593cdff','ch_1ad843ed6a0e','text','{"text": "‘It was very kind of you!’"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41cd84a49edf','ch_1ad843ed6a0e','text','{"text": "‘I beg your pardon, madame?’"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca63e33947a2','ch_1ad843ed6a0e','text','{"text": "‘Very kind of you!’"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4cdcc07ba275','ch_1ad843ed6a0e','text','{"text": "She was still holding the envelope in her hands."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac33d7024faf','ch_1ad843ed6a0e','text','{"text": "On Sunday there was a knock on my door. An elderly woman introduced herself: she was Mrs Croft’s daughter, Helen. She walked into the room and looked at each of the walls as if for signs of change, glancing at the shirts that hung in the closet, the neckties draped over the doorknob, the box of cornflakes on the chest of drawers, the dirty bowl and spoon in the basin. She was short and thickwaisted, with cropped silver hair and bright pink lipstick. She wore a sleeveless summer dress, a row of white plastic beads and spectacles on a chain that hung like a swing against her chest. The backs of her legs were mapped with dark blue veins and her upper arms sagged like the flesh of a roasted eggplant. She told me she lived in Arlington, a town farther up Massachusetts Avenue. ‘I come once a week to bring Mother groceries. Has she sent you packing yet?’"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbd05e5447a4','ch_1ad843ed6a0e','text','{"text": "‘It is very well, madame.’"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f3e709a4251','ch_1ad843ed6a0e','text','{"text": "‘Some of the boys run screaming. But I think she likes you. You’re the first boarder she’s ever referred to as a gentleman.’"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09a87623bbac','ch_1ad843ed6a0e','text','{"text": "‘Not at all, madame.’"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e53166e493e','ch_1ad843ed6a0e','text','{"text": "She looked at me, noticing my bare feet (I still felt strange wearing shoes indoors, and always removed them before entering my room). ‘Are you new to Boston?’ ‘New to America, madame.’ ‘From?’ She raised her eyebrows."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d6bf5fec184','ch_1ad843ed6a0e','text','{"text": "‘I am from Calcutta, India.’"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5039e65681eb','ch_1ad843ed6a0e','text','{"text": "‘Is that right? We had a Brazilian fellow, about a year ago. You’ll find Cambridge a very international city.’"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c71d924fbba','ch_1ad843ed6a0e','text','{"text": "I nodded, and began to wonder how long our conversation would last. But at that moment we heard Mrs Croft’s electrifying voice rising up the stairs. When we stepped into the hallway we heard her hollering: ‘You are to come downstairs immediately!’ ‘What is it?’ Helen hollered back."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9381887fcbe0','ch_1ad843ed6a0e','text','{"text": "‘Immediately!’"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03016dbc022d','ch_1ad843ed6a0e','text','{"text": "I put on my shoes at once. Helen sighed."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ece258dcc8ed','ch_1ad843ed6a0e','text','{"text": "We walked down the staircase. It was too narrow for us to descend side by side, so I followed Helen, who seemed to be in no hurry, and complained at one point that she had a bad knee. ‘Have you been walking without your cane?’ Helen called out. ‘You know you’re not supposed to walk without that cane.’ She paused, resting her hand on the banister, and looked back at me. ‘She slips sometimes.’"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a992e9cce64a','ch_1ad843ed6a0e','text','{"text": "For the first time Mrs Croft seemed vulnerable. I pictured her on the floor in front of the bench, flat on her back, staring at the ceiling, her feet pointing in opposite directions. But when we reached the bottom of the staircase she was sitting there as usual, her hands folded together in her lap. Two grocery bags were at her feet. When we stood before her she did not slap the bench, or ask us to sit down. She glared."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0cd3271127e4','ch_1ad843ed6a0e','text','{"text": "‘What is it, Mother?’"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b2ab5ea6bcb','ch_1ad843ed6a0e','text','{"text": "‘It’s improper!’"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7d620bbde68','ch_1ad843ed6a0e','text','{"text": "‘What’s improper?’"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f410ce3b1f2d','ch_1ad843ed6a0e','text','{"text": "‘It is improper for a lady and gentleman who are not married to one another to hold a private conversation without a chaperone!’"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96e2deed248d','ch_1ad843ed6a0e','text','{"text": "Helen said she was sixty-eight years old, old enough to be my mother, but Mrs Croft insisted that Helen and I speak to each other downstairs, in the parlour. She added that it was also improper for a lady of Helen’s station to reveal her age, and to wear a dress so high above the ankle."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1288a2c09961','ch_1ad843ed6a0e','text','{"text": "‘For your information, Mother, it’s 1969. What would you do if you actually left the house one day and saw a girl in a miniskirt?’"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_518146ce7408','ch_1ad843ed6a0e','text','{"text": "Mrs Croft sniffed, ‘I’d have her arrested.’"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c20e9b81df43','ch_1ad843ed6a0e','text','{"text": "Helen shook her head and picked up one of the grocery bags. I picked up the other one and followed her through the parlour and into the kitchen. The bags were filled with cans of soup, which Helen opened up one by one with a few cranks of a can opener. She tossed the old soup in the saucepans into the sink, rinsed the pans under the tap, filled them with soup from the newly opened cans, and put them back in the refrigerator. ‘A few years ago she could still open the cans herself,’ Helen said. ‘She hates that I do it for her now. But the piano killed her hands.’ She put on her spectacles, glanced at the cupboards, and spotted my tea bags. ‘Shall we have a cup?’"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_577b677d6f20','ch_1ad843ed6a0e','text','{"text": "I filled the kettle on the stove. ‘ I beg your pardon, madame. The piano?’"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a4d2a899c2c','ch_1ad843ed6a0e','text','{"text": "‘She used to give lessons. For forty years. It was how she raised us after my father died.’ Helen put her hands on her hips, staring at the open refrigerator. She reached into the back, pulled out a wrapped stick of butter, frowned, and tossed it into the garbage. ‘That ought to do it,’ she said, and put the unopened cans of soup in the cupboard. I sat at the table and watched as Helen washed the dirty dishes, tied up the garbage bag, watered a spider plant over the sink, and poured boiling water into two cups. She handed one to me without milk, the string of the tea bag trailing over the side, and sat down at the table."}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e83f21e1ba1','ch_1ad843ed6a0e','text','{"text": "‘Excuse me, madame, but is it enough?’"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3f48ff35e63','ch_1ad843ed6a0e','text','{"text": "Helen took a sip of her tea. Her lipstick left a smiling pink stain on the inside rim of the cup. ‘Is what enough?’"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_852f4f11d51e','ch_1ad843ed6a0e','text','{"text": "‘The soup in the pans. Is it enough food for Mrs Croft?’"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a52a72638ed8','ch_1ad843ed6a0e','text','{"text": "‘She won’t eat anything else. She stopped eating solids after she turned one hundred. That was, let’s see, three years ago.’"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60b5f92d674b','ch_1ad843ed6a0e','text','{"text": "I was mortified. I had assumed Mrs Croft was in her eighties, perhaps as old as ninety. I had never known a person who had lived for over a century. That this person was a widow who lived alone mortified me further still. It was widowhood that had driven my own mother insane. My father, who worked as a clerk at the General Post Office of Calcutta, died of encephalitis when I was sixteen. My mother refused to adjust to life without him; instead, she sank deeper into a world of darkness from which neither I, nor my brother, nor concerned relatives, nor psychiatric clinics on Rashbihari Avenue could save her. What pained me most was to see her so unguarded, to hear her burp after meals or expel gas in front of company without the slightest embarrassment. After my father’s death my brother abandoned his schooling and began to work in the jute mill he would eventually manage, in order to keep the household running. And so it was my job to sit by my mother’s feet and study for my exams as she counted and recounted the bracelets on her arm as if they were the beads of an abacus. We tried to keep an eye on her. Once she had wandered half naked to the tram depot before we were able to bring her inside again."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57066b7a5044','ch_1ad843ed6a0e','text','{"text": "‘I am happy to warm Mrs Croft’s soup in the evenings,’ I suggested, removing the tea bag from my cup and squeezing out the liquor. ‘It is no trouble.’"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07a5e4595704','ch_1ad843ed6a0e','text','{"text": "Helen looked at her watch, stood up, and poured the rest of her tea into the sink. ‘I wouldn’t if I were you. That’s the sort of thing that would kill her altogether.’"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f42c1111658d','ch_1ad843ed6a0e','text','{"text": "That evening, when Helen had gone back to Arlington and Mrs Croft and I were alone again, I began to worry. Now that I knew how very old she was, I worried that something would happen to her in the middle of the night, or when I was out during the day. As vigorous as her voice was, and imperious as she seemed, I knew that even a scratch or a cough could kill a person that old; each day she lived, I knew, was something of a miracle. Although Helen had seemed friendly enough, a small part of me worried that she might accuse me of negligence if anything were to happen. Helen didn’t seem worried. She came and went, bringing soup for Mrs Croft, one Sunday after the next."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5c96354e2c9','ch_1ad843ed6a0e','text','{"text": "In this manner the six weeks of that summer passed. I came home each evening, after my hours at the library, and spent a few minutes on the piano bench with Mrs Croft. I gave her a bit of my company, and assured her that I had checked the lock, and told her that the flag on the moon was splendid. Some evenings I sat beside her long after she had drifted off to sleep, still in awe of how many years she had spent on this earth. At times I tried to picture the world she had been born into, in 1866—a world, I imagined, filled with women in long black skirts and chaste conversations in the parlour. Now when I looked at her hands with their swollen knuckles folded together in her lap, I imagined them smooth and slim, striking the piano keys. At times I came downstairs, before going to sleep, to make sure that she was sitting upright on the bench, or was safe in her bedroom. On Fridays I made sure to put the rent in her hands. There was nothing I could do for her beyond these simple gestures. I was not her son and apart from those eight dollars, I owed her nothing."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19f4f261d175','ch_1ad843ed6a0e','text','{"text": "At the end of August, Mala’s passport and green card were ready. I received a telegram with her flight information; my brother’s house in Calcutta had no telephone. Around that time I also received a letter from her, written only a few days after we had parted. There was no salutation; addressing me by name would have assumed an  intimacy we had not yet discovered. It contained only a few lines. ‘I write in English in preparation for the journey. Here I am very much lonely. Is it very cold there. Is there snow. Yours, Mala.’"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4b9a7bba5fe','ch_1ad843ed6a0e','text','{"text": "I was not touched by her words. We had spent only a handful of days in each other’s company. And yet we were bound together; for six weeks she had worn an iron bangle on her wrist, and applied vermilion powder to the part in her hair, to signify to the world that she was a bride. In those six weeks I regarded her arrival as I would the arrival of a coming month, or season—something inevitable but meaningless at the time. So little did I know her that, while details of her face sometimes rose to my memory, I could not conjure up the whole of it."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fabb5f45d348','ch_1ad843ed6a0e','text','{"text": "A few days after receiving the letter, as I was walking to work in the morning, I saw an Indian woman on the other side of Massachusetts Avenue, wearing a sari with its free end nearly dragging on the footpath, and pushing a child in a stroller. An American woman with a small black dog on a leash was walking to one side of her. Suddenly the dog began barking. From the other side of the street I watched as the Indian woman, startled, stopped in her path, at which point the dog leapt up and seized the end of the sari between its teeth. The American woman scolded the dog, appeared to apologise, and walked quickly away, leaving the Indian woman to fix her sari in the middle of the footpath, and quiet her crying child. She did not see me standing there and eventually she continued on her way. Such a mishap, I realised that morning, would soon be my concern. It was my duty to take care of Mala, to welcome her and protect her. I would have to buy her her first pair of snow boots, her first winter coat. I would have to tell her which streets to avoid, which way the traffic came, tell her to wear her sari so that the free end did not drag on the footpath. A five-mile separation from her parents, I recalled with some irritation, had caused her to weep."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a719bdf8996f','ch_1ad843ed6a0e','text','{"text": "Unlike Mala, I was used to it all by then: used to cornflakes and milk, used to Helen’s visits, used to sitting on the bench with Mrs Croft. The only thing I was not used to was Mala. Nevertheless I did what I had to do. I went to the housing office at MIT and found a furnished apartment a few blocks away, with a double bed and a private kitchen and bath, for forty dollars a week. One last Friday I handed Mrs Croft eight one-dollar bills in an envelope, brought my suitcase downstairs, and informed her that I was moving. She put my key into her change purse. The last thing she asked me to do was to hand her the cane propped against the table so that she could walk to the door and lock it behind me. ‘Good-bye, then,’ she said, and retreated back into the house. I did not expect any display of emotion but I was disappointed all the same. I was only a boarder, a man who paid her a bit of money and passed in and out of her home for six weeks. Compared to a century, it was no time at all."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e5cc33e0849','ch_1ad843ed6a0e','text','{"text": "At the airport I recognised Mala immediately. The free end of her sari did not drag on the floor but was draped in a sign of bridal modesty over her head, just as it had draped my mother until the day my father died. Her thin brown arms were stacked with gold bracelets, a small red circle was painted on her forehead and the edges of her feet were tinted with a decorative red dye. I did not embrace her, or kiss her, or take her hand. Instead I asked her, speaking Bengali for the first time in America, if she was hungry."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_315a0853690f','ch_1ad843ed6a0e','text','{"text": "I told her I had prepared some egg curry at home. ‘What did they give you to eat on the plane?’"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc64b7634460','ch_1ad843ed6a0e','text','{"text": "‘I didn’t eat.’"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_814e76bfa517','ch_1ad843ed6a0e','text','{"text": "‘All the way from Calcutta?’"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1d036725083','ch_1ad843ed6a0e','text','{"text": "‘The menu said oxtail soup.’"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a87e826934a9','ch_1ad843ed6a0e','text','{"text": "‘But surely there were other items.’"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_745663aeafd2','ch_1ad843ed6a0e','text','{"text": "‘The thought of eating an ox’s tail made me lose my appetite.’"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16f7a082d4a7','ch_1ad843ed6a0e','text','{"text": "When we arrived home, Mala opened up one of her suitcases and presented me with two pullover sweaters, both made with bright blue wool, which she had knitted in the course of our separation, one with a V neck, the other covered with cables. I tried them on; both were tight under the arms. She had also brought me two new pairs of drawstring pyjamas, a letter from my brother and a packet of loose Darjeeling tea. I had no present for her apart from the egg curry. We sat at a bare table, each of us staring at our plates. We ate with our hands, another thing I had not yet done in America."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c76c9f298e87','ch_1ad843ed6a0e','text','{"text": "‘The house is nice,’ she said, ‘also the egg curry’. With her left hand she held the end of her sari to her chest, so it would not slip off her head."}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f71074bd38c4','ch_1ad843ed6a0e','text','{"text": "‘I don’t know many recipes.’"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c15cd57c27c','ch_1ad843ed6a0e','text','{"text": "She nodded, peeling the  skin off each of her potatoes before eating them. At one point the sari slipped to her shoulders. She readjusted it at once."}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_330e345c6dac','ch_1ad843ed6a0e','text','{"text": "‘There is no need to cover your head,’ I said. ‘I don’t mind. It doesn’t matter here.’"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82cf8a5f4bad','ch_1ad843ed6a0e','text','{"text": "She kept it covered anyway."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a15bdf8e5b2a','ch_1ad843ed6a0e','text','{"text": "I waited to get used to her, to her presence at my side, at my table and in my bed, but a week later we were still strangers. I still was not used to coming home to an apartment that smelled of steamed rice, and finding that the basin in the bathroom was always wiped clean, our two toothbrushes lying side by side, a cake of Pears soap from India resting in the soap dish. I was not used to the fragrance of the coconut oil she rubbed every other night into her scalp, or the delicate sound her bracelets made as she moved about the apartment. In the mornings she was always awake before I was. The first morning when I came into the kitchen she had heated up the leftovers and set a plate with a spoonful of salt on its edge on the table, assuming I would eat rice for breakfast, as most Bengali husbands did. I told her cereal would do and the next morning when I came into the kitchen she had already poured the cornflakes into my bowl. One morning she walked with me down Massachusetts Avenue to MIT, where I gave her a short tour of the campus. On the way we stopped at a hardware store and I made a copy of the key, so that she could let herself into the apartment. The next morning before I left for work she asked me for a few dollars. I parted with them reluctantly but I knew that this, too, was now normal. When I came home from work there was a potato peeler in the kitchen drawer, and a tablecloth on the table, and chicken curry made with fresh garlic and ginger on the stove. We did not have a television in those days. After dinner I read the newspaper, while Mala sat at the kitchen table, working on a cardigan for herself with more of the bright blue wool, or writing letters home."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d57a0d85a40','ch_1ad843ed6a0e','text','{"text": "At the end of our first week, on Friday, I suggested going out. Mala set down her knitting and disappeared into the bathroom. When she emerged I regretted the suggestion; she had put on a clean silk sari and extra bracelets, and coiled her hair with a flattering side part on top of her head. She was prepared as if for a party, or at the very least for the cinema, but I had no such destination in mind. The evening air was balmy. We walked several blocks down Massachusetts Avenue, looking into the windows of restaurants and shops. Then, without thinking, I led her down the quiet street where for so many nights I had walked alone."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64180569886b','ch_1ad843ed6a0e','text','{"text": "‘This is where I lived before you came,’ I said, stopping at Mrs Croft’s chain-link fence."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_485f48d09c56','ch_1ad843ed6a0e','text','{"text": "‘In such a big house?’"}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13bda6b4e427','ch_1ad843ed6a0e','text','{"text": "‘I had a small room upstairs. At the back.’"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_becc4ef9d3dc','ch_1ad843ed6a0e','text','{"text": "‘Who else lives there?’"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8cd4a0ae2eac','ch_1ad843ed6a0e','text','{"text": "‘A very old woman.’"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f98a6977cf44','ch_1ad843ed6a0e','text','{"text": "‘With her family?’"}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_355958279c15','ch_1ad843ed6a0e','text','{"text": "‘Alone.’"}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c29c2efabcda','ch_1ad843ed6a0e','text','{"text": "‘But who takes care of her?’"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e60377750ff2','ch_1ad843ed6a0e','text','{"text": "I opened the gate. ‘For the most part she takes care of herself.’"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_660a476ce76a','ch_1ad843ed6a0e','text','{"text": "I wondered if Mrs Croft would remember me; I wondered if she had a new boarder to sit with her on the bench each evening. When I pressed the bell I expected the same long wait as that day of our first meeting, when I did not have a key. But this time the door was opened almost immediately, by Helen. Mrs Croft was not sitting on the bench. The bench was gone."}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_113460c07083','ch_1ad843ed6a0e','text','{"text": "‘Hello there,’ Helen said, smiling with her bright pink lips at Mala."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b319df23b159','ch_1ad843ed6a0e','text','{"text": "‘Mother’s in the parlour. Will you be visiting awhile?’"}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74ec239fdfde','ch_1ad843ed6a0e','text','{"text": "‘As you wish, madame.’"}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5755b16ec5cd','ch_1ad843ed6a0e','text','{"text": "‘Then I think I’ll run to the store, if you don’t mind. She had a little accident. We can’t leave her alone these days, not even for a minute.’"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0777bfc69321','ch_1ad843ed6a0e','text','{"text": "I locked the door after Helen and walked into the parlour. Mrs Croft was lying flat on her back, her head on a peach-coloured cushion, a thin white quilt spread over her body. Her hands were folded together on top of her chest. When she saw me she pointed at the sofa and told me to sit down. I took my place as directed but Mala wandered over to the piano and sat on the bench which was now positioned where it belonged."}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5e7c73a42cb','ch_1ad843ed6a0e','text','{"text": "‘I broke my hip! ’ Mrs Croft announced, as if no time had passed."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53e339dcbb0d','ch_1ad843ed6a0e','text','{"text": "‘Oh dear, madame.’"}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfffc7b75d87','ch_1ad843ed6a0e','text','{"text": "‘I fell off the bench!’"}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a4af1d49dfd','ch_1ad843ed6a0e','text','{"text": "‘I am so sorry, madame.’"}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e83674526c2f','ch_1ad843ed6a0e','text','{"text": "‘It was the middle of the night! Do you know what I did, boy?’"}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd7a7c436c31','ch_1ad843ed6a0e','text','{"text": "I shook my head."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59bd4829da32','ch_1ad843ed6a0e','text','{"text": "‘I called the police!’"}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1880346d07f','ch_1ad843ed6a0e','text','{"text": "She stared up at the ceiling and grinned sedately, exposing a crowded row of long grey teeth. Not one was missing. ‘What do you say to that, boy?’"}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0af675f8a8f2','ch_1ad843ed6a0e','text','{"text": "As stunned as I was, I knew what I had to say.With no hesitation at all, I cried out, ‘Splendid!’"}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe05ef50d254','ch_1ad843ed6a0e','text','{"text": "Mala laughed then. Her voice was full of kindness, her eyes bright with amusement. I had never heard her laugh before, and it was loud enough so that Mrs Croft had heard, too. She turned to Mala and glared."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fb1754bd573','ch_1ad843ed6a0e','text','{"text": "‘Who is she, boy?’"}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3219214aaf3b','ch_1ad843ed6a0e','text','{"text": "‘She is my wife, madame.’"}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f3e3a2f5d9a','ch_1ad843ed6a0e','text','{"text": "Mrs Croft pressed her head at an angle against the cushion to get a better look, ‘Can you play the piano?’ ‘No, madame,’ Mala replied."}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fad33b647931','ch_1ad843ed6a0e','text','{"text": "‘Then stand up!’"}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e58754a4067','ch_1ad843ed6a0e','text','{"text": "Mala rose to her feet, adjusting the end of her sari over her head and holding it to her chest, and, for the first time since her arrival, I felt sympathy. I remembered my first days in London, learning how to take the tube to Russell Square, riding an escalator for the first time, being unable to understand that when the man cried ‘piper’ it meant ‘paper’, being unable to decipher, for a whole year, that the conductor said ‘mind the gap’ as the train pulled away from each station. Like me, Mala had travelled far from home. Not knowing where she was going, or what she would find, for no reason other than to be my wife. As strange as it seemed, I knew in my heart that one day her death would affect me and, stranger still, that mine would affect her. I wanted somehow to explain this to Mrs Croft, who was still scrutinising Mala from top to toe with what seemed to be placid disdain. I wondered if Mrs Croft had ever seen a woman in a sari, with a dot painted on her forehead and bracelets stacked on her wrists. I wondered what she would object to. I wondered if she could see the red dye still vivid on Mala’s feet, all but obscured by the bottom edge of her sari. At last Mrs Croft declared, with equal measures of disbelief and delight I knew well:"}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5594014f45db','ch_1ad843ed6a0e','text','{"text": "‘She is a perfect lady!’"}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ee4b7934400','ch_1ad843ed6a0e','text','{"text": "Now it was I who laughed. I did so quietly and Mrs Croft did not hear me. But Mala had heard, and, for the first time, we looked at each other and smiled."}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14ff9b8e626c','ch_1ad843ed6a0e','text','{"text": "I like to think of that moment in Mrs Croft’s parlour as the moment when the distance between Mala and me began to lessen. Although we were not yet fully in love, I like to think of the months that followed as a honeymoon of sorts. Together we explored the city and met other Bengalis, some of whom are still friends today. We discovered that a man named Bill sold fresh fish on Prospect Street, and that a shop in Harvard Square, called Cardullo’s, sold bay leaves and cloves. In the evenings we walked to the Charles River to watch sailboats drift across the water, or had ice cream cones in Harvard Yard. We bought an Instamatic camera with which to document our life together, and I took pictures of her posing in front of the Prudential building so that she could send them to her parents. At night we kissed, shy at first but quickly bold, and discovered pleasure and solace in each other’s arms. I told her about my voyage on the SS Roma, and about Finsbury Park and the YMCA, and my evenings on the bench with Mrs Croft. When I told her stories about my mother, she wept. It was Mala who consoled me when, reading the Globe one evening, I came across Mrs Croft’s obituary. I had not thought of her in several months—by then those six weeks of the summer were already a remote interlude in my past—but when I learned of her death I was stricken, so much so that when Mala looked up from her knitting she found me staring at the wall, the newspaper neglected in my lap, unable to speak. Mrs Croft’s was the first death I mourned in America, for, hers was the first life I had admired; she had left this world at last, ancient and alone, never to return."}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24584edf40a3','ch_1ad843ed6a0e','text','{"text": "As for me, I have not strayed much farther: Mala and I live in a town about twenty miles from Boston, on a treelined street much like Mrs Croft’s, in a house we own, with a garden that saves us from buying tomatoes in summer, and room for guests. We are American citizens now so that we can collect social security when it is time. Though we visit Calcutta every few years, and bring back more drawstring pyjamas and Darjeeling tea, we have decided to grow old here. I work in a small college library. We have a son who attends Harvard University. Mala no longer drapes the end of her sari over her head, or weeps at night for her parents but, occasionally, she weeps for our son. So we drive to Cambridge to visit him, or bring him home for a weekend, so that he can eat rice with us with his hands and speak in Bengali, things we sometimes worry he will no longer do after we die."}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db46166ad805','ch_1ad843ed6a0e','text','{"text": "Whenever we make that drive, I always make it a point to take Massachusetts Avenue, in spite of the traffic. I barely recognise the buildings now but each time I am there I return instantly to those six weeks as if they were only the other day, and I slow down and point to Mrs Croft’s street, saying to my son, here was my first home in America where I lived with a woman who was 103. ‘Remember?’ Mala says, and smiles, amazed, as I am, that there was ever a time that we were strangers. My son always expresses his astonishment, not at Mrs Croft’s age, but at how little I paid in rent, a  nearly inconceivable amount to him as a flag on the moon was to a woman born in 1866. In my son’s eyes I see the ambition that had first hurled me across the world. In a few years he will graduate and pave his way, alone and unprotected. But I remind myself that he has a father who is still living, a mother who is happy and strong. Whenever he is discouraged, I tell him that if I can survive on three continents, then there is no obstacle he cannot conquer. While the astronauts, heroes forever, spent mere hours on the moon, I have remained in this new world for nearly thirty years. I know that my achievement is quite ordinary. I am not the only man to seek his fortune far from home and certainly I am not the first. Still, there are times I am bewildered by each mile I have travelled, each meal I have eaten, each person I have known, each room in which I have slept. As ordinary as it all appears, there are times when it is beyond my imagination."}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea15c7588664','ch_1ad843ed6a0e','list','{"ordered": false, "items": ["Jhumpa Lahiri"]}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51d87d232570','ch_1ad843ed6a0e','heading','{"level": 2, "text": "About The Author"}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f633e29fecdc','ch_1ad843ed6a0e','text','{"text": "Jhumpa Lahiri, an Indian Bengali, born in London (1967), lives in New York with her husband and son. This story is from her collection, Interpreter of Maladies (1999), a bestseller in 2000 both in U.S.A. and elsewhere. In addition to the Pulitzer Prize, she has received a number of awards for the work which has been translated into twenty-nine languages."}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_566845f6e164','ch_1ad843ed6a0e','text','{"text": "Her stories revolve around the lives of Indians in diasporic situations, i.e., of  Indians living abroad,  Indians who have been brought up in traditional India but are now encountering the baffling new world [U.S.A.]."}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c97e817dfda','ch_1ad843ed6a0e','heading','{"level": 2, "text": "Understanding The Text"}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c79b9ad9eba','ch_1ad843ed6a0e','text','{"text": "1. Indicate the details that tell us that the narrator was not very financially comfortable during his stay in London."}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78636d26ad5b','ch_1ad843ed6a0e','text','{"text": "2. How did the narrator adjust to the ways of life first in London and then in Cambridge, U.S.A.?"}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0449db80ccbd','ch_1ad843ed6a0e','text','{"text": "3. What do you understand of the character of Mrs Croft from the story?"}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d938ddfda03','ch_1ad843ed6a0e','text','{"text": "4. What kind of a relationship did Mrs Croft share with her daughter Helen?"}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3297369a2515','ch_1ad843ed6a0e','text','{"text": "5. How does the narrator bring out the contrast between the Indian way of life and American society? Do you think his wife Mala adjusted comfortably to the new way of life?"}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e89732a148c3','ch_1ad843ed6a0e','text','{"text": "6. How does the bond of affection between Mrs Croft and the narrator evolve?"}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b86bc685b06','ch_1ad843ed6a0e','text','{"text": "*********"}',157);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_5e5c5ef311e1','bk_ncert_english','11-7-glory-at-twilight','11.7 Glory at Twilight',NULL,'public',47,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05dd0d13ce1d','ch_5e5c5ef311e1','text','{"text": "The slow, narrow-gauge Indian train with its awkward freak of an engine had a way of making unauthorised stops for no good reason, between fields of corn or at the foot of a village—it was said that the guard signalled a halt to pluck a pumpkin or ripe melons from its stem or to buy fistfuls of green gram from a peasant."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c1f3c0ea85e','ch_5e5c5ef311e1','text','{"text": "Some of the passengers grumbled and sat with drawn brows, composing in their minds angry letters to Authority, or to the Press, but others seized the chance to slip merrily out of doors for a breath of air and a view of the green fields. Satyajit, languid on the cushioned bench now vacated by the other occupants, reached out for his cigarettes but, on second thought, withdrew his hand brusquely. That won’t do, he told himself with a stern shake of his head. His smoke was rationed."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e19765c8ca6e','ch_5e5c5ef311e1','text','{"text": "He had attuned himself in the past month to a fast-growing list of denials, large and small, and this was one. How can he afford the unrestricted luxury of chain smoking? Life lay sharpening to realities that still had the semblance of an undreamable dream. He winced, the turning wheel of fortune in his unhappy eye, as always. Along the orbit of reminiscence he went round and round, pulled by a force beyond his will. The banking establishment of which he had attained control."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e47d71821b7','ch_5e5c5ef311e1','text','{"text": "The amazing tempo of it all. Luck had come his way, undeniably, but behind it was his mind, his initiative, grit, energy. Starting as a mere clerk he had become Managing Director. And now? What now? Tall, thin, near forty, he had sharp features, the hair receding on his temple in wide shiny smooth patches. His eyes hated glare and he wore smart eye-glasses to shield them. His mouth, thin-lipped, would tighten in repose to a line that suggested strength of will but might have been only pride."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d31d33000f15','ch_5e5c5ef311e1','text','{"text": "‘What now?’ he said to himself in an underbreath."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ea472ffcb27','ch_5e5c5ef311e1','text','{"text": "Those words had become his obsession."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4392e06747b6','ch_5e5c5ef311e1','text','{"text": "‘What now?’ He had no business to be on this wretched train on a neglected railroad, travelling away from the city where he must look for work, for the means of living."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44e4bd1eb3fb','ch_5e5c5ef311e1','text','{"text": "With the sudden collapse of his bank, all his private assets were gone overnight; the equities; the house on Tagore Street; even the two cars, his and his wife’s. A mercy that she was away from the scene, with her parents at Delhi, and unaware of the full extent of the ruin. A telegram had come last Tuesday announcing the safe birth of her child. Their first-born, for he had married late in life. His son, his heir."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_796a4c4e4d44','ch_5e5c5ef311e1','text','{"text": "And he had sold off his diamond ring to send his young wife a remittance for the name-giving rites. She had married a man of fortune—that made it harder for him in this crisis. True, she knew all about his earlier life. But that was story-book stuff. It could be narrated happily to their first-born when he grew older. The story lay killed by its sequel—failure. Glory was all overlaid with dark shame. Glory was dead."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a0931910de0','ch_5e5c5ef311e1','text','{"text": "It would be easy enough today if there were none else to think of except himself. Born in a humble village home, self-educated, struggle had been his life-breath. How grateful he was for the clerkship he secured. A turning of the wheel of fortune? he had wondered. The next turning, a year after, was more dramatic. What made him give a fixed look to the man beyond the brass grille of the counter? The cheque presented for encashment was not a large sum. Eye upon eye."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f5498190d6a','ch_5e5c5ef311e1','text','{"text": "Alarm vivid in the face and the hand on the counter shaking curiously. Surprised, stirred by a quick impulse, he took the cheque to the accounts desk, compared the signature with the one on record. It tallied. But that face, that hand. A hundred reasons, none connected with the cheque, could explain the face and hand. Even so, the impulse led him to the telephone."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75322c76c8ad','ch_5e5c5ef311e1','text','{"text": "‘Sir, have you signed a bearer cheque for Rs 2,000? It has yesterday’s date...’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54015fa96228','ch_5e5c5ef311e1','text','{"text": "‘Rs 2,000? No.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_16e5b0165df9','ch_5e5c5ef311e1','text','{"text": "His heart felt pain for lack of air."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf3e45c56ac4','ch_5e5c5ef311e1','text','{"text": "‘Sir, are you sure? The signature seems okay.’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f5eee0c0ee9','ch_5e5c5ef311e1','text','{"text": "In the next instance he was back to his counter in a rush. Where was the man? There, close to the exit, and the face turning back for a moment wore stark fear. He was going away. Feet bounded up the counter. The bank clerk hunted down his prey on the gravel path, twenty paces from the front door. There was no struggle. The man crumpled down in a heap. He squatted with head between his hands, looking down, tears rolling down."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e54033584ad9','ch_5e5c5ef311e1','text','{"text": "‘Why did you have to commit forgery?’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_140dc018db27','ch_5e5c5ef311e1','text','{"text": "‘She has TB.’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa9b00f05bca','ch_5e5c5ef311e1','text','{"text": "‘She?’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c35f8598145b','ch_5e5c5ef311e1','text','{"text": "‘She is dying for want of medicine.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba26e0337e5f','ch_5e5c5ef311e1','text','{"text": "‘Who?’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a86ac98b4958','ch_5e5c5ef311e1','text','{"text": "‘My wife. I saw no other means. I give lessons in Maths to the rich man’s son. That money...’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e5d827d7425','ch_5e5c5ef311e1','text','{"text": "The head between the hands wagged from side to side in a queer rhythmic frenzy. That was the way the clerk grew into an accountant. He deserved what he had gained. He was not made to be a mere clerk. Lost in the thrill, he had honest contempt for his stepping-stone, the forgerer. You could not commit such a crime even to save your dying wife. But today, as he sat on his lone bench on the train, he saw mind-pictures and felt troubled."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3f42fb70b9c','ch_5e5c5ef311e1','text','{"text": "The crouched figure on the gravel path wrapped in mute grieving. The prisoner at the bar, face frozen, as though he had died within himself. Had he anything to say to the Court? the Judge had asked."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d665ae471550','ch_5e5c5ef311e1','text','{"text": "‘Punish me.’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ba41c5a0c82','ch_5e5c5ef311e1','text','{"text": "‘Is that all?’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b47c1736db9d','ch_5e5c5ef311e1','text','{"text": "‘Punish me as a killer.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6fdb3e53198','ch_5e5c5ef311e1','text','{"text": "‘Killer?’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_934cd73815dd','ch_5e5c5ef311e1','text','{"text": "‘I have put my wife to shame. Shame kills as fast as TB.’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e857ebbee824','ch_5e5c5ef311e1','text','{"text": "Yes, that wretched one had turned the wheel for him with his trembling hand. From that point the wheel attained a volition of its own, moving continuously. He had every reason to be grateful to the forgerer. Too late now to seek him out, give him a chance to live? Too late. He himself sorely needed a chance to live. The banking business lay around him in a broken mass and there was he, prostrate on his face in the wreckage, sucking its dust. All his fault. He had tried to overreach himself."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59923f2ff59f','ch_5e5c5ef311e1','text','{"text": "Each wrong step was now clear in time’s perspective. The run on the bank had come all too suddenly though. Failure had a tempo far faster than success. He had great need to fly from himself—that was why he was on this train. A letter had come in the nick of time offering him an excuse, a temporary relief from the wrenching within."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be0f433cc2ad','ch_5e5c5ef311e1','text','{"text": "‘The wedding of my fifth daughter, Beena, is to take place on the twentieth of this month. I have kept you posted with the progress of negotiations. I seek your benediction as in the case of my second, third and fourth daughters— Kamini, Damini and Suhashi. With Beena wedded, there will be only Aruna left, and she is in her tenth year. Your benediction alone can pull me through the present daughter crisis. That is all I have to say—Your helpless Uncle Srinath.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34007b189ad8','ch_5e5c5ef311e1','text','{"text": "Daughter crisis, indeed! mused Satyajit with a dim smile. Uncle Srinath, a neighbour at Shantipur village but no blood relation, seemed to have been producing his numerous daughters secure in the faith that others would bear the brunt of the repeated crises of their marriage needs. And Satyajit, in the flush of prosperity, had been more than open-handed. It was a matter of pride, selfsatisfaction."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5efe420989d','ch_5e5c5ef311e1','text','{"text": "In his younger days, the village people had not thought much of him, had not seen in him any special gift or brilliance. One of the common herd. That was all the more reason why he enjoyed success. He needed the wide-eyed wonder and eager homage of Uncle Srinath and the like while they had use and longing for his money. It was plain give-and-take. All that was over. Fallen from his castle in the clouds, Satyajit must tread the earthly ways of humble folk."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_599762e0660e','ch_5e5c5ef311e1','text','{"text": "But he could not deny the old man altogether. He must send some help. He had pondered over the amount. He had to ponder over each rupee before he spent it. Then, all at once, he had come to a decision. He would go to Shantipur and attend the marriage. This would be a welcome relief—the city was suffocating him. His mind would be freshened, his strength renewed for the coming struggle by a return to the physical scene which had been his starting point in life."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8f05e36f36e','ch_5e5c5ef311e1','text','{"text": "Let that be his starting point once more, outwardly as much as in the spirit. He would also take this chance to look at his ancestral house and fishpond, both leased out, bits of property still intact amid the vast demolition. Those he must pass on to his wife as his last gift. And he had sent word to Uncle Srinath about his arrival on the marriage day. The engine came to life with a shrill of warning. The passenger hurried back. Another half-hour and it was Shantipur."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8bd24f13105','ch_5e5c5ef311e1','text','{"text": "Satyajit leaned out of the door, his eyes looking for Uncle Srinath on the station platform, where many people stood crowded together, alert and apparently excited, one of them holding aloft the national flag on a bamboo pole. A political celebrity on the train? Strange that Uncle Srinath, who had always feared politics, was leading the group. Suddenly, there was a rush of legs towards Satyajit as he stepped down. The legs stopped and a booming chorus followed."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd4a7f396e2a','ch_5e5c5ef311e1','text','{"text": "Swagatam! Welcome!’ A small girl with an awestruck face stepped up with a jasmine garland in her hand. Satyajit stood in a daze of bewilderment as the girl rose on tiptoe to place the chain of flowers around his neck. He bent mechanically to receive the offer, not knowing what it meant. It was obviously a mistake, a very curious one."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e799993acbb','ch_5e5c5ef311e1','text','{"text": "‘Welcome!’ the voices rang again. Then, an expectant hush. Uncle Srinath turned round to the group. On the high cheekbones and grey stubble of his face was a clear coating of strong elation."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5a1017dbd74','ch_5e5c5ef311e1','text','{"text": "‘Friends and brothers! Bengal has seen greatness in almost every field of action. I shall not belittle your knowledge by citing names. It is only in trade and industry that Bengal has lagged behind sadly—the plums of business have gone to people from upcountry or from overseas."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4769c68a1b02','ch_5e5c5ef311e1','text','{"text": "That is why our hearts grow big with pride at the sight of a son of Bengal, a son of our own Shantipur village, who has attained great success in that field, that forbidden field, and become the glory of the motherland, Swagatam! Welcome!’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3e1b8586f7d','ch_5e5c5ef311e1','text','{"text": "‘Swagatam!’ the combined voices roared while the tricolour flag on its tall pole nodded approvingly. When Satyajit slipped down from the ox cart at the door of a mud-brick house, a knot of women waiting tensely with brass water-bowls rushed up and stooped over his feet, scrambling for the privilege to wash his feet with cool water. Satyajit shrank back, embarrassed."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e88cd3cc47ce','ch_5e5c5ef311e1','text','{"text": "‘It’s my Beena’s privilege,’ cried Srinath, smiling."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_078a22ffbeef','ch_5e5c5ef311e1','text','{"text": "‘This is her day. Let Beena alone wash and wipe the reverent feet. All her life she will remember this honour befalling her on the auspicious day of her marriage.’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f03a8d51d81','ch_5e5c5ef311e1','text','{"text": "Satyajit looked at the girl who stepped forward, shy, slender with large pensive eyes in a graceful face."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd16bf943007','ch_5e5c5ef311e1','text','{"text": "‘So this is the bride,’ he smiled at her and touched her hair in the gesture of blessing."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4576ce0c3340','ch_5e5c5ef311e1','text','{"text": "‘I hope the groom is worthy of this girl,’ he said as she knelt down to unlace his shoes."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30833fe1aedf','ch_5e5c5ef311e1','text','{"text": "She slipped off his socks and poured cool water to freshen his feet, washing them with keen care. As her slim fingers went between his toes, he wiggled them, for he felt ticklish. Presently he sat on a carpet in the inner verandah with a plateful of sweets and a glass of whey while Kamini, Damini and Suhashi sat near him on their haunches and waved palm leaf fans with all their energy, as though each passing minute had to be fully used before their hands were deprived of the privilege."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c59d951439ff','ch_5e5c5ef311e1','text','{"text": "Sweat broke out on their faces and they shifted their fans from right hand to left and again to the right. Their mother, who stood by, now spoke in a murmur, husky with emotion."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c877c707e29e','ch_5e5c5ef311e1','text','{"text": "‘You have been more of a father to these girls than he,’ jerking her head at her invisible husband."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73ac53701df5','ch_5e5c5ef311e1','text','{"text": "‘But for the bigness of your heart, they would still be maids under this room, shooting up in years and in height with no chance of having husband and home.’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a32aec7797bc','ch_5e5c5ef311e1','text','{"text": "She lifted her sari fringes to her eyes, wiping off two grateful tears. The meal over, Uncle Srinath, who had been shuttling between the inner verandah and the outer quarters, now stopped, leaning over his guest."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfa8ad30ea2a','ch_5e5c5ef311e1','text','{"text": "‘Beena has been given the old jewellery of her mother,’ he confided."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_caa2012972af','ch_5e5c5ef311e1','text','{"text": "‘So, that part of the dowry problem has been met. Her three married sisters, whom you see before you and who owe all their bliss in life to your benediction, have given her the marriage gifts she must have:"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be59aaf6d735','ch_5e5c5ef311e1','text','{"text": "sari, jacket, chemise. Also brass utensils for her new household.’"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d87ae0865a21','ch_5e5c5ef311e1','text','{"text": "‘Good! Good!’ Satyajit cried happily."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3c14606f403','ch_5e5c5ef311e1','text','{"text": "He had Rs 200 in his purse and had wondered how much of it had to go into the marriage pool. May be Rs 100; or, rather, Rs 101, since a figure ending with zero was not propitious. During the meal he had been slowly adding to that figure:"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1927e75a03f','ch_5e5c5ef311e1','text','{"text": "ten, twenty, finally stopping at an additional fifty. Now that Beena had got all she needed, he could just as well slice a goodly bit off the amount. Let it be Rs 101. The fifty rupees saved would buy a perambulator for his newborn son."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5af5a2cdc30','ch_5e5c5ef311e1','text','{"text": "‘Your benediction is our blind-man’s staff,’ Srinath went on."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99ddc1a0c854','ch_5e5c5ef311e1','text','{"text": "‘Do I have to say more?’ He apparently decided that he did not, for he changed the topic abruptly."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59a75aa32c3e','ch_5e5c5ef311e1','text','{"text": "‘My house has become a place of pilgrimage. You are the pride of the village, its strength. In you the people see their own inmost dream fulfilled. Will you now show yourself for a minute to the devotees who sit waiting—’ Satyajit followed his host. His devotees were seated on a floor mat, talking animatedly, and at the sight of him there was an instant hush. Hands joined to his chest, Satyajit made salutation to all."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c229defd7b6e','ch_5e5c5ef311e1','text','{"text": "He caught sight of the schoolmaster who had taught him as a boy and made a deep obeisance. Swelled with pride, the old man swept the floor mat group with a superior glance before he spoke:"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f33fba16c7bf','ch_5e5c5ef311e1','text','{"text": "‘Didn’t I say? Didn’t I say a hundred and one times in those far off days that the light of genius blazed on the face of my young pupil? That he stood apart from every other young pig—’ He broke short and yielded to a violent fit of coughing to cover up the slip. Presently he resumed:"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_684f10b3c6e3','ch_5e5c5ef311e1','text','{"text": "‘That he with the light of genius on his face was afar from the world where the other youngsters dwelt? Why, I predicted that he would be a High Court Judge—’ Satyajit burst into a laugh."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9be5dd17784','ch_5e5c5ef311e1','text','{"text": "‘Alas, I am no High Court Judge’."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f64aa2d666f4','ch_5e5c5ef311e1','text','{"text": "‘Even more, much more!’ counted the old man."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3cf6ecc0776f','ch_5e5c5ef311e1','text','{"text": "His good memory reached back to the boy with whom he had been on terms of a perpetual feud. Always bent on some kind of mischief—he did have an inventive mind that way! Arithmetic was his bogey. How does he count all his pile of money? He owns a million, if Srinath is to be believed. A million? And the old man hastened to add a brushful of colour to the drab picture presented by memory."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a953fa2ea47e','ch_5e5c5ef311e1','text','{"text": "‘Even in those far-off days I could see two shadow forms about him, clear as life—Saraswati at his left, Lakshmi at his right. And I knew even then that the twin goddesses of knowledge and wealth, though hating the sight of each other, had for once united, stayed together, drawn by their common love.’"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c527cf634605','ch_5e5c5ef311e1','text','{"text": "He lifted joined palms to his forehead, offering salutation— perhaps to those goddesses. Satyajit was determined to enjoy himself. He felt a twinge of regret that he had not thought of coming to Shantipur and basking in the people’s homage when it was truly his due. Now he was an impostor. He impersonated the man he had been a few weeks before. He made an angry jerk of his hand about his face, waving off a sandfly—and the regret."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3cca2a0ee9c8','ch_5e5c5ef311e1','text','{"text": "Let him be happy for the day even with a false echo, let him be wrapped a while in the lingering twilight splendour of departed glory. Tommorow he would be in the full fury of a stream, tugged under water, fighting for life. Today he would have his last breath of peace, freedom, content. Through the rest of the day he went round the village, meeting the elders, sipping the proffered milk of green coconuts. He visited his house occupied by a tenant."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1670fadb0d83','ch_5e5c5ef311e1','text','{"text": "His house—and he touched the walls possessively. This small house gave him a feeling of security which had not come to him even from his huge city mansion. He spent an hour by the fish pond. His pond—and he sprinkled a palmful of its water on his head. A good-sized carp landed at the end of his hook. When he came home with the catch, Uncle Srinath gazed at it raptly—one would have thought he had never before seen such fish."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b2d9c283a84','ch_5e5c5ef311e1','text','{"text": "‘What gills!’ he breathed in apparent ecstasy."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c229f9fcd55a','ch_5e5c5ef311e1','text','{"text": "He patted the head of the fish with an affectionate hand."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ee81633719c','ch_5e5c5ef311e1','text','{"text": "‘Bride and groom shall eat curried portions of this auspicious one when they break their marriage fast at midnight. That will bring them all the blessings that life can give’. It was near twilight when the groom’s party arrived in ox carts and palanquins. Conches blew welcome."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0408c6fc3d4','ch_5e5c5ef311e1','text','{"text": "Young women gathered at the dooryard and gave the shrill traditional greeting expressive of great joy; Ulu-ulu-uluulu-ulu! When the bridal party was well settled, chewing betel leaf and waiting for the marriage hour as prescribed by the almanac, Satyajit felt for his purse. Time now to part with Rs 101. Srinath, reading his thoughts, took him to the secluded darkness under a fig-tree in the backyard"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a6bb4b304d0','ch_5e5c5ef311e1','text','{"text": "‘My begging bowl is ready,’ he announced happily."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be0cf2395b59','ch_5e5c5ef311e1','text','{"text": "‘Yes, yes,’ Satyajit nodded."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3027b07b4fbf','ch_5e5c5ef311e1','text','{"text": "‘The cash dowry stands fixed. Only Rs 2001.’"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d792ff56f282','ch_5e5c5ef311e1','text','{"text": "‘What!’ Satyajit felt a hard blow in the pit of his stomach."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a25700600e99','ch_5e5c5ef311e1','text','{"text": "‘That is all.’"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_947d58a54e94','ch_5e5c5ef311e1','text','{"text": "‘Rs 2001?’ Srinath smiled."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8ad222b45c3','ch_5e5c5ef311e1','text','{"text": "‘Everything else is provided for, even the cost of the marriage feast. Only this last item awaits your benediction.’"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34387c0b564d','ch_5e5c5ef311e1','text','{"text": "Benediction—Srinath’s favourite word. Nothing abstract in its meaning. It could be interpreted only in terms of money. Satyajit felt a burning inside him. He had stretched his leg right into the snare of benediction, unthinkingly. How could he be so very stupid? Srinath broke the silence with a half laugh."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1507fb78804c','ch_5e5c5ef311e1','text','{"text": "‘This drop in the ocean of your fortune. It shames me to mention the petty figure.’"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87f7fd046ba5','ch_5e5c5ef311e1','text','{"text": "‘Why didn’t you write and tell me?’ The voice was harsh."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ead32d492a93','ch_5e5c5ef311e1','text','{"text": "The half laugh repeated itself."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24ef92df9931','ch_5e5c5ef311e1','text','{"text": "‘Have I no sense? I am not such a big ass as I look. What! Mention money to a millionaire! And such a pittance. A drop in the ocean.’"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de060721a5d4','ch_5e5c5ef311e1','text','{"text": "‘A drop,’ echoed Satyajit, his mouth dry."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f26b4f26c11a','ch_5e5c5ef311e1','text','{"text": "This was the moment for confession. He was even worse off than Srinath. Hard struggle lay ahead of him for bare survival. Srinath would understand."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fd5ced0924c','ch_5e5c5ef311e1','text','{"text": "‘Millionaire!’ Rhapsody in the voice. Plain worship on the face. A devotee, prayerful before his god."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14272668c90d','ch_5e5c5ef311e1','text','{"text": "‘ We bask in your benediction. Our life-spark itself is held in your fist; you can destroy it just by closing your fingers tight. Words cannot say what I feel —’ Yes, the god had been a millionaire, truly. That was yesterday. Today... Confession stuck in his throat, clutched by the millionaire’s dead hand. Better give an excuse. He had come rushing in the midst of heavy work and had not thought of equipping himself with adequate cash. That would sound plausible."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0739024134e0','ch_5e5c5ef311e1','text','{"text": "Later—it wouldn’t matter if Srinath discovered the terrible truth later, as he must. Something stronger than he spoke with his tongue."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67bfc82853f0','ch_5e5c5ef311e1','text','{"text": "‘I had to catch the morning train—there was no time to go to the bank. Maybe someone in the village—’ The words"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c3edaa0d5da','ch_5e5c5ef311e1','text','{"text": "‘cash a cheque’ were almost on his lips."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d333c9ff6cd6','ch_5e5c5ef311e1','text','{"text": "‘Someone in the village will advance a loan—’ Uncle Srinath rushed out of the house, panic on his face."}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcee36f31c61','ch_5e5c5ef311e1','text','{"text": "He had been under the impression that a millionaire always had his pockets stuffed with money. Satyajit returned to the assembled guests. Instantly the groom, on his foothigh satin-draped platform, fat round cushions on three sides of him, was forgotten. Silence. All eyes took their fill of the rich man. A god on the pedestal of fortune. He too sat quiet, the tiredness within him heavier than even before. The peace he had attained erstwhile was gone."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fce372f004b','ch_5e5c5ef311e1','text','{"text": "He longed to see the face of his new-born son. The rich man’s son who would never ride in a perambulator. Srinath returned in half an hour. His face looked angry. Satyajit saw his beckoning hand, rose heavily to his feet, and stepped outside, away from the people."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc39852e895a','ch_5e5c5ef311e1','text','{"text": "‘Only one person in Shantipur can produce so much cash at this late hour,’ said Srinath, ‘Harish, the moneylender."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03662f0638a4','ch_5e5c5ef311e1','text','{"text": "That shark refuses to make an advance though.’"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a67c5b481c1e','ch_5e5c5ef311e1','text','{"text": "The swift flood of relief!"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e396f363f36e','ch_5e5c5ef311e1','text','{"text": "‘Harish does not trust me?’ Moneylenders did have a sixth sense."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3963adbe1067','ch_5e5c5ef311e1','text','{"text": "There was no knowing when Harish would have got his money back—perhaps never."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae1002844548','ch_5e5c5ef311e1','text','{"text": "‘Preposterous! Not to trust the word and signature of a millionaire! Harish is off his senses; or, is it malice?’ The voice collected anger."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_928d4d766c07','ch_5e5c5ef311e1','text','{"text": "‘I could drag him to you and make him grovel at your feet and rub his fat nose on the ground.’"}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddfbab30a434','ch_5e5c5ef311e1','text','{"text": "Satyajit could be generous."}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_504ec09e18e8','ch_5e5c5ef311e1','text','{"text": "‘No need, no need. Trust is out of date in these cynical times.’"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a0f6fa4bc86','ch_5e5c5ef311e1','text','{"text": "The wonder of it—his leg was off the snare of benediction!"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34544ea674bd','ch_5e5c5ef311e1','text','{"text": "‘Where will our India be if such things are tolerated? What is Nehru doing about it? Is there no one to tell him how things stand in the country?’ Satyajit patted the excited man on the shoulder, soothingly."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3780aab94adc','ch_5e5c5ef311e1','text','{"text": "Srinath controlled himself with visible effort. His face saddened."}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00abf4af2ff1','ch_5e5c5ef311e1','text','{"text": "‘What is to be done?’ he moaned."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_43f06bfbdd16','ch_5e5c5ef311e1','text','{"text": "‘The groom’s father is a man of stone."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59ba92603d1c','ch_5e5c5ef311e1','text','{"text": "He will break off the marriage unless cash is paid to him before the ceremony starts. Who will ever marry Beena after such dishonour?’ Satyajit wagged his head in befitting sympathy."}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7004ff6a4b34','ch_5e5c5ef311e1','text','{"text": "‘If only you had written to me. Just two words or three. Anyway, do not be worried. You will find another suitable match, a better one maybe. Who can foresee the ways of destiny?’ He felt for his purse the second time. He ought to restore the fifty rupees he had cut. Let it be Rs 151. Even if there would be no perambulator for his son— Srinath cleared his throat twice."}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9723d04346f0','ch_5e5c5ef311e1','text','{"text": "‘It shames me to tell you the full story.’"}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d60e187d52bf','ch_5e5c5ef311e1','text','{"text": "‘Yes?’"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0caf76385097','ch_5e5c5ef311e1','text','{"text": "‘Harish is willing to pay.’"}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d53582e50614','ch_5e5c5ef311e1','text','{"text": "‘What! you have just said—’"}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7071201645d','ch_5e5c5ef311e1','text','{"text": "‘He will pay against security. He wants security, that evil-eyed shark. Your house and fish-pond. The madness! To think that house and pond have more weight than a millionaire’s signature!’ Satyajit trembled within him."}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3208a477d8df','ch_5e5c5ef311e1','text','{"text": "‘House and pond,’ he murmurmed to himself."}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f66eb8b78131','ch_5e5c5ef311e1','text','{"text": "The only possessions that had not toppled into the deluge. They were all he could give to his wife—"}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a245ca2ad695','ch_5e5c5ef311e1','text','{"text": "‘All the old values destroyed, where will our India be? Has Nehru no sense to understand this? What! A pond weighs more than a millionaire’s word, a house is better security than the signature of his hand! Yet, what else is to be done?’ Palms folded together made supplication."}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fba3692cc329','ch_5e5c5ef311e1','text','{"text": "‘What else is to be done in the daughter crisis?’ Satyajit had a queer drugged look."}',122);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7d107fb11cb','ch_5e5c5ef311e1','text','{"text": "And the dead voice of the millionaire came from his throat."}',123);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94e9ea2c0ef3','ch_5e5c5ef311e1','text','{"text": "‘Let the moneylender pay on those terms.’"}',124);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d951cf66330','ch_5e5c5ef311e1','text','{"text": "‘The insult, what about the insult?’ Srinath’s wrathful hand cleaved the air."}',125);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e36b26d42fa8','ch_5e5c5ef311e1','text','{"text": "‘When the thing is done, I will make the shark rub his fat nose on the ground at your feet; I will do that, be sure. You will also see the whole village spit at the shark, thoo!’ The deed was signed, the house was gay with marriage music. Satyajit walked off to the deep dark under the fig tree, all by himself."}',126);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_206108570d45','ch_5e5c5ef311e1','text','{"text": "‘What now,’ he said under his breath, and a dim smile pinched the corners of his lips as he stuck between them the cork tip of a cigarette, the last one in the tin, and lifted a lit match with slow tremulous deliberation."}',127);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb2716a544e2','ch_5e5c5ef311e1','list','{"ordered": false, "items": ["Bhabani Bhattacharya"]}',128);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb0e418dcf35','ch_5e5c5ef311e1','heading','{"level": 2, "text": "About The Author"}',129);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd5ed3d24c6b','ch_5e5c5ef311e1','text','{"text": "Bhabani Bhattacharya (1906–1988), one of the foremost Indian writers of fiction in English, won acclaim for his novel, So Many Hungers (1947), which presents a vivid picture of the Bengal famine during World War II. He won the Sahitya Akademi Award for Shadow from Ladakh (1966). He also wrote a number of short stories."}',130);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_842efd43e930','ch_5e5c5ef311e1','text','{"text": "‘Glory at Twilight’ is taken from the collection, Steel Hawk and Other Stories."}',131);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2aac26ec114d','ch_5e5c5ef311e1','heading','{"level": 2, "text": "Understanding The Text"}',132);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26b785eacce8','ch_5e5c5ef311e1','text','{"text": "1. Give reasons for the following"}',133);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1242567011ac','ch_5e5c5ef311e1','text','{"text": "a. Satyajit attending the village wedding."}',134);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ada69b211c7','ch_5e5c5ef311e1','text','{"text": "b. Satyajit’s recollection of the forgerer when he was on the train."}',135);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f39ac4b3f658','ch_5e5c5ef311e1','text','{"text": "c. Srinath and his family members’ eager expectation of"}',136);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b39a0d0ce12','ch_5e5c5ef311e1','text','{"text": "Satyajit’s arrival."}',137);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_026e89bdd6ee','ch_5e5c5ef311e1','text','{"text": "d. Srinath’s disappointment with Satyajit."}',138);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98e8baab01ae','ch_5e5c5ef311e1','text','{"text": "e. Satyajit’s feeling that he was an impostor."}',139);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2965f4bb198','ch_5e5c5ef311e1','text','{"text": "f. Satyajit not disclosing his present financial status to his uncle."}',140);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c2d5435505d','ch_5e5c5ef311e1','text','{"text": "2. Describe the cycle of events in Satyajit’s life that brought him back to where he began."}',141);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0540cc64d48','ch_5e5c5ef311e1','heading','{"level": 2, "text": "Talking About The Text"}',142);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_13e2713852e6','ch_5e5c5ef311e1','text','{"text": "Discuss in pairs"}',143);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f47f801105a','ch_5e5c5ef311e1','text','{"text": "1. It is difficult to adjust to a fall from glory."}',144);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08e382d56cbd','ch_5e5c5ef311e1','text','{"text": "2. ‘Failure had a tempo faster than success.’"}',145);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c774cfcdd58','ch_5e5c5ef311e1','text','{"text": "3. Satyajit should have revealed his predicament to his uncle."}',146);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f620de42f48','ch_5e5c5ef311e1','text','{"text": "4. The author’s comment on crime and punishment."}',147);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85ac8066a91a','ch_5e5c5ef311e1','heading','{"level": 2, "text": "Appreciation"}',148);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65101f060094','ch_5e5c5ef311e1','text','{"text": "1. How is Satyajit’s financial crash introduced to the reader?"}',149);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65c9e537b9cc','ch_5e5c5ef311e1','text','{"text": "2. Comment on the way in which the story is narrated from"}',150);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b3f48edd0a5','ch_5e5c5ef311e1','text','{"text": "Satyajit’s perspective."}',151);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb5f31e81b5b','ch_5e5c5ef311e1','text','{"text": "3. How has the author used the episode of the bank theft to comment on Satyajit’s success in his career?"}',152);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4fed0d9f8e95','ch_5e5c5ef311e1','text','{"text": "4. How do these lines capture the essence of the story:"}',153);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc8ab423809a','ch_5e5c5ef311e1','text','{"text": "‘Glory was all overlaid with dark shame. Glory was dead.’ ‘… let him be wrapped a while in the lingering twilight splendour of departed glory’."}',154);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b77214fb5a86','ch_5e5c5ef311e1','heading','{"level": 2, "text": "Language Work"}',155);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8a0b10fd9a3','ch_5e5c5ef311e1','text','{"text": "1. Notice this description"}',156);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a8f63a3bc3e','ch_5e5c5ef311e1','text','{"text": "Tall, thin, near forty, he had sharp features, the hair receding on his temple in wide shiny patches. His eyes hated glare and he wore smart eye-glasses to shield them. His mouth, thinlipped, would tighten in response to a line that suggested strength of will but might have only been pride."}',157);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32f218e8d622','ch_5e5c5ef311e1','text','{"text": "Look at the padding of adjectives. Notice how physical features are related to mental qualities."}',158);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05fc2fccb65b','ch_5e5c5ef311e1','text','{"text": "a. Pick out other such descriptions of people from the story."}',159);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f68c855fe062','ch_5e5c5ef311e1','text','{"text": "b. Try writing out a description of a person you have observed closely."}',160);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc468e3ca62d','ch_5e5c5ef311e1','text','{"text": "2. Notice these expressions"}',161);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d98d940de53','ch_5e5c5ef311e1','text','{"text": "‘We bask in your benediction. Our life-spark itself is held in your fist.’"}',162);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ce0fdcb0f5b','ch_5e5c5ef311e1','text','{"text": "‘This is her day. Let Beena alone wash and wipe the reverent feet. All her life she will remember this honour befalling her on her auspicious day of her marriage.’"}',163);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c7f0f5b31d5','ch_5e5c5ef311e1','text','{"text": "? How do they capture the Indian idiom? ? Underline other such expressions."}',164);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9bb5fd3594a5','ch_5e5c5ef311e1','text','{"text": "3. Notice these fragments in para three of the lesson"}',165);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ff7f15b3d62','ch_5e5c5ef311e1','text','{"text": "a. The banking establishment of which he had attained control."}',166);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e101b43ba59','ch_5e5c5ef311e1','text','{"text": "b. The amazing tempo of it all."}',167);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d356d735c8cd','ch_5e5c5ef311e1','text','{"text": "These are not complete sentences but serve to capture the character’s train of thought. Such devices are often used in creative writing."}',168);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f48cd770ea2','ch_5e5c5ef311e1','heading','{"level": 2, "text": "Suggested Reading"}',169);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_548bbe4d4eb2','ch_5e5c5ef311e1','text','{"text": "1.\tAn Astrologer’s Day and other Stories by R.K. Narayan."}',170);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b621a81f35da','ch_5e5c5ef311e1','text','{"text": "*********"}',171);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_79a67a5c6bb1','bk_ncert_english','11-8-the-luncheon','11.8 The Luncheon',NULL,'public',48,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eefb6e0ca339','ch_79a67a5c6bb1','text','{"text": "I caught sight of her at the play and, in answer to her beckoning, I went over during the interval and sat down beside her. It was long since I had last seen her and if someone had not mentioned her name I hardly think I would have recognised her. She addressed me brightly."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bce9580fc13a','ch_79a67a5c6bb1','text','{"text": "‘Well, it’s many years since we first met."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39be15f88f2e','ch_79a67a5c6bb1','text','{"text": "How time does fly! We’re none of us getting any younger. Do you remember the first time I saw you? You asked me to luncheon.’"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61c840736154','ch_79a67a5c6bb1','text','{"text": "Did I remember? It was twenty years ago and I was living in Paris. I had a tiny apartment in the Latin quarter overlooking a cemetery and I was earning barely enough money to keep the body and soul together. She had read a book of mine and had written to me about it."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15c0698fa6f3','ch_79a67a5c6bb1','text','{"text": "I answered, thanking her, and presently I received from her another letter saying that she was passing through Paris and would like to have a chat with me; but her time was limited and the only free moment she had was on the following Thursday; she was spending the morning at the Luxembourg and would I give her a little luncheon at Foyot’s afterwards? Foyot’s is a restaurant at which the French senators eat and it was so far beyond my means that I had never even thought of going there."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd12191ec772','ch_79a67a5c6bb1','text','{"text": "But I was flattered and I was too young to have learned to say no to a woman. Few men, I may add, learn this until they are too old to make it of any consequence to a woman what they say. I had eighty francs (gold francs) to last me the rest of the month, and a modest luncheon should not cost more than fifteen. If I cut out coffee for the next two weeks I could manage well enough. I answered that I would meet my friend—by correspondence—at Foyot’s on Thursday at half-past twelve."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dec479a7e6f8','ch_79a67a5c6bb1','text','{"text": "She was not so young as I expected and in appearance imposing rather than attractive. She was, in fact, a woman of forty (a charming age, but not one that excites a sudden and devastating passion at first sight), and she gave me the impression of having more teeth, white and large and even, than were necessary for any practical purpose. She was talkative but since she seemed inclined to talk about me I was prepared to be an attentive listener."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a5a44321fb6','ch_79a67a5c6bb1','text','{"text": "I was startled when the bill of fare was brought for the prices were a great deal higher than I had anticipated. But she reassured me."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b34003b90470','ch_79a67a5c6bb1','text','{"text": "‘I never eat anything for luncheon.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f08e90a0a39','ch_79a67a5c6bb1','text','{"text": "She said."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_639e51aa9bb8','ch_79a67a5c6bb1','text','{"text": "‘Oh, don’t say that!’ I answered generously."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98a13f570df0','ch_79a67a5c6bb1','text','{"text": "‘I never eat more than one thing. I think people eat far too much nowadays. A little fish, perhaps. I wonder if they have any salmon.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1196bb32aa4e','ch_79a67a5c6bb1','text','{"text": "Well, it was early in the year for salmon and it was not on the bill of fare, but I asked the waiter if there was any. Yes, a beautiful salmon had just come in, it was the first they had had. I ordered it for my guest. The waiter asked her if she would have something while it was being cooked."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7a6ccd3f7d5','ch_79a67a5c6bb1','text','{"text": "‘No,’ she answered, ‘I never eat more than one thing. Unless you have a little caviare. I never mind caviare.’"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2daae79e811a','ch_79a67a5c6bb1','text','{"text": "My heart sank a little. I knew I could not afford caviare but I could not very well tell her that. I told the waiter by all means to bring caviare. For myself I chose the cheapest dish on the menu and that was a mutton chop."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ab1edbdd304','ch_79a67a5c6bb1','text','{"text": "‘I think you are unwise to eat meat,’ she said."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed5a4e2ab4d1','ch_79a67a5c6bb1','text','{"text": "‘I don’t know how you can expect to work after eating heavy things like chops."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2d213986734','ch_79a67a5c6bb1','text','{"text": "I don’t believe in overloading my stomach.’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f33a61ade9ae','ch_79a67a5c6bb1','text','{"text": "Then came the question of drink."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1067c52c36d','ch_79a67a5c6bb1','text','{"text": "‘I never drink anything for luncheon,’ she said."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c25ced41fa0f','ch_79a67a5c6bb1','text','{"text": "‘Neither do I,’ I answered promptly."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59906ecdcad7','ch_79a67a5c6bb1','text','{"text": "‘Except white wine,’ she proceeded as though I had not spoken."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e4870aa4d97','ch_79a67a5c6bb1','text','{"text": "‘These French white wines are so light. They’re wonderful for the digestion.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_801939e54411','ch_79a67a5c6bb1','text','{"text": "‘What would you like?’ I asked, hospitable still, but not exactly effusive."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6244d3ffe07','ch_79a67a5c6bb1','text','{"text": "She gave me a bright and amicable flash of her white teeth."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abab6984e52c','ch_79a67a5c6bb1','text','{"text": "‘My doctor won’t let me drink anything but Champagne.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_405a1abc4637','ch_79a67a5c6bb1','text','{"text": "I fancy I turned a trifle pale. I ordered half a bottle. I mentioned casually that my doctor had absolutely forbidden me to drink Champagne."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35614513933d','ch_79a67a5c6bb1','text','{"text": "‘What are you going to drink, then?’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1a4f1e6f9b1','ch_79a67a5c6bb1','text','{"text": "‘Water.’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ad2626f64dc','ch_79a67a5c6bb1','text','{"text": "She ate the caviare and she ate the salmon. She talked gaily of art and literature and music. But I wondered what the bill would come to. When my mutton chop arrived she took me quite seriously to task."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d8526eca11e','ch_79a67a5c6bb1','text','{"text": "‘I see that you’re in the habit of eating a heavy luncheon."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bed0db6f8bfd','ch_79a67a5c6bb1','text','{"text": "I’m sure it’s a mistake. Why don’t you follow my example and just eat one thing? I’m sure you’d feel ever so much better for it.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0d7f4ef3505','ch_79a67a5c6bb1','text','{"text": "‘I am only going to eat one thing,’ I said, as the waiter came again with the bill of fare."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a45e69e155e','ch_79a67a5c6bb1','text','{"text": "She waved him aside with an airy gesture."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f987cc37eef','ch_79a67a5c6bb1','text','{"text": "‘No, no, I never eat anything for luncheon. Just a bite, I never want more than that, and I eat that more as an excuse for conversation than anything else. I couldn’t possibly eat anything more—unless they had some of those giant asparagus. I should be sorry to leave Paris without having some of them.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_195b67a4607e','ch_79a67a5c6bb1','text','{"text": "My heart sank. I had seen them in the shops and I knew that they were horribly expensive. My mouth had often watered at the sight of them."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1093b1384ddc','ch_79a67a5c6bb1','text','{"text": "‘Madame wants to know if you have any of those giant asparagus,’ I asked the waiter."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a92a9cdae8ad','ch_79a67a5c6bb1','text','{"text": "I tried with all my might to will him to say no. A happy smile spread over his broad, priest-like face and he assured me that they had some so large, so splendid, so tender, that it was a marvel."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c47220964dc6','ch_79a67a5c6bb1','text','{"text": "‘I’m not in the least hungry,’ my guest sighed, ‘but if you insist I don’t mind having some asparagus.’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d825ff11082f','ch_79a67a5c6bb1','text','{"text": "I ordered them."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1051162ec71','ch_79a67a5c6bb1','text','{"text": "‘Aren’t you going to have any?’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd39f9f46988','ch_79a67a5c6bb1','text','{"text": "‘No, I never eat asparagus.’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82632a95f6a3','ch_79a67a5c6bb1','text','{"text": "‘I know there are people who don’t like them."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac00d4875852','ch_79a67a5c6bb1','text','{"text": "The fact is, you ruin your palate by all the meat you eat.’"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa87068b5286','ch_79a67a5c6bb1','text','{"text": "We waited for the asparagus to be cooked. Panic seized me:"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10dfa75c04f5','ch_79a67a5c6bb1','text','{"text": "it was not a question now how much money I should have left over for the rest of the month but whether I had enough to pay the bill. It would be mortifying to find myself ten francs short and be obliged to borrow from my guest. I could not bring myself to do that. I knew exactly how much I had and if the bill came to me I made up my mind that I would put my hand in my pocket and with a dramatic cry start up and say it had been picked."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b48d5aeae4a','ch_79a67a5c6bb1','text','{"text": "Of course, it would be awkward if she had not money enough either to pay the bill; then the only thing would be to leave my watch and say I would come back and pay later. The asparagus appeared. They were enormous, succulent, and appetizing. The smell of the melted butter tickled my nostrils as the nostrils of Johovah were tickled by the burned offerings of the virtuous Semites."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44f39da51151','ch_79a67a5c6bb1','text','{"text": "I watched the abandoned woman thrust them down her throat in large voluptuous mouthfuls, and, in my polite way, I discoursed on the condition of the drama in the Balkans. At last she finished."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07b6e6fb026a','ch_79a67a5c6bb1','text','{"text": "‘Coffee,’ I said..."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fac34687389e','ch_79a67a5c6bb1','text','{"text": "‘Yes, just an ice-cream and coffee,’ she answered."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d86f6e6c5a27','ch_79a67a5c6bb1','text','{"text": "I was past caring now, so I ordered coffee for myself and ice-cream and coffee for her."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9110d7a961e9','ch_79a67a5c6bb1','text','{"text": "‘You know, there’s one thing I thoroughly believe in,’ she said, as she ate the ice-cream."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4eb63c992252','ch_79a67a5c6bb1','text','{"text": "‘One should always get up from a meal feeling one could eat a little more.’"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b98fc8cabc5c','ch_79a67a5c6bb1','text','{"text": "‘Are you still hungry?’ I asked faintly."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e2c1e7a1a5f5','ch_79a67a5c6bb1','text','{"text": "‘Oh, no, I’m not hungry; you see, I don’t eat luncheon."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_207cc367bce7','ch_79a67a5c6bb1','text','{"text": "I have a cup of coffee in the morning and then dinner, but I never eat more than one thing for luncheon. I was speaking for you.’"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7218f358a50e','ch_79a67a5c6bb1','text','{"text": "‘Oh, I see!’ Then a terrible thing happened."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a068050e6118','ch_79a67a5c6bb1','text','{"text": "While we were waiting for the coffee, the headwaiter, with an ingratiating smile on his false face, came up to us bearing a large basket full of huge peaches. They had the blush of an innocent girl; they had the rich tone of an Italian landscape. But surely peaches were not in season then? Lord knew what they cost. I knew too—a little later, for my guest, going on with her conversation, absentmindedly took one."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3d163fa565c','ch_79a67a5c6bb1','text','{"text": "‘You see, you’ve filled your stomach with a lot of meat’ —my one miserable little chop—"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0bc69f147fa','ch_79a67a5c6bb1','text','{"text": "‘and you can’t eat any more."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75e9d81aa7f3','ch_79a67a5c6bb1','text','{"text": "But I’ve just had a snack and I shall enjoy a peach.’"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3d485c89bcb','ch_79a67a5c6bb1','text','{"text": "The bill came and when I paid it I found that I had only enough for a quite inadequate tip. Her eyes rested for an instant on the three francs I left for the waiter and I knew that she thought me mean. But when I walked out of the restaurant I had the whole month before me and not a penny in my pocket."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c1c80fef14d','ch_79a67a5c6bb1','text','{"text": "‘Follow my example,’ she said as we shook hands, ‘and never eat more than one thing for luncheon.’"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d07024d1910','ch_79a67a5c6bb1','text','{"text": "‘I’ll do better than that,’ I retorted."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e94f2e061d1','ch_79a67a5c6bb1','text','{"text": "‘I’ll eat nothing for dinner tonight.’"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3e664b2c567','ch_79a67a5c6bb1','text','{"text": "‘Humorist’, she cried gaily, jumping into a cab."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9868a9ed47b7','ch_79a67a5c6bb1','text','{"text": "‘You’re quite a humorist!’ But I have had my revenge at last. I do not believe that I am a vindictive man, but when the immortal gods take a hand in the matter it is pardonable to observe the result with complacency. Today she weighs twenty-one stone."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d92277f819b','ch_79a67a5c6bb1','list','{"ordered": false, "items": ["William Somerset Maugham"]}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b3a9a0e0307','ch_79a67a5c6bb1','heading','{"level": 2, "text": "About The Author"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9d51c626822','ch_79a67a5c6bb1','text','{"text": "William Somerset Maugham (1874–1965) is a distinguished British author. He was born in Paris and his childhood was spent in a Frenchspeaking society. After the death of his father, he returned to England at the age of 10. He studied at Heidelberg and at St. Thomas’s Hospital, London, and qualified as a doctor. But he preferred writing to practising medicine."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1403704ae565','ch_79a67a5c6bb1','text','{"text": "During his long career as a writer, Maugham produced a large number of novels, plays and short stories. Some of his best novels include Of Human Bondage, The Moon and Sixpence and Cakes and Ale."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b50edf2a1331','ch_79a67a5c6bb1','text','{"text": "Maugham has an amazing skill for revealing, with a few touches, a situation and the essentials of a character, and his stories are told with a lucidity and an economy of words which are the marks of a supreme craftsman."}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34c3275a8bcc','ch_79a67a5c6bb1','heading','{"level": 2, "text": "Understanding The Text"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a758f2c00262','ch_79a67a5c6bb1','text','{"text": "1. Although the author was not a vindictive man he was very happy to see the twenty one stone lady who had impoverished him twenty years ago, and says he had finally had his revenge. What makes him says this?"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce27e7b0b0b4','ch_79a67a5c6bb1','text','{"text": "2. There are quite a few places where the author uses the expressions ‘my heart sank’, ‘panic seized’ etc. What was the reason for this?"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b22da34c9404','ch_79a67a5c6bb1','text','{"text": "3. Locate instances of irony in the story."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f84bd908b32','ch_79a67a5c6bb1','heading','{"level": 2, "text": "Talking About The Text"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_548472f1ddaf','ch_79a67a5c6bb1','text','{"text": "Discuss in pairs or in small groups"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7f3149494a39','ch_79a67a5c6bb1','text','{"text": "1. People with foibles are often not conscious of them."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a4c946585bc','ch_79a67a5c6bb1','text','{"text": "2. The author’s attempts at keeping up his pretence of friendliness while he was mentally preoccupied with the expense of the luncheon."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3143b831ac88','ch_79a67a5c6bb1','heading','{"level": 2, "text": "Appreciation"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45a0d01414a1','ch_79a67a5c6bb1','text','{"text": "1. The author is a humorist"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f846d10dbe1','ch_79a67a5c6bb1','text','{"text": "a. How does the story reflect his sense of humour?"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_954859aa6a5e','ch_79a67a5c6bb1','text','{"text": "b. What makes his lady friend remark—‘you are quite a humorist’?"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3df9617712a2','ch_79a67a5c6bb1','text','{"text": "c. Give instances of the author’s ability to laugh at himself."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01eab0968f1d','ch_79a67a5c6bb1','text','{"text": "2. How does the first person narrative help in heightening the literary effects of the story?"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19fb588957de','ch_79a67a5c6bb1','heading','{"level": 2, "text": "Language Work"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9df2fc99303f','ch_79a67a5c6bb1','text','{"text": "? Pick out the words and phrases in the text that indicate that the author was not financially well off."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1f83c73061a','ch_79a67a5c6bb1','heading','{"level": 2, "text": "Suggested Reading"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9592c54c57bb','ch_79a67a5c6bb1','text','{"text": "1. ‘The Phantom Luncheon’ by Saki"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dacf657d8e13','ch_79a67a5c6bb1','text','{"text": "2. ‘The Ant and the Grasshopper’ by W. Somerset Maugham."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88c3b25d525e','ch_79a67a5c6bb1','text','{"text": "*********"}',92);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_fde53d625e52','bk_ncert_english','11-9-the-peacock','11.9 The Peacock',NULL,'public',49,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b716399ae14b','ch_fde53d625e52','text','{"text": "His loud sharp call seems to come from nowhere."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14fe5d2a9978','ch_fde53d625e52','text','{"text": "Then, a flash of turquoise in the pipal tree"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8121b228cebb','ch_fde53d625e52','text','{"text": "The slender neck arched away from you as he descends,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4864fe25ae7f','ch_fde53d625e52','text','{"text": "and as he darts away, a glimpse of the very end of his tail."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f871930543a','ch_fde53d625e52','text','{"text": "I was told"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ad98eb29592','ch_fde53d625e52','text','{"text": "that you have to sit in the veranda"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6b06ab8eefb','ch_fde53d625e52','text','{"text": "And read a book, preferably one of your favourites with great concentration.."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8a070fe7b0a','ch_fde53d625e52','text','{"text": "The moment you begin to live inside the book"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b19722ebd865','ch_fde53d625e52','text','{"text": "A blue shadow will fall over you."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_352a48d1a7bb','ch_fde53d625e52','text','{"text": "The wind will change direction,"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_871f03fc9235','ch_fde53d625e52','text','{"text": "The steady hum of bees"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0caf7ef61848','ch_fde53d625e52','text','{"text": "In the bushes nearby will stop."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6775d38bfdc0','ch_fde53d625e52','text','{"text": "The cat will awaken and stretch."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b47b97db630b','ch_fde53d625e52','text','{"text": "Something has broken your attention;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3c1187f98b5','ch_fde53d625e52','text','{"text": "And if you look up in time"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a1bf2250d39','ch_fde53d625e52','text','{"text": "You might see the peacock turning away as he gathers his tail"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ad750f485fe','ch_fde53d625e52','text','{"text": "To shut those dark glowing eyes, Violet fringed with golden amber."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_604c911fda2b','ch_fde53d625e52','text','{"text": "It is the tail that has to blink"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3584707f721','ch_fde53d625e52','text','{"text": "For eyes that are always open."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c396c33e7afc','ch_fde53d625e52','list','{"ordered": false, "items": ["Sujata Bhatt"]}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21f1525bd03a','ch_fde53d625e52','heading','{"level": 2, "text": "About The Poet"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_978cd63b1c36','ch_fde53d625e52','text','{"text": "Sujata Bhatt (born 1956)) was educated in the USA and now lives in Germany. She won the Commonwealth Poetry Prize for the Asia section for her collection of poems, Brunizem (1988), from which ‘The Peacock’ is taken. Two other books of poems by her are Monkey Shadows (1991) and The Stinking Rose (1994). She has also translated Gujarati poetry into English."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17794a8d5b22','ch_fde53d625e52','text','{"text": "? Notice these words in the poem and guess their meaning from the context"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c436e16cb46e','ch_fde53d625e52','heading','{"level": 2, "text": "Understanding The Poem"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b0c49160a59','ch_fde53d625e52','text','{"text": "1. Comment on the lines that make you visualise the colourful image of the peacock."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a154e5d67877','ch_fde53d625e52','text','{"text": "2. What are the cues that signal the presence of the peacock in the vicinity?"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df84dc323635','ch_fde53d625e52','text','{"text": "3. How does the connection drawn between the tail and the eyes add to the descriptive detail of the poem?"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48c666e5e3c6','ch_fde53d625e52','text','{"text": "4. How does the poem capture the elusive nature of the peacock?"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92f95fc33d67','ch_fde53d625e52','text','{"text": "5. The peacock is a colourful bird. How does the poem capture the various colours that its plumage displays?"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54bce4d07302','ch_fde53d625e52','heading','{"level": 2, "text": "Try This Out"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5cfad34b5887','ch_fde53d625e52','text','{"text": "1. In English the peacock is associated with pride. ‘As proud as a peacock’ is a commonly used simile. With what qualities is the peacock associated in the literature of your language?"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c2a1a1f76c7','ch_fde53d625e52','text','{"text": "2. The peacock is the national bird of India. Why do you think the peacock has been chosen?"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9b12fdfe809','ch_fde53d625e52','heading','{"level": 2, "text": "Suggested Reading"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6a3fe836332','ch_fde53d625e52','text','{"text": "1.\t‘The Bangle Sellers’ by Sarojini Naidu."}',34);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_17bd00f1e946','bk_ncert_english','11-10-let-me-not-to-the-marriage-of-true-minds','11.10 Let Me Not to the Marriage of True Minds',NULL,'public',50,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_274dce5de5ee','ch_17bd00f1e946','text','{"text": "Let me not to the marriage of true minds"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98be5eb75812','ch_17bd00f1e946','text','{"text": "Admit impediments. Love is not love"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e95eab7749b','ch_17bd00f1e946','text','{"text": "Which alters when it alteration finds,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_157900a045b5','ch_17bd00f1e946','text','{"text": "Or bends with the remover to remove."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_160b7625049c','ch_17bd00f1e946','text','{"text": "O no, it is an ever-fixed mark"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0349e5c02137','ch_17bd00f1e946','text','{"text": "That looks on tempests and is never shaken;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6d07da53a85','ch_17bd00f1e946','text','{"text": "It is the star to every wandering bark,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d45a8a93a66d','ch_17bd00f1e946','text','{"text": "Whose worth’s unknown, although his height be taken."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_724a10724b5f','ch_17bd00f1e946','text','{"text": "Love’s not Time’s fool, though rosy lips and cheeks"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de372745fa9c','ch_17bd00f1e946','text','{"text": "Within his bending sickle’s compass come;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46d16635fa82','ch_17bd00f1e946','text','{"text": "Love alters not with his brief hours and weeks,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d75cce2b0162','ch_17bd00f1e946','text','{"text": "But bears it out even to the edge of doom."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_761a5f50a2f7','ch_17bd00f1e946','text','{"text": "If this be error, and upon me proved, I never writ, nor no man ever loved."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2802aeb8f77d','ch_17bd00f1e946','list','{"ordered": false, "items": ["William Shakespeare"]}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66c9b84d9d1f','ch_17bd00f1e946','heading','{"level": 2, "text": "About The Poet"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09566abbb55e','ch_17bd00f1e946','text','{"text": "William Shakespeare (1564–1616) was one of the greatest poets and dramatists of the English language. Born at Stratford-on-Avon, England, he went to London where his reputation as a dramatist and poet was established. His Sonnets,"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70caf9f9598e','ch_17bd00f1e946','text','{"text": "154 in number, probably written between 1593 and 1598, were  published in 1602. The above sonnet is sonnet number 116 in which we have a depiction of true love. His voluminous work includes 37 plays and two narrative poems."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eeb52554806d','ch_17bd00f1e946','text','{"text": "? The following two common words are used in a different sense in the poem. Guess what they mean"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdf9c442469d','ch_17bd00f1e946','heading','{"level": 2, "text": "Understanding The Poem"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7fdbaa5e051e','ch_17bd00f1e946','text','{"text": "1. ‘Constancy’ is the theme of the poem. Indicate the words, phrases and images that suggest the theme."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b80c46d95bbc','ch_17bd00f1e946','text','{"text": "2. Why do you think the poet has used so many ‘negatives’ to make his statement?"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d66dc05c244d','ch_17bd00f1e946','text','{"text": "3. What does the line ‘I never writ, nor no man ever loved’ imply?"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91b5502c1c55','ch_17bd00f1e946','text','{"text": "4. Love is presented as the subject or doer of actions in the poem. Why do you think the poet has used this form rather than involving human agents?"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03a85ed84c9b','ch_17bd00f1e946','text','{"text": "5. Explain the phrases"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d7d86a1e569','ch_17bd00f1e946','text','{"text": "a. his bending sickle’s compass"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84512c234102','ch_17bd00f1e946','text','{"text": "b. Time’s fool"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1a25edc3887','ch_17bd00f1e946','heading','{"level": 2, "text": "Try This Out"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a8404432650','ch_17bd00f1e946','text','{"text": "This poem is a Shakespearean sonnet."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4d979a61604','ch_17bd00f1e946','text','{"text": "1. What do you understand by a sonnet?"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39d15fd93d89','ch_17bd00f1e946','text','{"text": "2. Look at some other sonnets and notice the variations in the structure of the sonnet that are possible."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7bebb8c3ca1','ch_17bd00f1e946','heading','{"level": 2, "text": "Suggested Reading"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd93b19fd87c','ch_17bd00f1e946','text','{"text": "1.\t“Shall I Compare Thee’ by William Shakespeare."}',32);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_1c0aeb275763','bk_ncert_english','11-11-coming','11.11 Coming',NULL,'public',51,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18ad2dcfab19','ch_1c0aeb275763','text','{"text": "On longer evenings,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9d1818eb7db','ch_1c0aeb275763','text','{"text": "Light, chill and yellow,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82ab96dd2fef','ch_1c0aeb275763','text','{"text": "Bathes the serene"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_725c77dba882','ch_1c0aeb275763','text','{"text": "Foreheads of houses."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_489c60fbaac0','ch_1c0aeb275763','text','{"text": "A thrush sings,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e71e7681dcac','ch_1c0aeb275763','text','{"text": "Laurel-surrounded"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b14205e6ae2','ch_1c0aeb275763','text','{"text": "In the deep bare garden,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ff28eaf97a6','ch_1c0aeb275763','text','{"text": "Its fresh-peeled voice"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c1d6d2d405c','ch_1c0aeb275763','text','{"text": "Astonishing the brickwork."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c499392f1486','ch_1c0aeb275763','text','{"text": "It will be spring soon,"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_616f76364a48','ch_1c0aeb275763','text','{"text": "It will be spring soon—"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dac0e2919ff9','ch_1c0aeb275763','text','{"text": "And I, whose childhood"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1f2636a79dc','ch_1c0aeb275763','text','{"text": "Is a forgotten boredom, Feel like a child"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3ce5c70be01','ch_1c0aeb275763','text','{"text": "Who comes on a scene"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6293c0e43f14','ch_1c0aeb275763','text','{"text": "Of adult reconciling,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d93ec657ff7a','ch_1c0aeb275763','text','{"text": "And can understand nothing But the unusual laughter, And starts to be happy."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e95771a98d93','ch_1c0aeb275763','list','{"ordered": false, "items": ["Philip Larkin"]}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ebb4bcb2de48','ch_1c0aeb275763','heading','{"level": 2, "text": "About The Poet"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17577f32fb10','ch_1c0aeb275763','text','{"text": "Philip Larkin (1922–1985) was born in Coventry,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_287a2fd60281','ch_1c0aeb275763','text','{"text": "England. He is well-known as a leader of ‘Movement’ in English Poetry in the fifties. The principal works of Philip Larkin are The North Ship, The Less Deceived, The Whitsun Weddings"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc8e0757f536','ch_1c0aeb275763','text','{"text": "and High Windows. His themes—love, change, disenchantment, the mystery, the inexplicableness of the poet’s survival and death’s inevitability—are universally liked by the readers. The above poem has been taken from the volume, The Less Deceived, which establishes a kinship with the environment."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5bfe8bdd5dc','ch_1c0aeb275763','heading','{"level": 2, "text": "Understanding The Poem"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bb8a86bc098','ch_1c0aeb275763','text','{"text": "1. What does the bird in the poem announce? How is this related to the title, ‘Coming’?"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adf4e89b8855','ch_1c0aeb275763','text','{"text": "2. Why is the speaker’s childhood described as ‘a forgotten boredom’?"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a8ad2b08d89','ch_1c0aeb275763','text','{"text": "3. What causes the element of surprise when the child comes on the scene of ‘adult reconciling’?"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b910969b0877','ch_1c0aeb275763','text','{"text": "4. What two things are compared in the poem?"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15c98d10b110','ch_1c0aeb275763','text','{"text": "5. How do you respond to these lines?"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c8c07e8ca4d','ch_1c0aeb275763','text','{"text": "Light, chill and yellow,"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e16c2c33732','ch_1c0aeb275763','text','{"text": "Bathes the serene"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25a52a6ce479','ch_1c0aeb275763','text','{"text": "Foreheads of houses"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3e42a33ef5f','ch_1c0aeb275763','text','{"text": "6. Comment on the use of the phrase ‘fresh-peeled voice’."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf91c2afdf3b','ch_1c0aeb275763','heading','{"level": 2, "text": "Try This Out"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3aba95c4fee9','ch_1c0aeb275763','text','{"text": "1. The song of a bird is often the first sign of spring. Do you know the bird that signals the advent of vasant or spring in our country?"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be51de5986e9','ch_1c0aeb275763','text','{"text": "2. Do you know of other spring poems? How is this poem different from them?"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e2bec9537e3','ch_1c0aeb275763','heading','{"level": 2, "text": "Suggested Reading"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7781f2ea98a0','ch_1c0aeb275763','text','{"text": "1.\t‘Ambulances’ by Philip Larkin."}',36);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_ec0964255434','bk_ncert_english','11-12-telephone-conversation','11.12 Telephone Conversation',NULL,'public',52,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_947887e0f698','ch_ec0964255434','text','{"text": "The price seemed reasonable, location"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39f7683575aa','ch_ec0964255434','text','{"text": "Indifferent. The landlady swore she lived"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3e4bca90c8a','ch_ec0964255434','text','{"text": "Off premises. Nothing remained"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_181f7c0c7bf2','ch_ec0964255434','text','{"text": "But self-confession. ‘Madam,’ I warned,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_692b18d8a928','ch_ec0964255434','text','{"text": "‘I hate a wasted journey—I am African.’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0bbaf63ee90','ch_ec0964255434','text','{"text": "Silence. Silenced transmission of"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c3e89662fe85','ch_ec0964255434','text','{"text": "Pressurised good-breeding. Voice, when it came,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e862cb54aa48','ch_ec0964255434','text','{"text": "Lipstick coated, long gold-rolled"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cebde9021e7','ch_ec0964255434','text','{"text": "Cigarette-holder pipped. Caught I was, foully."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98c373d0e653','ch_ec0964255434','text','{"text": "‘HOW DARK ?’... I had not misheard... ‘ARE YOU LIGHT"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e19bce46ea74','ch_ec0964255434','text','{"text": "OR VERY DARK ?’ Button B. Button A. Stench"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a641aeab3582','ch_ec0964255434','text','{"text": "Of rancid breath of public hide-and-speak."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d35277b8b8bf','ch_ec0964255434','text','{"text": "Red booth. Red pillar-box. Red double-tiered"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53f54534d1db','ch_ec0964255434','text','{"text": "Omnibus squelching tar. It was real! Shamed"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_071cc3feaf3f','ch_ec0964255434','text','{"text": "By ill-mannered silence, surrender"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea5830473612','ch_ec0964255434','text','{"text": "Pushed dumbfounded to beg simplification."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_077fadd652f0','ch_ec0964255434','text','{"text": "Considerate she was, varying the emphasis—"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_453821366a32','ch_ec0964255434','text','{"text": "‘ARE YOU DARK? OR VERY LIGHT?’ Revelation came."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6256697ede5c','ch_ec0964255434','text','{"text": "‘You mean—like plain or milk chocolate?’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3765189cb19c','ch_ec0964255434','text','{"text": "Her assent was clinical, crushing in its light"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a48bc25b389','ch_ec0964255434','text','{"text": "Impersonality. Rapidly, wave-length adjusted,"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56fc5e540bb0','ch_ec0964255434','text','{"text": "I chose. ‘West African sepia’—and as afterthought,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63c679b189e1','ch_ec0964255434','text','{"text": "“down in my passport.” Silence for spectroscopic"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53c4a09a293b','ch_ec0964255434','text','{"text": "Flight of fancy, till truthfulness changed her accent"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_412bb82db8e8','ch_ec0964255434','text','{"text": "Hard on the mouthpiece. ‘WHAT’S THAT?’ conceding"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18d2a3720cbb','ch_ec0964255434','text','{"text": "‘DON’T KNOW WHAT THAT IS.’ ‘Like brunette.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b890320b6c24','ch_ec0964255434','text','{"text": "‘THAT’S DARK, ISN’T IT?’ ‘Not altogether."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91b8f2e0e16b','ch_ec0964255434','text','{"text": "Facially, I am brunette, but madam, you should see"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7fa87466fe1e','ch_ec0964255434','text','{"text": "The rest of me. Palm of my hand, soles of my feet"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b963ed68c0b','ch_ec0964255434','text','{"text": "Are a peroxide blonde. Friction, caused—"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cbfa13fffdf','ch_ec0964255434','text','{"text": "Foolishly madam—by sitting down, has turned"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b4b7187c5da','ch_ec0964255434','text','{"text": "My bottom raven black—One moment madam!’—sensing"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51770484b6ad','ch_ec0964255434','text','{"text": "Her receiver rearing on the thunderclap"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90ee5a4d5ff8','ch_ec0964255434','text','{"text": "About my ears—‘Madam,’ I pleaded, ‘wouldn’t you rather See for yourself ?’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65f0be3c8d3d','ch_ec0964255434','list','{"ordered": false, "items": ["Wole Soyinka"]}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8799a9660a66','ch_ec0964255434','heading','{"level": 2, "text": "About The Poet"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3db9fbade73a','ch_ec0964255434','text','{"text": "Wole Soyinka (born 1934), is a famous Nigerian poet and playwright. He was educated at the Government College in Ibadan, Nigeria and, later, at Leeds University, England, where he took a degree in English. He taught in the London schools and also worked in the Royal Court Theatre. He returned to Nigeria when he was about twenty-five."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fffaed63f5ad','ch_ec0964255434','text','{"text": "He has been one of the leading figures in Nigerian theatre, writing a number of successful plays and also leading a theatrical company."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96daf1e1e7a4','ch_ec0964255434','text','{"text": "He is the first African to receive the Nobel Prize for literature (1986). His writings are known for their humour and satire."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3d565bc95e6','ch_ec0964255434','heading','{"level": 2, "text": "Understanding The Poem"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7b5eb6d5ab9','ch_ec0964255434','text','{"text": "1. State the central issue in the poem."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_352b70a5b7b1','ch_ec0964255434','text','{"text": "2. There are intervals of silence in the interaction between the landlady and the prospective tenant. What are the reasons for this?"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa2d0ea6b7cb','ch_ec0964255434','text','{"text": "3. How is colour highlighted in the poem and why? List all the words in the poem that suggest colour."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b44b8844ab2','ch_ec0964255434','text','{"text": "4. Which are the lines in the poem that impressed you the most and why?"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26d65ee94969','ch_ec0964255434','text','{"text": "5. You know what ‘hide-and-seek’ is. What would ‘hide-and-speak’ mean?"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5eecfeae6f86','ch_ec0964255434','text','{"text": "6. Certain words in the poem are in capital letters—why?"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_716b75f3b668','ch_ec0964255434','text','{"text": "7. Why do you think that the poet has chosen the title ‘Telephone Conversation’? If you were to suggest another title for the poem, what would it be?"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_615ed4373d69','ch_ec0964255434','text','{"text": "8. The power of poetry lies in suggestion and understatement."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9203d43e1836','ch_ec0964255434','text','{"text": "Discuss this with reference to the poem."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97099a7e3f3b','ch_ec0964255434','heading','{"level": 2, "text": "Try This Out"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55fde069d7a1','ch_ec0964255434','text','{"text": "1. Enact the conversation bits with your partner."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9330a90ac5f','ch_ec0964255434','text','{"text": "2. Attempt a description of"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80a26d60b617','ch_ec0964255434','text','{"text": "a. the place from which the call was made"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c8cd6d5be5b','ch_ec0964255434','text','{"text": "b. the lady at the other end"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12ee5f33ec93','ch_ec0964255434','text','{"text": "c. the speaker in the poem."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cdb5110a5f3a','ch_ec0964255434','text','{"text": "3. The poem evokes a mental picture of the scene. Draw a rough sketch to illustrate the episode."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21b85fff095d','ch_ec0964255434','text','{"text": "4. The poem ends with ‘Wouldn’t you rather see for yourself?’. Imagine a personal encounter between the two people in the poem and write down the dialogue they might have had."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6e7928e68e9','ch_ec0964255434','heading','{"level": 2, "text": "Suggested Reading"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a1eec57fb9a','ch_ec0964255434','text','{"text": "1. Idanre and other Poems (1967) by Wole Soyinka"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eeab23869938','ch_ec0964255434','text','{"text": "2. Poems from Prison (1969) by Wole Soyinka."}',60);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_cf724c7393b0','bk_ncert_english','11-13-the-world-is-too-much-with-us','11.13 The World is too Much With Us',NULL,'public',53,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70ca73a7824b','ch_cf724c7393b0','text','{"text": "The World is too much with us; late and soon,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09b2b9ae3512','ch_cf724c7393b0','text','{"text": "Getting and spending, we lay waste our powers:"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_978e96e0e849','ch_cf724c7393b0','text','{"text": "Little we see in Nature that is ours;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e15924e2fdfb','ch_cf724c7393b0','text','{"text": "We have given our hearts away, a sordid boon!"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d951b7ce5f9b','ch_cf724c7393b0','text','{"text": "The Sea that bares her bosom to the moon;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1706da76770','ch_cf724c7393b0','text','{"text": "The Winds that will be howling at all hours,"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f4c0dc7ce5c','ch_cf724c7393b0','text','{"text": "And are up-gathered now like sleeping flowers,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80ff36b9020f','ch_cf724c7393b0','text','{"text": "For this, for everything, we are out of tune;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_172c7948c46b','ch_cf724c7393b0','text','{"text": "It moves us not.—Great God! I’d rather be"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62e828a9a7ea','ch_cf724c7393b0','text','{"text": "A Pagan suckled in a creed outworn;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb1168fe0b0b','ch_cf724c7393b0','text','{"text": "So might I, standing on this pleasant lea,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_947cef510aeb','ch_cf724c7393b0','text','{"text": "Have glimpses that would make me less forlorn;"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76393ff081b3','ch_cf724c7393b0','text','{"text": "Have sight of Proteus rising from the sea;"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b050b92b958b','ch_cf724c7393b0','text','{"text": "Or hear old Triton blow his wreathèd horn."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79d2700b119e','ch_cf724c7393b0','list','{"ordered": false, "items": ["William Wordsworth"]}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d65df7d487c','ch_cf724c7393b0','text','{"text": "Pagan: a person whose religious beliefs do not belong to any of the main religions of the world."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ce91c0ffa28','ch_cf724c7393b0','text','{"text": "Proteus: a character in Greek mythology who had the gift of prophecy but who, when questioned, would assume different shapes to elude their grasp."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e0c5b17e7c4','ch_cf724c7393b0','text','{"text": "Triton: a sea-deity in Greek mythology, who is generally represented as blowing a shell, his body above the waist being that of a man, below it of a dolphin."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_424f741b93e6','ch_cf724c7393b0','heading','{"level": 2, "text": "About The Poet"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_862d82213c41','ch_cf724c7393b0','text','{"text": "William Wordsworth (1770-1850) spent most of his life in the Lake district of northern England, and the many hours that he spent wandering about the hills and woods led to the production of some of the finest poetry on nature. His work Lyrical Ballads, co-authored with Coleridge in 1798, is regarded as the beginning of the English Romantic Movement."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c888782a5cb','ch_cf724c7393b0','text','{"text": "He selected subjects from nature and rustic life. He held the view that the language of poetry should be simple and natural."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_276017ec223f','ch_cf724c7393b0','heading','{"level": 2, "text": "Understanding The Poem"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_861bc0754223','ch_cf724c7393b0','text','{"text": "1. Why does the poet prefer to be a primitive Pagan rather than a member of civilised society?"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30daf5f9dd30','ch_cf724c7393b0','text','{"text": "2. What, according to the poet, are human beings out of tune with?"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53ce6958ab4a','ch_cf724c7393b0','heading','{"level": 2, "text": "Try This Out"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00f2781bcb5a','ch_cf724c7393b0','text','{"text": "? Compare the organisation of this sonnet with that of the sonnet by William Shakespeare."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_273baddcdc1c','ch_cf724c7393b0','heading','{"level": 2, "text": "Suggested Reading"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e441208fd95','ch_cf724c7393b0','text','{"text": "1. ‘To the Cuckoo’ by William Wordsworth"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_562e18504026','ch_cf724c7393b0','text','{"text": "2. ‘The Solitary Reaper’ by William Wordsworth."}',29);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_2b5beb986d70','bk_ncert_english','11-14-mother-tongue','11.14 Mother Tongue',NULL,'public',54,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_617df816abf4','ch_2b5beb986d70','text','{"text": "I approached a stem"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f24473340cef','ch_2b5beb986d70','text','{"text": "Swinging on a reed"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d65248925934','ch_2b5beb986d70','text','{"text": "And asked him"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23771ce90a04','ch_2b5beb986d70','text','{"text": "To give me a quill."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa6546140115','ch_2b5beb986d70','text','{"text": "Irritated, he said I gave you one only the other day"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_395844553f93','ch_2b5beb986d70','text','{"text": "A new one, what have you done with it?"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b28ed1d4f893','ch_2b5beb986d70','text','{"text": "Are you some sort of an accountant"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ead24145db28','ch_2b5beb986d70','text','{"text": "With some Shah"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58605d64a73b','ch_2b5beb986d70','text','{"text": "Writing account books"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5a6adb04780','ch_2b5beb986d70','text','{"text": "Where you need a new pen Every other day he asked."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee1b806de6fb','ch_2b5beb986d70','text','{"text": "No, I don’t work for a Shah"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56166efd3c32','ch_2b5beb986d70','text','{"text": "I said, but for a Shahni, very kind,"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa889689ff4e','ch_2b5beb986d70','text','{"text": "Very well off"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccde75a79f27','ch_2b5beb986d70','text','{"text": "And I am not the only one"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d9ca0f1ebe3','ch_2b5beb986d70','text','{"text": "Working for her"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b40b122cbf20','ch_2b5beb986d70','text','{"text": "She has many servants"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_939d99a3d212','ch_2b5beb986d70','text','{"text": "Ever ready to do her bidding"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abe235c86b98','ch_2b5beb986d70','text','{"text": "That Shahni is my mother tongue"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35f27b3ee895','ch_2b5beb986d70','text','{"text": "Dogri"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7f46a587ac2','ch_2b5beb986d70','text','{"text": "Give me, a quill, quickly"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2b7e53d0fa1','ch_2b5beb986d70','text','{"text": "She must be looking for me"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6d4a6317933','ch_2b5beb986d70','text','{"text": "The reed cut off its hand"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8a6ad2e7f97','ch_2b5beb986d70','text','{"text": "Gave it to me and said"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_159a37243454','ch_2b5beb986d70','text','{"text": "Take it"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6455e28cb12','ch_2b5beb986d70','text','{"text": "I too am her servant."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f33f179c3dbb','ch_2b5beb986d70','list','{"ordered": false, "items": ["Padma Sachdev"]}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afbea7590ab8','ch_2b5beb986d70','heading','{"level": 2, "text": "About The Poet"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2591879a2afa','ch_2b5beb986d70','text','{"text": "Padma Sachdev (born 1940) writes in her mother tongue Dogri and in Hindi. She has received many awards for her poetry, including the Sahitya Academi Award she received at the age of thirty for her first collection of Dogri poems. The above poem, translated from the original Dogri, bemoans the deprivation of Dogri of its native script Sharade, that evolved from the original Brahmi around the time Dogri developed. Once widely used by the people of all religions in the valley, Sharade, for various reasons, came to be replaced by the Persian script. Presently both Persian and Devanagri (Hindi and Urdu) scripts are used for Dogri, a language listed in Schedule VIII of the Constitution of India."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ecc8dfd4b2a5','ch_2b5beb986d70','heading','{"level": 2, "text": "Understanding The Poem"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88edfb3021b5','ch_2b5beb986d70','text','{"text": "1. The quill is the central element in the poem—what does it symbolise?"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0cf8fff45661','ch_2b5beb986d70','text','{"text": "2. You notice a sense of urgency in the poet’s request—what is the reason for this?"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c9649446332','ch_2b5beb986d70','text','{"text": "3. How has the poet brought out her emotional attachment to her mother tongue?"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0801544b199d','ch_2b5beb986d70','text','{"text": "4. Personification is a figure of speech that attributes human qualities to inanimate things and abstract ideas. How has it been used in this poem?"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1373fdd8600','ch_2b5beb986d70','heading','{"level": 2, "text": "Try This Out"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae2947f64735','ch_2b5beb986d70','text','{"text": "1. Talk to five people from different spheres of society around you and ask them the number of languages they know and use for various purposes. Try to gather information about their attitude to the different languages they know and use."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_022005459157','ch_2b5beb986d70','text','{"text": "2. Dogri is a language spoken in parts of Jammu and Kashmir, Himachal Pradesh and Punjab. Its earliest mention is in Amir Khusro’s list of Indian languages. It does not have a script of its own. It is written in either the Devnagari or the Persian script. Find out about other Indian languages that are spoken but do not have a script of their own."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8500b733c49','ch_2b5beb986d70','heading','{"level": 2, "text": "Suggested Reading"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_619a6f745b49','ch_2b5beb986d70','text','{"text": "1.\t‘Hindi’ by Raghuvir Sahay."}',38);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_99019e22283a','bk_ncert_english','11-15-hawk-roosting','11.15 Hawk Roosting',NULL,'public',55,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_beefed6864a1','ch_99019e22283a','text','{"text": "I sit in the top of the wood, my eyes closed."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfcf4879319f','ch_99019e22283a','text','{"text": "Inaction, no falsifying dream"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc72e482e22c','ch_99019e22283a','text','{"text": "Between my hooked head and hooked feet:"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2791a7911e50','ch_99019e22283a','text','{"text": "Or in sleep rehearse perfect kills and eat."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_183d57c4164f','ch_99019e22283a','text','{"text": "The convenience of the high trees!"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82e57ea38dca','ch_99019e22283a','text','{"text": "The air’s buoyancy and the sub’s ray"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce7d28435ecd','ch_99019e22283a','text','{"text": "Are of advantage to me;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20d986d3e2ac','ch_99019e22283a','text','{"text": "And the earth’s face upward for my inspection."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6228abed37a2','ch_99019e22283a','text','{"text": "My feet are locked upon the rough bark. It took the whole of Creation"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8e1e29ce4cb','ch_99019e22283a','text','{"text": "To produce my foot, my each feather: Now I hold Creation in my foot."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d242f6519756','ch_99019e22283a','text','{"text": "Or fly up, and revolve it all slowly—"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44222805dfc7','ch_99019e22283a','text','{"text": "I kill where I please because it is all mine."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db2f460d9be3','ch_99019e22283a','text','{"text": "There is no sophistry in my body:"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91d6f24508b2','ch_99019e22283a','text','{"text": "My manners are tearing off heads."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_818afd58ff17','ch_99019e22283a','text','{"text": "The allotment of death."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6feb7b101c55','ch_99019e22283a','text','{"text": "For the one path of my flight is direct"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e2a42b96440','ch_99019e22283a','text','{"text": "Through the bones of the living. No arguments assert my right."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_066535baf15e','ch_99019e22283a','text','{"text": "The sun is behind me. Nothing has changed since I began,"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76a3e049b2ac','ch_99019e22283a','text','{"text": "My eye has permitted no change."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8bb2df71c7e4','ch_99019e22283a','text','{"text": "I am going to keep things like this."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6d50b4bb0d1','ch_99019e22283a','list','{"ordered": false, "items": ["Ted Hughes"]}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd81a7c74fc2','ch_99019e22283a','heading','{"level": 2, "text": "About The Poet"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_172ca1b1fb62','ch_99019e22283a','text','{"text": "Ted Hughes (1930–1998) completed his education at Pembroke College, Cambridge. In 1956, he married the poet Sylvia Plath. He tried to make a living in America by teaching and writing. Finally, he returned to England."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5639d7a54b2','ch_99019e22283a','text','{"text": "The most remarkable quality of Hughes’ poems is an intense and obsessive fascination with the world of birds and animals; and though essentially about birds, animals and fishes, his poems shock us with unusual phrases and violent images."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68ba959bb272','ch_99019e22283a','text','{"text": "The above poem is in the form of a monologue."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18912e316529','ch_99019e22283a','text','{"text": "? Notice the use of the following phrases in the poem and guess what they mean in the context"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d07af5bbaefe','ch_99019e22283a','text','{"text": "air’s buoyancy               sophistry in my body"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d0c4a27f1b9','ch_99019e22283a','heading','{"level": 2, "text": "Understanding The Poem"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24392b6907f8','ch_99019e22283a','text','{"text": "1. Comment on the physical features of the hawk highlighted in the poem and their significance."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db6e22e539de','ch_99019e22283a','text','{"text": "2. How does the poem emphasise the physical prowess of the hawk?"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c438a7a0d24','ch_99019e22283a','text','{"text": "3. ‘There is no sophistry in my body’—this statement expresses the brutal frankness of the hawk. Does the poet suggest something through this statement?"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93e7dd82c116','ch_99019e22283a','text','{"text": "4. ‘Now I hold Creation in my foot’—explain the centrality of this assertion in the poem. What makes the hawk’s assertion of its invincibility so categorical?"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79abe5bb5efb','ch_99019e22283a','text','{"text": "5. Why is the poem entitled ‘Hawk Roosting’?"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec7de310aa2c','ch_99019e22283a','text','{"text": "6. Bring out the parallel suggested between the predatory instincts of the bird and human behaviour."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49f1983d6be9','ch_99019e22283a','heading','{"level": 2, "text": "Try This Out"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f0f41137ae8','ch_99019e22283a','text','{"text": "1. Consult a dictionary or an encyclopedia to differentiate between the following birds"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e674cf00f699','ch_99019e22283a','text','{"text": "2. To what aspects of human behaviour do the following adjectives apply"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_322c2376f0b6','ch_99019e22283a','heading','{"level": 2, "text": "Suggested Reading"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1342be9f9ba5','ch_99019e22283a','text','{"text": "1. ‘The Lake’ by Ted Hughes"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d468a93acd6','ch_99019e22283a','text','{"text": "2. ‘Poem in October’ by Dylan Thomas."}',40);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_da9dc0153193','bk_ncert_english','11-16-for-elkana','11.16 For Elkana',NULL,'public',56,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80212c0020a6','ch_da9dc0153193','text','{"text": "The warm April evening"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4efeaf06bd5e','ch_da9dc0153193','text','{"text": "tempts us to the breezes"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_847f89ee5372','ch_da9dc0153193','text','{"text": "sauntering across the lawn."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9d1195c1c07','ch_da9dc0153193','text','{"text": "We drag our chairs down"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73f1dd509da6','ch_da9dc0153193','text','{"text": "the stone steps and plant them there."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5450a9ecf0a6','ch_da9dc0153193','text','{"text": "Unevenly, to sit or rather sprawl"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23e3757ca4ed','ch_da9dc0153193','text','{"text": "in silence till the words begin to come."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e915413bc4c','ch_da9dc0153193','text','{"text": "My wife, as is her way,"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68055f9bf9c5','ch_da9dc0153193','text','{"text": "surveys the scene, comments"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d8aa57f2db6','ch_da9dc0153193','text','{"text": "on a broken window-pane."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4f218e4f642','ch_da9dc0153193','text','{"text": "Suggests a thing or two"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6f3e00787d1','ch_da9dc0153193','text','{"text": "that every husband in the neighbourhood"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73f80f5ab69a','ch_da9dc0153193','text','{"text": "knows exactly how to do"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8939be48068a','ch_da9dc0153193','text','{"text": "except of course the man she loves"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5c398ba6f5a','ch_da9dc0153193','text','{"text": "who happened to be me."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d060249d0346','ch_da9dc0153193','text','{"text": "Unwilling to dispute"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f5c4ca208ef','ch_da9dc0153193','text','{"text": "the obvious fact that she is always right,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c299265bbac8','ch_da9dc0153193','text','{"text": "I turn towards the more"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba16ebccf50b','ch_da9dc0153193','text','{"text": "attractive view that opens up"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36125c7df8c4','ch_da9dc0153193','text','{"text": "behind my eyes and shuts her out."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_455bfb4fd539','ch_da9dc0153193','text','{"text": "Her voice crawls up and down the lawn,"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b930fb327901','ch_da9dc0153193','text','{"text": "our son, who is seven,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fecc2d3a9b37','ch_da9dc0153193','text','{"text": "hears it—and it reminds him of something."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b96ffe200bb0','ch_da9dc0153193','text','{"text": "He stands before us,"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a89a4520583','ch_da9dc0153193','text','{"text": "his small legs well apart,"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9291cf82d8a','ch_da9dc0153193','text','{"text": "crescent-moon-like chin uplifted"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_717128262195','ch_da9dc0153193','text','{"text": "eyes hard and cold"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_322389e371d9','ch_da9dc0153193','text','{"text": "to speak his truth"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b2d8d1cb881','ch_da9dc0153193','text','{"text": "in masterly determination:"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf984b81a7e4','ch_da9dc0153193','text','{"text": "Mummy, I want my dinner, now."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a549a768a2c8','ch_da9dc0153193','text','{"text": "Wife and husband in unusual rapport"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79c7ae2001ce','ch_da9dc0153193','text','{"text": "state one unspoken thought:"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6e40eec1755','ch_da9dc0153193','text','{"text": "Children Must be Disciplined."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30f1bd338262','ch_da9dc0153193','text','{"text": "She looks at me. I look away."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_760457564041','ch_da9dc0153193','text','{"text": "The son is waiting. In another second"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b086d720738','ch_da9dc0153193','text','{"text": "he will repeat himself."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b69d2d2e65a','ch_da9dc0153193','text','{"text": "Wife wags a finger."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d056a0f178c8','ch_da9dc0153193','text','{"text": "Firmly delivers verdict: Wait."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a6ad901a5ed','ch_da9dc0153193','text','{"text": "In five minutes I’ll serve you dinner."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e4703c3915c','ch_da9dc0153193','text','{"text": "No, says the little one,"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc8908bd4a03','ch_da9dc0153193','text','{"text": "not in five minutes, now."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ecb1c155e71','ch_da9dc0153193','text','{"text": "I am hungry."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_388a8cf2819a','ch_da9dc0153193','text','{"text": "It occurs to me the boy is like his father."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cb07378c427','ch_da9dc0153193','text','{"text": "I love him as I love myself."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_542b140b0a8f','ch_da9dc0153193','text','{"text": "Wait, darling, wait,"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7c5057b9528','ch_da9dc0153193','text','{"text": "Mummy says, wait for five minutes"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_051fb23b38b5','ch_da9dc0153193','text','{"text": "But, I am hungry now,"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77de1bd9ac8e','ch_da9dc0153193','text','{"text": "declaims the little bastard, in five minutes"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c0d6ddf42c2','ch_da9dc0153193','text','{"text": "I won’t be hungry any more."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_468c8fae717a','ch_da9dc0153193','text','{"text": "This argument appeals to me."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_648581f8b02a','ch_da9dc0153193','text','{"text": "Such a logician deserves his dinner straightaway."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2bce191c715d','ch_da9dc0153193','text','{"text": "My wife’s delightful laughter"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19ecf2057365','ch_da9dc0153193','text','{"text": "holds the three of us together."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53b2e8ddcda9','ch_da9dc0153193','text','{"text": "We rise and go into the house."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_012fedea76bd','ch_da9dc0153193','list','{"ordered": false, "items": ["Nissim Ezekiel"]}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6d8180b126d','ch_da9dc0153193','heading','{"level": 2, "text": "About The Poet"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d0801007384','ch_da9dc0153193','text','{"text": "Nissim Ezekiel (1924–2004) was born in Mumbai. He is today perhaps the best known Indian poet to have written in English. He had his education at Wilson College, Bombay and later at Birbeck College, London. A professor of American Literature at Bombay University, Ezekiel has written several poems and some plays. A proficient critic, Ezekiel lectured at a number of universities in the U.S.A. and the U.K."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae40db09bf96','ch_da9dc0153193','heading','{"level": 2, "text": "Understanding The Poem"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40a3e7d540b0','ch_da9dc0153193','text','{"text": "1. Comment on the subtlety with which the poet captures the general pattern of communication within a family."}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_597bf12591e3','ch_da9dc0153193','text','{"text": "2. Poetic effect is achieved in the poem through understatement and asides. Discuss this with examples."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4401485eeb5','ch_da9dc0153193','text','{"text": "3. How is the idyllic juxtaposed with the pedestrian in the poem?"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51fe7f827eaf','ch_da9dc0153193','text','{"text": "4. Explain the undertones in the statement: ‘Wife and husband in unusual rapport State one unspoken thought’:"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5a2190bc0ae','ch_da9dc0153193','text','{"text": "5. Comment on the capitalisation of all the words in the line: ‘Children Must be Disciplined’."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab7216bb05b1','ch_da9dc0153193','text','{"text": "6. What makes the urgency of the child’s demand seem logical?"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd3284e606d5','ch_da9dc0153193','heading','{"level": 2, "text": "Try This Out"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9477003bb622','ch_da9dc0153193','text','{"text": "1. Paraphrase the poem and notice the change in effect. Comment on the deft touch with which the poet transforms ordinary events into evocative poetry."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26ebba1bb23c','ch_da9dc0153193','heading','{"level": 2, "text": "Suggested Reading"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e715fb38184d','ch_da9dc0153193','text','{"text": "The Night of the Scorpion and Other Poems by Nissim Ezekiel."}',68);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_748a2b3421f4','bk_ncert_english','11-17-the-limerick','11.17 The Limerick',NULL,'public',57,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d1898afc164','ch_748a2b3421f4','text','{"text": "The limerick is a small five line poem, expressing a single thought. It is usually funny with a punch or joke in the last line. In fact, the limerick is to poetry what slapstick is to comedy."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad1394d20689','ch_748a2b3421f4','text','{"text": "The rhyme scheme is ‘a a b b a’ : the first and second lines rhyme with the fifth, while the third and fourth lines rhyme with each other."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4832b2eae826','ch_748a2b3421f4','text','{"text": "One reason why the limerick is popular is that almost anyone can try his/her hand at it. May be you could too!"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a819dc33480','ch_748a2b3421f4','text','{"text": "A novice was driving a car"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9167f678f489','ch_748a2b3421f4','text','{"text": "When, down the road, his son said “Papa,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f77e10e6d266','ch_748a2b3421f4','text','{"text": "If you drive at this rate"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79a20fe99ca1','ch_748a2b3421f4','text','{"text": "We are bound to be late—"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89d277556b03','ch_748a2b3421f4','text','{"text": "Drive faster!” He did, and they are."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f8cab0bff6d','ch_748a2b3421f4','text','{"text": "***"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20c36e52e3c9','ch_748a2b3421f4','text','{"text": "Earth’s plan had a hopeful beginning but man spoiled its chances by sinning."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_403160e8bb24','ch_748a2b3421f4','text','{"text": "We hope that the story,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8065c39f017e','ch_748a2b3421f4','text','{"text": "Will end in Earth’s glory"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df236f1301d4','ch_748a2b3421f4','text','{"text": "But at present the other side’s winning!"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1a0e14a60396','ch_748a2b3421f4','text','{"text": "***"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff0f01fd82e4','ch_748a2b3421f4','text','{"text": "There was once a man from Peru"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3f9bc27c5c8','ch_748a2b3421f4','text','{"text": "Who dreamed he was eating his shoe"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_974e063ee750','ch_748a2b3421f4','text','{"text": "He woke up with a fright"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efde09822ec9','ch_748a2b3421f4','text','{"text": "In the middle of the night"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6355e28b8e4d','ch_748a2b3421f4','text','{"text": "And found that it was perfectly true!"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6a96b4db120','ch_748a2b3421f4','text','{"text": "There was a teacher named Ms Brass"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4539a90c321e','ch_748a2b3421f4','text','{"text": "Who was blessed with an unruly class"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5df854d3e051','ch_748a2b3421f4','text','{"text": "They slept and snored And completely ignored"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b1afc5d3a72','ch_748a2b3421f4','text','{"text": "Theorems like Pythagoras."}',23);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_015361eb11cb','bk_ncert_english','11-18-refugee-blues','11.18 Refugee Blues',NULL,'public',58,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9db33a01f28','ch_015361eb11cb','text','{"text": "Say this city has ten million souls,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a62ad184016b','ch_015361eb11cb','text','{"text": "Some are living in mansions, some are living in holes:"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_381bd1281356','ch_015361eb11cb','text','{"text": "Yet there’s no place for us, my dear, yet there’s no"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dce1540bc10','ch_015361eb11cb','text','{"text": "place for us."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad9ea0daa417','ch_015361eb11cb','text','{"text": "Once we had a country and we thought it fair,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6cb611dcaec','ch_015361eb11cb','text','{"text": "Look in the atlas and you’ll find it there:"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e650c7dc6172','ch_015361eb11cb','text','{"text": "We cannot go there now, my dear, we cannot go there"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d5085c12909','ch_015361eb11cb','text','{"text": "now."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77a1394e3073','ch_015361eb11cb','text','{"text": "In the village churchyard there grows an old yew,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26dc7c38d142','ch_015361eb11cb','text','{"text": "Every spring it blossoms anew:"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_580054528b0e','ch_015361eb11cb','text','{"text": "Old passports can’t do that, my dear, old passports"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_932a86a23cd6','ch_015361eb11cb','text','{"text": "can’t do that."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5a44929aa14','ch_015361eb11cb','text','{"text": "The consul banged the table and said:"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23d1ed821155','ch_015361eb11cb','text','{"text": "‘If you’ve got no passport you’re officially dead’;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbd8e5707750','ch_015361eb11cb','text','{"text": "But we are still alive, my dear, but we are still alive."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e918adc8630d','ch_015361eb11cb','text','{"text": "Went to a committee; they offered me a chair;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10b4e6917b61','ch_015361eb11cb','text','{"text": "Asked me politely to return next year;"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a6dc415deb1','ch_015361eb11cb','text','{"text": "But where shall we go today, my dear, but where shall"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f475f7565d7','ch_015361eb11cb','text','{"text": "we go today?"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0d5b14a437a','ch_015361eb11cb','text','{"text": "Came to a public meeting; the speaker got up and said:"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a50b1760cd8b','ch_015361eb11cb','text','{"text": "‘If we let them in, they will steal our daily bread’;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3a81c744969','ch_015361eb11cb','text','{"text": "He was talking of you and me, my dear, he was talking"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce553fd2247b','ch_015361eb11cb','text','{"text": "of you and me."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18fb5245f700','ch_015361eb11cb','text','{"text": "Thought I heard the thunder rumbling in the sky;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f741cc1fad6b','ch_015361eb11cb','text','{"text": "It was Hitler over Europe, saying: ‘they must die’;"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ebef483d6e0','ch_015361eb11cb','text','{"text": "We were in his mind, my dear, we were in his mind."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef6f0cc05870','ch_015361eb11cb','text','{"text": "Saw a poodle in a jacket fastened with a pin;"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f85fa949adc3','ch_015361eb11cb','text','{"text": "Saw a door opened and a cat let in:"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a30583311c33','ch_015361eb11cb','text','{"text": "But they weren’t German Jews, my dear, but they"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12b10671125c','ch_015361eb11cb','text','{"text": "weren’t German Jews."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0853f84d72aa','ch_015361eb11cb','text','{"text": "Went down the harbour and stood upon the quay,"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b681e6505c96','ch_015361eb11cb','text','{"text": "Saw the fish swimming as if they were free:"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3a5930d8058','ch_015361eb11cb','text','{"text": "Only ten feet away, my dear, only ten feet away."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0316f31422e7','ch_015361eb11cb','text','{"text": "Walked through a wood, saw the birds in the trees;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f72e6881d055','ch_015361eb11cb','text','{"text": "They had no politicians and sang at their ease:"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4783bc96e80','ch_015361eb11cb','text','{"text": "They weren’t the human race, my dear, they weren’t"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d801de9fae57','ch_015361eb11cb','text','{"text": "the human race."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9eab9eafb39c','ch_015361eb11cb','text','{"text": "Dreamed I saw a building with a thousand floors,"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae3ae0809781','ch_015361eb11cb','text','{"text": "A thousand windows and a thousand doors;"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1955f0d9dee','ch_015361eb11cb','text','{"text": "Not one of them was ours, my dear, not one of them"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3563ab3f7b6','ch_015361eb11cb','text','{"text": "was ours."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c905507dcabd','ch_015361eb11cb','text','{"text": "Went down to the station to catch the express,"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df271b71fae4','ch_015361eb11cb','text','{"text": "Asked for two tickets to Happiness;"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2df1678f93bc','ch_015361eb11cb','text','{"text": "But every coach was full, my dear, every coach was"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3359d0ff91b','ch_015361eb11cb','text','{"text": "full."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98f80a40c496','ch_015361eb11cb','text','{"text": "Stood on a great plain in the falling snow;"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7905a9b3e6a8','ch_015361eb11cb','text','{"text": "Ten thousand soldiers marched to and fro:"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6934aaad1b5c','ch_015361eb11cb','text','{"text": "Looking for you and me, my dear, looking for you and"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f742784c7985','ch_015361eb11cb','text','{"text": "me."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_061c12c194de','ch_015361eb11cb','list','{"ordered": false, "items": ["Wystan Hugh Auden"]}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_613cd1d5ead8','ch_015361eb11cb','heading','{"level": 2, "text": "About The Poet"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fd4f607c659','ch_015361eb11cb','text','{"text": "Wystan Hugh Auden (1907–1973) was a student and later a Professor of Poetry at Oxford University. One of the most important poets of the century, he has published several collections of poems noted for their irony, compassion and wit."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0f39e0b8f7f','ch_015361eb11cb','text','{"text": "Although a modern poem, ‘Refugee Blues’ uses the ballad form of narration."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e62630414acd','ch_015361eb11cb','heading','{"level": 2, "text": "Understanding The Poem"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c51abfcdd517','ch_015361eb11cb','text','{"text": "1. The title, ‘Refugee Blues’ encapsulates the theme of the poem. Comment."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8324eb420257','ch_015361eb11cb','text','{"text": "2. What is the poetic technique used by the poet to convey the plaintive theme of the poem?"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8fece20f638','ch_015361eb11cb','text','{"text": "3. What do the references to the birds and animals made in the poem suggest?"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_423383f1a9e3','ch_015361eb11cb','text','{"text": "4. How does the poet juxtapose the human condition with the behaviour of the political class?"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00992999d3f6','ch_015361eb11cb','text','{"text": "5. How is the essence of the poem captured in the lines ‘two tickets to Happiness’?"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14bedc059037','ch_015361eb11cb','heading','{"level": 2, "text": "Try This Out"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc011b424167','ch_015361eb11cb','text','{"text": "1. Here is a list of devices used in poetry. Elaborate on their use in this poem"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41cfb3b112ec','ch_015361eb11cb','text','{"text": "Refrain:"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ea7f9d0334b','ch_015361eb11cb','text','{"text": "Pathos:"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61966ccc30d5','ch_015361eb11cb','text','{"text": "Irony:"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03e593c23231','ch_015361eb11cb','text','{"text": "Sarcasm:"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3bf9044c2056','ch_015361eb11cb','text','{"text": "2. What does the colour ‘blue’ suggest in the poem? Make a list of other colours and the emotions and moods they carry."}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5b235744023','ch_015361eb11cb','heading','{"level": 2, "text": "Suggested Reading"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1cd35a65c4cf','ch_015361eb11cb','text','{"text": "1. ‘Taller Today we Remember’ by W.H. Auden"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c677e83e9b24','ch_015361eb11cb','text','{"text": "2. ‘Our Hunting Fathers’ by W.H. Auden."}',69);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b2570efdbb19','bk_ncert_english','11-19-felling-of-the-banyan-tree','11.19 Felling of the Banyan Tree',NULL,'public',59,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77cae8002c55','ch_b2570efdbb19','text','{"text": "My father told the tenants to leave"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37adc2a90741','ch_b2570efdbb19','text','{"text": "Who lived on the houses surrounding our house on the hill"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1020ce54b68d','ch_b2570efdbb19','text','{"text": "One by one the structures were demolished"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efe5fe7bf389','ch_b2570efdbb19','text','{"text": "Only our own house remained and the trees"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f780a8dbe4f1','ch_b2570efdbb19','text','{"text": "Trees are sacred my grandmother used to say"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8bc78d196ce','ch_b2570efdbb19','text','{"text": "Felling them is a crime but he massacred them all"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd9a1fe7a312','ch_b2570efdbb19','text','{"text": "The sheoga, the oudumber, the neem were all cut down"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5eb2961b3735','ch_b2570efdbb19','text','{"text": "But the huge banyan tree stood like a problem"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abf091d3f881','ch_b2570efdbb19','text','{"text": "Whose roots lay deeper than all our lives"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f2b2c0ac2fa','ch_b2570efdbb19','text','{"text": "My father ordered it to be removed"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96a50030ec30','ch_b2570efdbb19','text','{"text": "The banyan tree was three times as tall as our house"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b0e9b497701','ch_b2570efdbb19','text','{"text": "Its trunk had a circumference of fifty feet"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25b3d3a46ff8','ch_b2570efdbb19','text','{"text": "Its scraggy aerial roots fell to the ground"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7179be722b76','ch_b2570efdbb19','text','{"text": "From thirty feet or more so first they cut the branches"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_765132595b85','ch_b2570efdbb19','text','{"text": "Sawing them off for seven days and the heap was huge"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf6aed406103','ch_b2570efdbb19','text','{"text": "Insects and birds began to leave the tree"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_098349d9619f','ch_b2570efdbb19','text','{"text": "And then they came to its massive trunk"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6eccc8459b81','ch_b2570efdbb19','text','{"text": "Fifty men with axes chopped and chopped"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62a0aee77112','ch_b2570efdbb19','text','{"text": "The great tree revealed its rings of two hundred years"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59242a32d293','ch_b2570efdbb19','text','{"text": "We watched in terror and fascination this slaughter"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_069daa81b3f3','ch_b2570efdbb19','text','{"text": "As a raw mythology revealed to us its age"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42de39bd7e97','ch_b2570efdbb19','text','{"text": "Soon afterwards we left Baroda for Bombay"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_720ce433286b','ch_b2570efdbb19','text','{"text": "Where there are no trees except the one"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_781488785482','ch_b2570efdbb19','text','{"text": "Which grows and seethes in one’s dreams, its aerial roots"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_73224d0d19ab','ch_b2570efdbb19','text','{"text": "Looking for the ground to strike."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5825e51d1834','ch_b2570efdbb19','list','{"ordered": false, "items": ["Dilip Chitre"]}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_feef8691df06','ch_b2570efdbb19','heading','{"level": 2, "text": "About The Poet"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c337dd376ef','ch_b2570efdbb19','text','{"text": "Dilip Chitre (1938-2009) was born in Baroda. He writes poetry both in Marathi and English. Travelling in a Cage, from which the poem selected here has been taken, was published in 1980. Apart from poetry, Chitre has also written short stories and critical essays. An"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d83e1089b80e','ch_b2570efdbb19','text','{"text": "Anthology of Marathi Poetry 1945–1965 is one of his most important works of translation. He sees poetry as an expression of the spirit. He lives and works in Mumbai."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50040252896a','ch_b2570efdbb19','text','{"text": "F Guess the meaning of the word ‘scraggy’ from the context."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54b402e0ffe1','ch_b2570efdbb19','heading','{"level": 2, "text": "Understanding The Poem"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b58a5c9fa2c','ch_b2570efdbb19','text','{"text": "1. Identify the lines that reveal the critical tone of the poet towards the felling of the tree."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e764108fa338','ch_b2570efdbb19','text','{"text": "2. Identify the words that help you understand the nature of the poet’s father."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_248f1c16871f','ch_b2570efdbb19','text','{"text": "3. ‘Trees are sacred my grandmother used to say’— what does the poet imply by this line?"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f4a0c80d9a2','ch_b2570efdbb19','text','{"text": "4. ‘No trees except the one which grows and seethes in one’s dreams’— why is the phrase ‘grows and seethes’ used?"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06dadc1dd10c','ch_b2570efdbb19','text','{"text": "5. How does the banyan tree stand out as different from other trees? What details of the tree does the poet highlight in the poem?"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_847cbdfdcbb9','ch_b2570efdbb19','text','{"text": "6. What does the reference to raw mythology imply?"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2eebf390ae47','ch_b2570efdbb19','text','{"text": "7. ‘Whose roots lay deeper than our lives’— what aspect of human behaviour does this line reflect?"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0abd986ce074','ch_b2570efdbb19','text','{"text": "8. Comment on the contemporary concern that the poem echoes."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6055064d5a0','ch_b2570efdbb19','heading','{"level": 2, "text": "Try This Out"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38b6f67f415e','ch_b2570efdbb19','text','{"text": "1. Most of us have had this experience of seeing trees in our neighbourhood being mercilessly cut down in order to build a house or a public building or to widen a road. Describe any such experience you have had of the felling of a tree you were attached to, with reasons for your special attachment to the tree."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27e0976bda54','ch_b2570efdbb19','text','{"text": "2. Find out the equivalents for sheoga, oudumber and neem in your language and English and the equivalent of banyan in your language."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_481ecd437394','ch_b2570efdbb19','text','{"text": "3. The adjective ‘scraggy’ is used to describe ‘roots’ in the poem. Find out two other items which could be described as ‘scraggy’: scraggy……………."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af28aed9095d','ch_b2570efdbb19','text','{"text": "4. Use the following adjectives to describe suitable items"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_830c244ebecb','ch_b2570efdbb19','heading','{"level": 2, "text": "Suggested Reading"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_234114d60e70','ch_b2570efdbb19','text','{"text": "1.\t‘Death of Grandmother’ by Dilip Chitre."}',46);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_e0f7eb651473','bk_ncert_english','11-20-ode-to-a-nightingale','11.20 Ode to a Nightingale',NULL,'public',60,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac92b28ab17c','ch_e0f7eb651473','text','{"text": "My heart aches, and a drowsy numbness"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8068041c275','ch_e0f7eb651473','text','{"text": "pains"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7d51d4f74de','ch_e0f7eb651473','text','{"text": "My sense, as though of hemlock I had"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94d902237949','ch_e0f7eb651473','text','{"text": "drunk,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75daa60ada7b','ch_e0f7eb651473','text','{"text": "Or emptied some dull opiate to the drains"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a729bae79dc','ch_e0f7eb651473','text','{"text": "One minute past, and Lethe-wards had"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27fbeeed5e46','ch_e0f7eb651473','text','{"text": "sunk:"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4abc2faac34','ch_e0f7eb651473','text','{"text": "’Tis not through envy of thy happy lot,"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d47f8ad0f01a','ch_e0f7eb651473','text','{"text": "But being too happy in thine happiness,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14633ccf9392','ch_e0f7eb651473','text','{"text": "That thou, light-winged Dryad of the trees,"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39812b53a886','ch_e0f7eb651473','text','{"text": "In some melodious plot"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be5ec6365035','ch_e0f7eb651473','text','{"text": "Of beechen green, and shadows"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9b461266d7c1','ch_e0f7eb651473','text','{"text": "numberless,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7706416d8ab2','ch_e0f7eb651473','text','{"text": "Singest of summer in full-throated ease."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95f9652696c1','ch_e0f7eb651473','text','{"text": "***"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b41ae2a9c875','ch_e0f7eb651473','text','{"text": "O, for a draught of vintage! that hath been"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bd2fed8e243a','ch_e0f7eb651473','text','{"text": "Cool’d a long age in the deep-delved earth,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c21ef258621','ch_e0f7eb651473','text','{"text": "Tasting of Flora and the country green,"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bbdba78e0e0','ch_e0f7eb651473','text','{"text": "Dance, and Provencal song, and sunburnt"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7106e57df55','ch_e0f7eb651473','text','{"text": "mirth!"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5db9c85c83b2','ch_e0f7eb651473','text','{"text": "O, for a beaker full of the warm South,"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02f7f6730fc1','ch_e0f7eb651473','text','{"text": "Full of the true, the blushful Hippocrene,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f7742cb3beb','ch_e0f7eb651473','text','{"text": "With beaded bubbles winking at the brim,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0a745f12ceb','ch_e0f7eb651473','text','{"text": "And purple-stained mouth;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74ae441e0466','ch_e0f7eb651473','text','{"text": "That I might drink, and leave the world"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e345aa22285e','ch_e0f7eb651473','text','{"text": "unseen,"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5aa5f21c9e59','ch_e0f7eb651473','text','{"text": "And with thee fade away into the forest"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a6df66fcccd','ch_e0f7eb651473','text','{"text": "dim."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c031842895a','ch_e0f7eb651473','text','{"text": "***"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5717639795e7','ch_e0f7eb651473','text','{"text": "Fade far away, dissolve, and quite forget"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_229d604fcd11','ch_e0f7eb651473','text','{"text": "What thou among the leaves hast never"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a99c9294cd72','ch_e0f7eb651473','text','{"text": "known"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_336365590057','ch_e0f7eb651473','text','{"text": "The weariness, the fever, and the fret"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17814d6667a2','ch_e0f7eb651473','text','{"text": "Here, where men sit and hear each other"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c934d17eb7d','ch_e0f7eb651473','text','{"text": "groan;"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6520604ec99a','ch_e0f7eb651473','text','{"text": "Where palsy shakes a few, sad, last gray"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3927afd3912','ch_e0f7eb651473','text','{"text": "hairs,"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b97f773e4d61','ch_e0f7eb651473','text','{"text": "Where youth grows pale, and spectre-thin,"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ae74938df5c3','ch_e0f7eb651473','text','{"text": "and dies;"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea4d9a35165a','ch_e0f7eb651473','text','{"text": "Where but to think is to be full of sorrow"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2df3e02827cb','ch_e0f7eb651473','text','{"text": "And leaden-eyed despairs,"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d57a5c3676ba','ch_e0f7eb651473','text','{"text": "Where Beauty cannot keep her lustrous"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_56d7c6c3ba07','ch_e0f7eb651473','text','{"text": "eyes,"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60ed2bee8243','ch_e0f7eb651473','text','{"text": "Or new Love pine at them beyond tomorrow."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa9ef95ab49b','ch_e0f7eb651473','text','{"text": "***"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d4c9ce9c829','ch_e0f7eb651473','text','{"text": "Thou wast not born for death, immortal"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c104d1ec84b3','ch_e0f7eb651473','text','{"text": "Bird!"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccf438131b4e','ch_e0f7eb651473','text','{"text": "No hungry generations tread thee down;"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6092778f9656','ch_e0f7eb651473','text','{"text": "The voice I hear this passing night was"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ac8100c1061','ch_e0f7eb651473','text','{"text": "heard"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2972e9583951','ch_e0f7eb651473','text','{"text": "In ancient days by emperor and clown:"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00d364bdb403','ch_e0f7eb651473','text','{"text": "Perhaps the self-same song that found a"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_372e8ee0f85a','ch_e0f7eb651473','text','{"text": "path"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abd9cf6086a2','ch_e0f7eb651473','text','{"text": "Through the sad heart of Ruth, when, sick"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e1cac187729','ch_e0f7eb651473','text','{"text": "for home,"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e19f7e515b8','ch_e0f7eb651473','text','{"text": "She stood in tears amid the alien corn;"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bca8bd6934dc','ch_e0f7eb651473','text','{"text": "The same that oft-times hath"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c9b37a967e3','ch_e0f7eb651473','text','{"text": "Charm’d magic casements, opening on the"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e5e479a1aef','ch_e0f7eb651473','text','{"text": "foam"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_328bd63fc527','ch_e0f7eb651473','text','{"text": "Of perilous seas, in faery lands forlorn."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53a2cc2b1284','ch_e0f7eb651473','text','{"text": "***"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e269b347c062','ch_e0f7eb651473','text','{"text": "Forlorn! the very word is like a bell"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5d89538b731','ch_e0f7eb651473','text','{"text": "To toll me back from thee to my sole self!"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27fc6a62034f','ch_e0f7eb651473','text','{"text": "Adieu! the fancy cannot cheat so well"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2903ee999571','ch_e0f7eb651473','text','{"text": "As she is fam’d to do, deceiving elf."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_421d299dcc73','ch_e0f7eb651473','text','{"text": "Adieu! adieu! thy plaintive anthem fades"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f32bbec17ed6','ch_e0f7eb651473','text','{"text": "Past the near meadows, over the still"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_887be6fcd045','ch_e0f7eb651473','text','{"text": "stream,"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35211ccb8bd2','ch_e0f7eb651473','text','{"text": "Up the hill-side; and now ’tis buried deep"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7aa8dfaab896','ch_e0f7eb651473','text','{"text": "In the next valley-glades:"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85944e6ced85','ch_e0f7eb651473','text','{"text": "Was it a vision, or a waking dream?"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e37cf80bc3d','ch_e0f7eb651473','text','{"text": "Fled is that music:—Do I wake or sleep?"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1aa8ed8f03a6','ch_e0f7eb651473','list','{"ordered": false, "items": ["John Keats"]}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_115cd3e204c6','ch_e0f7eb651473','heading','{"level": 2, "text": "About The Poet"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca5eba811c3f','ch_e0f7eb651473','text','{"text": "John Keats (1795–1821) was one of the greatest of the younger generation of ‘English Romantic’ poets. He started his career as an apprentice to a surgeon but"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0243dee94c98','ch_e0f7eb651473','text','{"text": "Ruth: a woman in the Bible who left her own people to live with her mother-inlaw, Naomi. After the death of her husband, marries Boaz and is the ancestor of King David."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_405ec6b59074','ch_e0f7eb651473','text','{"text": "soon gave it up for poetry. His poetic career lasted for only four years but, during this short span, he evolved from an ordinary poet to an exceptionally mature poetic force. His poetry celebrates beauty, which he considered the ultimate truth. It is portrayed in extremely sensuous images that have been created through beautiful verbal pictures. The image of the nightingale’s bower in the poem is an apt illustration of the poet’s craft in this respect."}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50abfefe0c2c','ch_e0f7eb651473','text','{"text": "? Look for these words and guess their meanings from the context"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b35e28a92dbd','ch_e0f7eb651473','text','{"text": "1. How does the nightingale’s song plunge the poet into a state of ecstasy?"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35fa60b65a2d','ch_e0f7eb651473','text','{"text": "2. What are the unpleasant aspects of the human condition that the poet wants to escape from?"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0af21c776a07','ch_e0f7eb651473','text','{"text": "3. What quality of ‘beauty’ and ‘love’ does the poem highlight?"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_478f9a76973c','ch_e0f7eb651473','text','{"text": "4. How does the poet bring out the immortality of the bird?"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44f85dd1d595','ch_e0f7eb651473','text','{"text": "5. How is the poet tossed back from ecstasy into despair?"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1a55c6872be','ch_e0f7eb651473','text','{"text": "6. How does the poem bring out the elusive nature of happiness in human existence?"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_276877138801','ch_e0f7eb651473','heading','{"level": 2, "text": "Try This Out"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_704b11ddeda5','ch_e0f7eb651473','text','{"text": "1. The poet has juxtaposed sets of opposites like  numbness  pains, waking dream. How does this contribute to the poetic effect? What is this figure of speech called? List other such pairs from poems that you have read."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bfc08d41c6d','ch_e0f7eb651473','text','{"text": "2. The poet has evoked the image of wine—why has this image been chosen?"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_358efdc0722a','ch_e0f7eb651473','text','{"text": "3. The senses of sound, sight and taste are evoked in the poem."}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_428cd3aea9ef','ch_e0f7eb651473','text','{"text": "Locate instances of these."}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c41cd9c8a6dd','ch_e0f7eb651473','text','{"text": "Ode to a Nightingale"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_860f30436501','ch_e0f7eb651473','text','{"text": "4. The poet addresses the nightingale and talks to the bird throughout the poem. What is this kind of poem called?"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02acbed6c7c5','ch_e0f7eb651473','text','{"text": "5. Make a list of all the adjectives in the poem along with the nouns they describe. List the phrases that impressed you most in the poem."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb48b0face1f','ch_e0f7eb651473','text','{"text": "6. Find out the other odes written by Keats and read them."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b67e8e4aabd','ch_e0f7eb651473','text','{"text": "7. Find out the odes written by Shelley and read them."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f006a82af3b','ch_e0f7eb651473','heading','{"level": 2, "text": "Suggested Reading"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_977985b9f363','ch_e0f7eb651473','text','{"text": "1. The complete version of ‘Ode to a Nightingale’ by John Keats"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a179e86ba7e3','ch_e0f7eb651473','text','{"text": "2. ‘Ode to the West Wind’ by P.B. Shelley."}',97);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_7d8124137a1d','bk_ncert_english','11-21-ajamil-and-the-tigers','11.21 Ajamil and the Tigers',NULL,'public',61,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_926e1a26c2cf','ch_7d8124137a1d','text','{"text": "The tiger people went to their king"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3ad7f3f7966','ch_7d8124137a1d','text','{"text": "and said, ‘We’re starving."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e2389aaf157','ch_7d8124137a1d','text','{"text": "We’ve had nothing to eat,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ef1a31a525a','ch_7d8124137a1d','text','{"text": "not a bite,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91a3f59bc125','ch_7d8124137a1d','text','{"text": "for 15 days and 16 nights."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e769172dfdb','ch_7d8124137a1d','text','{"text": "Ajamil has got"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bccae487a942','ch_7d8124137a1d','text','{"text": "a new sheep dog."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_febb7a395143','ch_7d8124137a1d','text','{"text": "He cramps our style"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d1ea55a8c943','ch_7d8124137a1d','text','{"text": "and won’t let us get within a mile"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5cb2a1bf523b','ch_7d8124137a1d','text','{"text": "of meat.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31687de2040e','ch_7d8124137a1d','text','{"text": "‘That’s shocking,’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a40ca49a8b0a','ch_7d8124137a1d','text','{"text": "said the tiger king."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_291291ec9335','ch_7d8124137a1d','text','{"text": "‘Why didn’t you come to see me before?"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2dfb96bd966','ch_7d8124137a1d','text','{"text": "Make preparations for a banquet."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d810bdc95f26','ch_7d8124137a1d','text','{"text": "I’m gonna teach that sheep dog a lesson he’ll never"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_095781d369f3','ch_7d8124137a1d','text','{"text": "forget.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6bff2919a0f','ch_7d8124137a1d','text','{"text": "‘Hear hear,’ said the tigers."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_132bb7343688','ch_7d8124137a1d','text','{"text": "‘Careful,’ said the queen."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7edd21be4b5d','ch_7d8124137a1d','text','{"text": "But he was already gone."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de5c07745f55','ch_7d8124137a1d','text','{"text": "Alone"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f5e3ed291ae','ch_7d8124137a1d','text','{"text": "into the darkness before the dawn."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5077f42da322','ch_7d8124137a1d','text','{"text": "In an hour he was back,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fb6f8a4126c','ch_7d8124137a1d','text','{"text": "the good king."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d42dd57adc9d','ch_7d8124137a1d','text','{"text": "A black patch on his eye."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec03c6c21a88','ch_7d8124137a1d','text','{"text": "His tail in a sling."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3e8a3845495','ch_7d8124137a1d','text','{"text": "And said, ‘I’ve got it all planned"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9a696e4db66','ch_7d8124137a1d','text','{"text": "now that I know the lie of the land."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_173e09923dfe','ch_7d8124137a1d','text','{"text": "All of us will have to try."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1d36b45fcc9c','ch_7d8124137a1d','text','{"text": "We’ll outnumber the son of a bitch."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f88ffb23ef4','ch_7d8124137a1d','text','{"text": "And this time there will be no hitch."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96838ee378a6','ch_7d8124137a1d','text','{"text": "Because this time I shall be leading the attack.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb8a41f3e162','ch_7d8124137a1d','text','{"text": "Quick as lightning"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1828f2cf55a','ch_7d8124137a1d','text','{"text": "the sheep dog was."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49070b17bc12','ch_7d8124137a1d','text','{"text": "He took them all in as prisoners of war,"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d081d4fbb92','ch_7d8124137a1d','text','{"text": "the 50 tigers and the tiger king,"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5058ebad6cbb','ch_7d8124137a1d','text','{"text": "before they could get their paws"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d607453cb07','ch_7d8124137a1d','text','{"text": "on a single sheep."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27694a317c64','ch_7d8124137a1d','text','{"text": "They never had a chance."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_858db3a44754','ch_7d8124137a1d','text','{"text": "The dog was in 51 places all at once."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1ad4f0137b2','ch_7d8124137a1d','text','{"text": "He strung them all out in a daisy chain"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27dbac0d6d6d','ch_7d8124137a1d','text','{"text": "and flung them in front of his boss in one big heap."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_883dfedda0e6','ch_7d8124137a1d','text','{"text": "‘Nice dog you got there, Ajamil,’"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a87690d52caa','ch_7d8124137a1d','text','{"text": "said the tiger king."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_048cbd48cf37','ch_7d8124137a1d','text','{"text": "Looking a little ill"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_220b9927480c','ch_7d8124137a1d','text','{"text": "and spiting out a tooth."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8dca3525b47','ch_7d8124137a1d','text','{"text": "‘But there’s been a bit of a misunderstanding."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c225c35b23f1','ch_7d8124137a1d','text','{"text": "We could’ve wiped out your herd in one clean sweep."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55e2c835d7aa','ch_7d8124137a1d','text','{"text": "But we were not trying to creep up on your sheep."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5e37affc8bb','ch_7d8124137a1d','text','{"text": "We feel that means are more important than ends."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f93db6ce028','ch_7d8124137a1d','text','{"text": "We were coming to see you as friends."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99188943266c','ch_7d8124137a1d','text','{"text": "And that’s the truth.’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e08192af9dcc','ch_7d8124137a1d','text','{"text": "The sheep dog was the type"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f0172d95f29','ch_7d8124137a1d','text','{"text": "who had never told a lie in his life"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_369889865c2e','ch_7d8124137a1d','text','{"text": "He was built along simpler lines"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25db5951dab8','ch_7d8124137a1d','text','{"text": "and he was simply disgusted."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6af23008172e','ch_7d8124137a1d','text','{"text": "He kept on making frantic signs."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58ac3e4bff48','ch_7d8124137a1d','text','{"text": "But Ajamil, the good shepherd"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1c2d565096e','ch_7d8124137a1d','text','{"text": "refused to meet his eyes"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0d1aa1ed8f3','ch_7d8124137a1d','text','{"text": "and pretended to believe every single word"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec43dfe06c8c','ch_7d8124137a1d','text','{"text": "of what the tiger king said."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e874c99d86e0','ch_7d8124137a1d','text','{"text": "And seemed to be taken in by all the lies."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c64e595632d','ch_7d8124137a1d','text','{"text": "Ajamil cut them loose"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d19369c6cd54','ch_7d8124137a1d','text','{"text": "and asked them all to stay for dinner."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbdbaa793b93','ch_7d8124137a1d','text','{"text": "It was an offer the tigers couldn’t refuse."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8316b3d8433a','ch_7d8124137a1d','text','{"text": "And after the lamb chops and the roast,"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05e7e3358c88','ch_7d8124137a1d','text','{"text": "when Ajamil proposed"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eaefa07a160a','ch_7d8124137a1d','text','{"text": "they sign a long term friendship treaty,"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d9e2e1ea778','ch_7d8124137a1d','text','{"text": "all the tigers roared."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_597bbaf3f9d2','ch_7d8124137a1d','text','{"text": "‘We couldn’t agree with you more.’"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_608af97a5682','ch_7d8124137a1d','text','{"text": "And swore they would be good friends all their lives"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c279bf60d182','ch_7d8124137a1d','text','{"text": "as they put down the forks and the knives."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7daa261ec5b','ch_7d8124137a1d','text','{"text": "Ajamil signed a pact"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_819962c6cb4f','ch_7d8124137a1d','text','{"text": "with the tiger people and sent them back."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f916f976e5e','ch_7d8124137a1d','text','{"text": "Laden with gifts of sheep, leather jackets and balls of"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a72f54e05d3','ch_7d8124137a1d','text','{"text": "wool."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7919a8108bc','ch_7d8124137a1d','text','{"text": "Ajamil wasn’t a fool."}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_85b6b8bc0bc7','ch_7d8124137a1d','text','{"text": "Like all good shepherds he knew"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_804b5bfcb4f9','ch_7d8124137a1d','text','{"text": "that even tigers have got to eat some time."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09c5619e8ac7','ch_7d8124137a1d','text','{"text": "A good shepherd sees to it they do."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6945cd17b8c4','ch_7d8124137a1d','text','{"text": "He is free to play a flute all day"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da057c50b8ed','ch_7d8124137a1d','text','{"text": "as well fed tigers and fat sheep drink from the same"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abebf8f7f047','ch_7d8124137a1d','text','{"text": "pond"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8816eb041f95','ch_7d8124137a1d','text','{"text": "with a full stomach for a common bond."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da61a19ef71e','ch_7d8124137a1d','list','{"ordered": false, "items": ["Arun Kolatkar"]}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4f5aa2b1de5','ch_7d8124137a1d','heading','{"level": 2, "text": "About The Poet"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96a3ef9d95f4','ch_7d8124137a1d','text','{"text": "Arun Kolatkar (1932-2004) is a contemporary Indian poet. He was educated in Pune and earned a diploma in painting from the J.J. School of arts, Mumbai. He writes both in English and Marathi and has authored two books. The present poem is an excerpt from Jejuri— a long poem in thirty-one sections. A German translation of Jejuri by Gievanen Bandin was published in 1984."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49cd1adac6ad','ch_7d8124137a1d','heading','{"level": 2, "text": "Understanding The Poem"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9a304362918','ch_7d8124137a1d','text','{"text": "1. The poem has a literal level and a figurative level. Why has the poet chosen ‘tigers’ and ‘sheep’ to convey his message?"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a70d736f4ce','ch_7d8124137a1d','text','{"text": "2. What facet of political life does the behaviour of Ajamil illustrate?"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6217e176095f','ch_7d8124137a1d','text','{"text": "3. Why have the words, ‘pretended’ and ‘seemed’ been used in the lines:"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e324b0b35188','ch_7d8124137a1d','text','{"text": "...pretended to believe every single word of what the tiger king said."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e55426bac6c','ch_7d8124137a1d','text','{"text": "Ajamil and the Tigers"}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84b15caf7c1a','ch_7d8124137a1d','text','{"text": "And seemed to be taken in by all the lies."}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c4c07ea68e8','ch_7d8124137a1d','text','{"text": "How does the sense of these lines connect with the line ‘Ajamil wasn’t a fool’?"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e891b98cfc68','ch_7d8124137a1d','text','{"text": "4. Why did Ajamil refuse to meet the sheepdog’s eyes?"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_456b59336f2a','ch_7d8124137a1d','text','{"text": "5. ‘He is free to play a flute all day as well fed tigers and fat sheep drink from the same pond with a full stomach for a common bond.’"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a64e6c8b3464','ch_7d8124137a1d','text','{"text": "What do the phrases ‘play the flute all day’ and ‘a common bond’ refer to?"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5b49728a521','ch_7d8124137a1d','text','{"text": "6. The poem is a satire against the present political class. How effectively does it convey the anger and anguish of the common man trapped in the system?"}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa45d8b1fed3','ch_7d8124137a1d','heading','{"level": 2, "text": "Try This Out"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78654bce15b2','ch_7d8124137a1d','text','{"text": "Find out the difference between these literary forms (a) fable  (b) allegory (c) satire."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4e7436def1b','ch_7d8124137a1d','heading','{"level": 2, "text": "Suggested Reading"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_842888d3339a','ch_7d8124137a1d','text','{"text": "1.\tJejuri by Arun Kolatkar."}',102);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_acc97b350bf9','bk_ncert_english','essays','ESSAYS',NULL,'public',62,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f601943e785c','ch_acc97b350bf9','heading','{"level": 2, "text": "Introduction"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42be538f6a8a','ch_acc97b350bf9','text','{"text": "An essay is a short composition in prose that undertakes to discuss a matter, express a point of view, or persuade us to accept an idea on any subject. It is addressed to a general rather than a specialised audience; as a consequence, the essay discusses its subject in a nontechnical fashion and often with a liberal use of anecdote, illustration and humour."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9fabc765172','ch_acc97b350bf9','text','{"text": "A useful distinction is that between the formal and informal essay. The formal essay is relatively impersonal, logically organised and filled with serious purpose. The informal essay is personal, written in a relaxed, often whimsical fashion, and tends to deal with everyday things. Essays have been written since ancient times. The French writer, Montaigne, wrote short literary pieces which he called Essaies, meaning ‘attempts’. Francis Bacon inaugurated the English use of the term in his own essays. The founding of literary periodicals and magazines gave great impetus to the writing of essays (earlier essays were published in books)."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a9764ba9b21','ch_acc97b350bf9','text','{"text": "The essays in this unit provide a wide thematic range. My Watch is a humorous re-look at an instrument that most of us take for granted. My Three Passions focuses on the eternal concepts of love and pity. Tribal Verse makes one sensitively aware of the rich oral literatures of India. Bridges, an autobiographical excerpt, gives us a glimpse into the life of a kathak dancer and choreographer while Patterns of Creativity throws light on the creativity of poetry and creativity of science."}',4);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b8484109d0b5','bk_ncert_english','11-22-my-watch','11.22 My Watch',NULL,'public',63,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c44aec42117','ch_b8484109d0b5','heading','{"level": 2, "text": "I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4884bbbef9b','ch_b8484109d0b5','text','{"text": "My beautiful new watch had run eighteen months without losing or gaining, and without breaking any part of its machinery or stopping."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ed73cd7a23b','ch_b8484109d0b5','text','{"text": "I had come to believe it infallible in its judgments about the time of day, and to consider its constitution and its anatomy imperishable. But, at last, one night, I let it run down. I grieved about it as if it were a recognised messenger and forerunner of calamity. But by and by I cheered up, set the watch by guess, and commanded my bodings and superstitions to depart."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dc343d938c0','ch_b8484109d0b5','text','{"text": "Next day I stepped into the chief jeweller’s to set it by the exact time, and the head of the establishment took it out of my hand and proceeded to set it for me. Then he said, ‘she is four minutes slow— regulator wants pushing up’. I tried to stop him—tried to make him understand that the watch kept perfect time."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20cfd5bfa5ef','ch_b8484109d0b5','text','{"text": "But no; all this human cabbage could see was that the watch was four minutes slow and the regulator must be pushed up a little; and so, while I danced around him in anguish, and implored him to let the watch alone, he calmly and cruelly did the shameful deed. My watch began to gain. It gained faster and faster day by day. Within a week it sickened to a raging fever and its pulse went up to a hundred and fifty in the shade."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8665e605ae24','ch_b8484109d0b5','text','{"text": "At the end of two months it had left all the timepieces of the town far in the rear and was a fraction over thirteen days ahead of the almanac. It was away into November enjoying the snow, while the October leaves were still turning. It hurried up house rent, bills payable and such things in such a ruinous way that I could not abide it. I took it to the watchmaker to be regulated. He asked me if I had ever had it repaired. I said no, it had never needed any repairing."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1423710707a2','ch_b8484109d0b5','text','{"text": "He looked a look of vicious happiness and eagerly pried the watch open, and then put a small dice-box into his eye and peered into its machinery. He said it wanted cleaning and oiling, besides regulating, and asked me to come in a week."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fadb30bb89e5','ch_b8484109d0b5','text','{"text": "After being cleaned and oiled, and regulated, my watch slowed down to that degree that it ticked all appointments I go to, missing my dinner, I gradually drifted back into yesterday, then the day before, then into last week and by and by the comprehension came upon me that, all solitary and alone, I was lingering alone in week before last and the world was out of sight. I seemed to detect in myself a sort of sneaking fellow-feeling for the mummy in the museum, and a desire to swap news with him."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7db6efcd796','ch_b8484109d0b5','text','{"text": "I went to a watchmaker again. He took the watch all to pieces while I waited and then said the barrel was ‘swelled’. He said he could reduce it in three days. After this the watch averaged well, but nothing more. For a half day it would go like the very mischief, and keep up such a barking and wheezing and whooping and sneezing and snorting that I could not hear myself think for the disturbance: and as it held out there was not a watch in the land that stood any chance against it."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1446aac19d65','ch_b8484109d0b5','text','{"text": "But the rest of the day it would keep on slowing down and fooling along until all the clocks it had left behind caught up again. It would show a fair and square average, and no man could say it had done more or less than its duty."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7f5ee4a01a3','ch_b8484109d0b5','heading','{"level": 2, "text": "Ii"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac809e636732','ch_b8484109d0b5','text','{"text": "But a correct average is only a mild virtue in a watch and I took this instrument to another watchmaker. He said the king-bolt was broken. I said I was glad it was nothing more serious."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e5cce5020e0','ch_b8484109d0b5','text','{"text": "To tell the plain truth, I had no idea what the king-bolt was, but I did not choose to appear ignorant to a stranger. He repaired the king-bolt but what the watch gained in one way it lost in another. It would run a while and then stop a while, and then run a while again, and so on, using its own discretion about the intervals. And every time it went off it kicked back like a musket. I padded my breast for a few days but, finally, took the watch to another watchmaker."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6845695504f7','ch_b8484109d0b5','text','{"text": "He picked it all to pieces and turned the ruin over and over under his glass; and then he said there appeared to be fresh start. It did well now, except that always at ten minutes to ten the hands would shut together like a pair of scissors and from that time forth they would travel together. The oldest man in the world could not make head or tail of the time of day by such a watch, and so I went again to have the thing repaired."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_34ae5fae026b','ch_b8484109d0b5','text','{"text": "This person said that the crystal had got bent and the mainspring was not straight."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe5c90cbf2af','ch_b8484109d0b5','text','{"text": "He made these things all right and then my timepiece performed unexceptionably, save that now and then, after working along quietly for nearly eight hours, everything inside would let go all of a sudden and begin to buzz like a bee, and the hands would straightway begin to spin round and round so fast that their individuality was lost completely, and they simply seemed a delicate spider’s web over the face of the watch."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96af303a8452','ch_b8484109d0b5','text','{"text": "She would reel off the next twenty-four hours in six or seven minutes, and then stop with a bang. I went with a heavy heart to one more watchmaker, and looked on while he took her to pieces. Then I prepared to cross-question him rigidly, for this thing was getting serious. The watch had cost two hundred dollars originally, and I seemed to have paid out two or three thousand for repairs."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_252947ca7776','ch_b8484109d0b5','text','{"text": "While I waited and looked on, I presently recognised in this watchmaker an old acquaintance—a steam-boat engineer of other days and not a good engineer, either. He examined all the parts 148 Woven Words carefully, just as the other watchmakers had done, and then delivered his verdict with the same confidence of manner. He said:"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2097bfcbfe5f','ch_b8484109d0b5','text','{"text": "‘She makes too much steam— you want to hang the monkey-wrench on the safety-valve!’ I brained him on the spot and had him buried at my own expense."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_276b9ecdfabc','ch_b8484109d0b5','text','{"text": "My uncle William (now deceased, alas!) used to say that a good horse was a good horse until it had run away once, and that a good watch was a good watch until the repairers got a chance at it. And he used to wonder what became of all the unsuccessful tinkers, and gunsmiths, and shoe-makers, and engineers, and blacksmiths; but nobody could ever tell him."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_748cb25e7612','ch_b8484109d0b5','list','{"ordered": false, "items": ["Mark Twain"]}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4b329ac1e13','ch_b8484109d0b5','heading','{"level": 2, "text": "About The Author"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e4187a3b82f','ch_b8484109d0b5','text','{"text": "Samuel L. Clemens (1835–1910), who used the pseudonym Mark Twain, was an American humorist, short story writer and novelist. Brought up in the small town of Hannibal, Missouri, Mark Twain had less than 10 years of schooling. He worked as a printer’s apprentice, a steamboat pilot, a prospector and a journalist. All this gave him varied experiences and a wide knowledge of humanity. In the Adventures of Tom Sawyer, he drew on his own childhood; The Adventures of Huckleberry Finn, which was planned merely as a sequel, went on to become a masterpiece, the story being narrated through an uneducated boy."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5013b804569','ch_b8484109d0b5','heading','{"level": 2, "text": "Understanding The Text"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_944f7d900a2c','ch_b8484109d0b5','text','{"text": "1. What was the importance of the watch to the author?"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b802c29a25dd','ch_b8484109d0b5','text','{"text": "2. What were the attempts made by the author to get his watch repaired?"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a03afec0527','ch_b8484109d0b5','text','{"text": "3. Why did the author finally give up on his watch?"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_078d1af29756','ch_b8484109d0b5','text','{"text": "4. What was Uncle Williams’ comment on the ‘tinkerers’ of the world?"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5174fc474559','ch_b8484109d0b5','text','{"text": "5. Explain these lines"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c5c21910da1','ch_b8484109d0b5','text','{"text": "a. ‘I seemd to detect in myself a sort of sneaking fellow-feeling for the mummy in the museum, and a desire to swap news with him.’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbf3ea8df834','ch_b8484109d0b5','text','{"text": "b. ‘Within a week it sickened to a raging fever and its pulse went up to a hundred and fifty in the shade.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28d1b2fdae47','ch_b8484109d0b5','text','{"text": "c. ‘She makes too much steam—you want to hang the monkey wrench on the safety valve!’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63fcab9f52ec','ch_b8484109d0b5','heading','{"level": 2, "text": "Talking About The Text"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8633ab36a855','ch_b8484109d0b5','text','{"text": "Discuss in pairs or groups of four"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ede8c274df4','ch_b8484109d0b5','text','{"text": "1. Replacing old machines with new is better than getting them repaired."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8593f2fa7ca3','ch_b8484109d0b5','text','{"text": "2. It is difficult to part with personal items like a watch which have a sentimental value attached to them."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bca012c553b0','ch_b8484109d0b5','heading','{"level": 2, "text": "Appreciation"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5707aad93abb','ch_b8484109d0b5','text','{"text": "1. How is humour employed to comment on the pains that the author took to get his watch set right?"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c65d4b31b6ec','ch_b8484109d0b5','text','{"text": "2. ‘The author’s treatment of the subject matter makes the readers identify themselves with the experience.’ Comment on this statement."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a6900ad7337','ch_b8484109d0b5','text','{"text": "3. Identify some of the improbable images the author has used to effect greater humour."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d70383adb647','ch_b8484109d0b5','heading','{"level": 2, "text": "Language Work"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_377e58f8c777','ch_b8484109d0b5','text','{"text": "Make a list of the expressions that imbue the watch with human attributes."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_954b7d5d13e6','ch_b8484109d0b5','heading','{"level": 2, "text": "Suggested Reading"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d402de3be8b','ch_b8484109d0b5','text','{"text": "1. The Adventures of Huckleberry Finn by Mark Twain"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_306bf9f0b621','ch_b8484109d0b5','text','{"text": "2. The Mysterious Stranger and Other Stories by Mark Twain."}',45);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_8a55f07ee8e4','bk_ncert_english','11-23-my-three-passions','11.23 My Three Passions',NULL,'public',64,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1d13100bd47','ch_8a55f07ee8e4','text','{"text": "Three passions, simple but overwhelmingly strong, have governed my life: the longing for love, the search for knowledge, and unbearable pity for the suffering of mankind. These passions, like great winds, have blown me hither and thither, in a wayward course, over a deep ocean of anguish, reaching to the very verge of despair."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a505397a7302','ch_8a55f07ee8e4','text','{"text": "I have sought love, first, because it brings ecstasy— ecstasy so great that I would often have sacrificed all the rest of life for a few hours of this joy. I have sought it, next, because it relieves loneliness—that terrible loneliness in which one shivering consciousness looks over the rim of the world into the cold unfathomable lifeless abyss."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7690cb0e461','ch_8a55f07ee8e4','text','{"text": "I have sought it, finally, because in the union of love, I have seen, in a mystic miniature, the prefiguring vision of the heaven that saints and poets have imagined. This is what I sought and, though it might seem too good for human life, this is what at least I have found. With equal passion, I have sought knowledge. I have wished to understand the hearts of men. I have wished to know why the stars shine."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f1ee94a09f8','ch_8a55f07ee8e4','text','{"text": "And I have tried to apprehend the Pythagorean power by which number holds sway over the flux. A little of this, but not much, I have achieved. Love and knowledge, so far as they were possible, led upward toward the heavens. But always pity brought me back to earth. Echoes of cries of pain reverberate in my heart."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f2273f7cf3d','ch_8a55f07ee8e4','text','{"text": "Children in famine, victims tortured by oppressors, helpless old people a hated burden to their sons, and the whole world of loneliness, poverty and pain make a mockery of what human life should be. I long to alleviate the evil, but I cannot, and I too suffer. This has been my life. I have found it worth living, and would gladly live it again if the chance were offered to me."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa2cad156fda','ch_8a55f07ee8e4','list','{"ordered": false, "items": ["Bertrand Russell"]}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad162d094afb','ch_8a55f07ee8e4','heading','{"level": 2, "text": "About The Author"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe0f6a4bc85b','ch_8a55f07ee8e4','text','{"text": "Bertrand Russell (1872–1969), the British philosopher and mathematician, has written numerous popular works on philosophy, politics and education. He took a major part in the twentieth century revival of logic and made continued effort to identify the methods of philosophy with those of the sciences. He received the Nobel Prize for literature in 1950. The above passage is an extract from Bertrand Russell’s Autobiography."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1ae9126c87e','ch_8a55f07ee8e4','text','{"text": "Read the summary of Martin Luther’s King’s distinction between three kinds of love given below."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32686b6a6a20','ch_8a55f07ee8e4','text','{"text": "King’s sixth point was central to the method of non-violent resistance. He believed that the importance of non-violence rested in the fact that it prevented physical violence and the"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97248dc3a832','ch_8a55f07ee8e4','text','{"text": "‘internal violence of spirit’."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_403130be5bc6','ch_8a55f07ee8e4','text','{"text": "Bitterness and hate were absent from the resister’s mind, and replaced with love. However, the kind of love King was talking about was not the affectionate type but, instead, the type that meant"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_577c615425ce','ch_8a55f07ee8e4','text','{"text": "‘understanding, redeeming good will for all people’."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_869c1e875c57','ch_8a55f07ee8e4','text','{"text": "He further explained that in the Greek New Testament, there were three words for love and each had a different meaning. Eros was romantic love and philla was a reciprocal love. Neither of these two types of love were the kind that King advanced. Agape, which was not a passive love, was the kind of redemptive love he referred to. According to King, ‘It is an overflowing love which is purely spontaneous, unmotivated, groundless and creative."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d16e85339cf9','ch_8a55f07ee8e4','text','{"text": "It is not set in motion by any quality or function of its object. It is the love of God operating in the human heart.’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_390a952ab674','ch_8a55f07ee8e4','text','{"text": "Additionally, it was a love that was disinterested. The act of loving was not for one’s own good but for the good of another. It did not distinguish between worthy and unworthy people or friends and enemies. Furthermore, it was love that fulfilled the need of another person. A person was in greatest need of love when a sinner. King also believed that agape sought to preserve and create community. As a result, no distance was too far to travel in the attempt to restore community. Agape was, ...a"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29fca8d533e3','ch_8a55f07ee8e4','text','{"text": "willingness to forgive, not seven times, but seventy times to restore community. The cross is the eternal expression of the length to which God will go in order to restore broken community. The resurrection is a symbol of God’s triumph over all the forces that seek to block community. The Holy Spirit is the continuing community creating reality that moves through history. He who works against community is working against the whole of creation."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47524fea85c9','ch_8a55f07ee8e4','text','{"text": "Thus, hateful responses promote a broken community and instead one must respond to hate with love in order to avoid becoming depersonalised and to fix a broken community. Lastly, agape means that every aspect of life is interrelated. All human beings are related to one another and by harming another they harm themselves. Martin Luther King was a man who believed that the power of love could be the most effective weapon against the social ills of society."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9c814e5a101','ch_8a55f07ee8e4','text','{"text": "He promoted resistance that was nonviolent and, in the end, it proved to be the most successful method against an unjust system of segregation."}',19);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b74a25ba3fd0','bk_ncert_english','11-23-patterns-of-creativity','11.23 Patterns of Creativity',NULL,'public',65,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d82199d07d09','ch_b74a25ba3fd0','text','{"text": "...But I must return to the question: why is there a difference in the patterns of creativity among the practitioners in the arts and the practitioners in the sciences? 1 shall not attempt to answer this question directly;"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb9fada44990','ch_b74a25ba3fd0','text','{"text": "but I shall make an assortment of remarks which may bear on the answer. First, I should like to consider how scientists and poets view one another."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_241e20902ead','ch_b74a25ba3fd0','text','{"text": "When one thinks of the attitude of poets to science, one almost always thinks of Wordsworth and Keats and their off-quoted lines"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c77c0968d9d','ch_b74a25ba3fd0','text','{"text": "A fingering slave,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccce095547cb','ch_b74a25ba3fd0','text','{"text": "One that would peep and botanises"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e31e36ba38eb','ch_b74a25ba3fd0','text','{"text": "Upon his mother’s grave?"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36a0fffc9d40','ch_b74a25ba3fd0','text','{"text": "A reasoning self-suffering thing."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19697421c303','ch_b74a25ba3fd0','text','{"text": "An intellectual AlI-in-AIl!"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_022d6af87cb6','ch_b74a25ba3fd0','text','{"text": "Sweet is the lore which Nature brings:"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b69f0d3d4cd','ch_b74a25ba3fd0','text','{"text": "Our meddling intellect"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb38c906645e','ch_b74a25ba3fd0','text','{"text": "Misshapes the beauteous forms of things:"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b007c071d98d','ch_b74a25ba3fd0','text','{"text": "We murder to dissect."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b52749b580f','ch_b74a25ba3fd0','text','{"text": "(Wordsworth)"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7425f38b633d','ch_b74a25ba3fd0','text','{"text": "Do not all charms fly"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32aee8839453','ch_b74a25ba3fd0','text','{"text": "At the mere touch of cold philosophy?"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_880572dbdf59','ch_b74a25ba3fd0','text','{"text": "There was an awful rainbow once in heaven:"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d7ebedab0e9','ch_b74a25ba3fd0','text','{"text": "We know her woof, her texture; she is given"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2776cd220cb','ch_b74a25ba3fd0','text','{"text": "In the dull catalogue of common things."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0647d947b07','ch_b74a25ba3fd0','text','{"text": "Philosophy will clip an Angel’s wings."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_039a69533615','ch_b74a25ba3fd0','text','{"text": "(Keats)"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd386a402338','ch_b74a25ba3fd0','text','{"text": "These lines, perhaps, find an echo in a statement of Lowes Dickinson, ‘When Science arrives, it expels Literature’. It is to be expected that one should find scientists countering these views."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_702a71a57b09','ch_b74a25ba3fd0','text','{"text": "Thus, Peter Medawar counters Lowes Dickinson by"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f542fe0a002','ch_b74a25ba3fd0','text','{"text": "The case I shall find evidence for is that when literature"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03bdc974ecac','ch_b74a25ba3fd0','text','{"text": "arrives, it expels science… The way things are at present,"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f08eef80078a','ch_b74a25ba3fd0','text','{"text": "it is simply no good pretending that science and literature"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e0576aa9fdd','ch_b74a25ba3fd0','text','{"text": "represent complementary and mutually sustaining"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48ccc093991f','ch_b74a25ba3fd0','text','{"text": "endeavours to reach a common goal. On the contrary,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64c5a273b6b4','ch_b74a25ba3fd0','text','{"text": "where they might be expected to cooperate they compete."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bd14df6f6d6','ch_b74a25ba3fd0','text','{"text": "It would not seem to me that one can go very far in these matters by pointing accusing fingers at one another."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_053324f3fa73','ch_b74a25ba3fd0','text','{"text": "So, let me only say that the attitudes of Wordsworth and Keats are by no means typical. A scientist should rather consider the attitude of Shelley. Shelley is a scientist’s poet. It is not an accident that the most discriminating literary criticism of Shelley’s thought and work is by a distinguished scientist, Desmond King-Hele."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b60e3c41ad5','ch_b74a25ba3fd0','text','{"text": "As King-Hele has pointed out, ‘Shelley’s attitude to science emphasises the surprising modern climate of thoughts in which he chose to live and Shelley describes the mechanisms of nature with a precision and a wealth of detail unparalleled in English poetry’. And here is A.N. Whitehead’s testimony"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4dd2056fd6b','ch_b74a25ba3fd0','text','{"text": "Shelley’s attitude to Science was at the opposite pole to"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b71c433000b0','ch_b74a25ba3fd0','text','{"text": "that of Wordsworth. He loved it, and is never tired of"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea795e0bca49','ch_b74a25ba3fd0','text','{"text": "expressing in poetry the thoughts which it suggests. It"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_315942017f25','ch_b74a25ba3fd0','text','{"text": "symbolises to him joy, and peace, and illumination…"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ddba38ee8a9','ch_b74a25ba3fd0','text','{"text": "I should like to read two examples from Shelley’s poetry which support what has been said about him. The first example is from his Cloud which ‘fuses together a creative myth, a scientific monograph, and a gay picaresque tale of cloud adventure’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da05d5405b41','ch_b74a25ba3fd0','text','{"text": "I am the daughter of Earth and Water,"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3f9348e2dc1','ch_b74a25ba3fd0','text','{"text": "And the nursling of the Sky:"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fddd7fc0f05d','ch_b74a25ba3fd0','text','{"text": "I pass through the pores of the ocean and the shores:"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c70ec74e544b','ch_b74a25ba3fd0','text','{"text": "I change, but I cannot die."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_763b900e473b','ch_b74a25ba3fd0','text','{"text": "For after the rain when never a stain"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46320590e031','ch_b74a25ba3fd0','text','{"text": "The pavilion of Heaven is bare,"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adf277e7ecfd','ch_b74a25ba3fd0','text','{"text": "And the winds and sunbeams with their convex gleams"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a66b1279322','ch_b74a25ba3fd0','text','{"text": "Build up the blue dome of air,"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f5fa0341b22','ch_b74a25ba3fd0','text','{"text": "I silently laugh at my own cenotaph,"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a242759189b7','ch_b74a25ba3fd0','text','{"text": "And out of the caverns of rain,"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa6f00a18666','ch_b74a25ba3fd0','text','{"text": "Like a child from the womb, like a ghost from the tomb,"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eaff50f09ea6','ch_b74a25ba3fd0','text','{"text": "I arise and unbuild it again."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a82c62016648','ch_b74a25ba3fd0','text','{"text": "The second example is from Prometheus Unbound, which has been described by Herbert Read as ‘the greatest expression ever given to humanity’s desire for intellectual light and spiritual liberty’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9811bc6c5406','ch_b74a25ba3fd0','text','{"text": "The lightning is his slave, heaven’s utmost deep"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9db43ea30b2b','ch_b74a25ba3fd0','text','{"text": "Gives up her stars, and like a flock of sheep"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9845c259b5f6','ch_b74a25ba3fd0','text','{"text": "They pass before his eye, are numbered, and roll on!"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5432e48bcd7c','ch_b74a25ba3fd0','text','{"text": "The tempest is his steed, he strides the air;"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f5a27bd9707','ch_b74a25ba3fd0','text','{"text": "And the abyss shouts from her depth laid bare,"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b009052ec133','ch_b74a25ba3fd0','text','{"text": "Heaven, hast thou secrets? Man unveils me: I have none."}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_082155f81402','ch_b74a25ba3fd0','text','{"text": "Let me turn to a slightly different aspect of the matter. What are we to make of the following confession of Charles Darwin?"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_783e241ce1fa','ch_b74a25ba3fd0','text','{"text": "Up to the age of thirty, or beyond it, poetry of many kinds, such"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fae025dd0c93','ch_b74a25ba3fd0','text','{"text": "as the works of Milton, Gray, Byron, Wordsworth, Coleridge and"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb667c4cf641','ch_b74a25ba3fd0','text','{"text": "Shelley gave me great pleasure; and even as a school boy I took"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_557a4051ce46','ch_b74a25ba3fd0','text','{"text": "intense delight in Shakespeare, especially historical plays... I"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5fc8ea919c88','ch_b74a25ba3fd0','text','{"text": "have also said that formerly pictures gave me considerable,"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b8c437753fa','ch_b74a25ba3fd0','text','{"text": "and music very great, delight. But now, for many years, I cannot"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_145a95b44173','ch_b74a25ba3fd0','text','{"text": "endure to read a line of poetry; I have tried lately to read"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb6a29cb3a4a','ch_b74a25ba3fd0','text','{"text": "Shakespeare and found it so intolerably dull that it nauseated"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b71adaef351','ch_b74a25ba3fd0','text','{"text": "me. I have almost lost my taste for pictures or music... My mind"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a0a3c6550b6','ch_b74a25ba3fd0','text','{"text": "seems to have become a kind of machine for grinding general"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc1e08852a1d','ch_b74a25ba3fd0','text','{"text": "laws out of large collections of facts but why this should have"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_704309df4bf7','ch_b74a25ba3fd0','text','{"text": "caused the atrophy of that part of the brain alone on which the"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4b7e68a7b808','ch_b74a25ba3fd0','text','{"text": "higher tastes depend, I cannot conceive."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e29db1976be','ch_b74a25ba3fd0','text','{"text": "Or consider this: Faraday discovered the laws of electromagnetic induction and his discoveries led him to formulate concepts such as ‘lines of force’ and ‘fields of force’ which were foreign to the then prevailing modes of thought. They were, in fact, looked askance by many of his contemporaries. But of Faraday’s ideas, Maxwell wrote with prophetic discernment"}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_627639f93b85','ch_b74a25ba3fd0','text','{"text": "The way in which Faraday made use of his idea of the"}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_882df18dde9b','ch_b74a25ba3fd0','text','{"text": "lines of force in coordinating the phenomenon of electromagnetic"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a97f8698c5e2','ch_b74a25ba3fd0','text','{"text": "induction shows him to have been, in reality, a"}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e91918e6a42','ch_b74a25ba3fd0','text','{"text": "mathematician of a very high order—one from whom the"}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b67341919b5','ch_b74a25ba3fd0','text','{"text": "mathematicians of the future may derive valuable and"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61b9f546b143','ch_b74a25ba3fd0','text','{"text": "fertile methods. We are probably ignorant even of the name"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5ffd8c5b3a8','ch_b74a25ba3fd0','text','{"text": "of the science which will be developed out of the materials"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2cd188862c88','ch_b74a25ba3fd0','text','{"text": "we are now collecting, when the great philosopher next"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47511f5677d8','ch_b74a25ba3fd0','text','{"text": "after Faraday makes his appearance."}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbd35446cc7e','ch_b74a25ba3fd0','text','{"text": "And yet when Gladstone, then the Chancellor of the Exchequer, interrupted Faraday in his description of his work on electricity by the impatient inquiry, ‘But after all, what use is it?’ Faraday’s response was, ‘Why, Sir, there is every probability that you will soon be able to tax it’. And Faraday’s response has always been quoted most approvingly."}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40a569b5aa74','ch_b74a25ba3fd0','text','{"text": "It seems to me that to Darwin’s confession and to Faraday’s response, what Shelley has said about the cultivation of the sciences in his Defence of Poetry is apposite"}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_461644ae7104','ch_b74a25ba3fd0','text','{"text": "The cultivation of those sciences which have enlarged the"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_509d22780bdb','ch_b74a25ba3fd0','text','{"text": "limits of the empire of man over the external world, has,"}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_825c2bea0fed','ch_b74a25ba3fd0','text','{"text": "for want of the poetical faculty, proportionally circumscribed"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36599a43ff52','ch_b74a25ba3fd0','text','{"text": "those of the internal world; and man, having enslaved the"}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_26e26af77e2c','ch_b74a25ba3fd0','text','{"text": "elements, remains himself a slave."}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1df505d57b80','ch_b74a25ba3fd0','text','{"text": "Lest you think that Shelley is not sensitive to the role of technology in modern society, let me quote what he has said in that connection"}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53860038dda2','ch_b74a25ba3fd0','text','{"text": "Undoubtedly the promoters of utility, in this limited sense,"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23ff0c47b72a','ch_b74a25ba3fd0','text','{"text": "have their appointed office in society. They follow the"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c20ee95e9b0','ch_b74a25ba3fd0','text','{"text": "footstep of poets, and copy the sketches of their creations"}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_196a5a5acb63','ch_b74a25ba3fd0','text','{"text": "into the book of common life. They make space and give"}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fab4dee2b09d','ch_b74a25ba3fd0','text','{"text": "time."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_20e29f1d12e7','ch_b74a25ba3fd0','text','{"text": "Shelley’s A Defence of Poetry, from which I have just quoted, is one of the most moving documents in all of English literature. W.B. Yeats called it ‘the profoundest essay on the foundation of poetry in the English language’. The essay should be read in its entirety; but allow me to read a selection"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90b41f943a82','ch_b74a25ba3fd0','text','{"text": "Poetry is the record of the best and happiest moments of"}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d655620dfd0a','ch_b74a25ba3fd0','text','{"text": "the happiest and the best minds. Poetry, thus, makes"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e82698868951','ch_b74a25ba3fd0','text','{"text": "immortal all that is best and most beautiful in the world; it"}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_354545968aa2','ch_b74a25ba3fd0','text','{"text": "arrests the vanishing apparitions which haunt the"}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fbf8527364f','ch_b74a25ba3fd0','text','{"text": "interlunations of life,.."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4b4f9d03f49','ch_b74a25ba3fd0','text','{"text": "Poetry is indeed something divine. It is at once the centre"}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75ad11adbdd7','ch_b74a25ba3fd0','text','{"text": "and circumference of knowledge; it is that which"}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b62b73699109','ch_b74a25ba3fd0','text','{"text": "comprehends all science, and that to which all science"}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62f9a6a84932','ch_b74a25ba3fd0','text','{"text": "must be referred. It is, at the same time, the root and"}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b29f01f0d1b','ch_b74a25ba3fd0','text','{"text": "blossom of all other systems of thought."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e58dda59cb4','ch_b74a25ba3fd0','text','{"text": "Poets are the hierophants of an unapprehended inspiration;"}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_485030f9a8dc','ch_b74a25ba3fd0','text','{"text": "the mirrors or the gigantic shadows which futurity casts"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70a011e9d5f1','ch_b74a25ba3fd0','text','{"text": "upon the present; the words which express what they"}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c17b1fcb55ab','ch_b74a25ba3fd0','text','{"text": "understand not; the trumpets which sing to battle, and"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_560b6cd10ab5','ch_b74a25ba3fd0','text','{"text": "feel not what they inspire; the influence which is moved"}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5ef36a98876','ch_b74a25ba3fd0','text','{"text": "not, but moves. Poets are the unacknowledged legislators"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28f18bc3f710','ch_b74a25ba3fd0','text','{"text": "of the world."}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8fd5ecaf59c4','ch_b74a25ba3fd0','text','{"text": "On reading Shelley’s A Defence of Poetry, the question insistently occurs why there is no similar A Defence of Science written by a scientist of equal endowment. Perhaps in raising the question I have, in part, suggested an answer to the one I have repeatedly asked during the lecture. \\"}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_953c39c7335a','ch_b74a25ba3fd0','list','{"ordered": false, "items": ["S. Chandrasekhar"]}',112);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_084d86854d6b','ch_b74a25ba3fd0','heading','{"level": 2, "text": "About The Author"}',113);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5ecd4210356','ch_b74a25ba3fd0','text','{"text": "S. Chandrasekhar (1910-1995) was a distinguished astrophysicist and Nobel Laureate."}',114);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc4be060dd36','ch_b74a25ba3fd0','text','{"text": "He was a Professor Emeritus in the Department of Astronomy and Astrophysics at the University of Chicago. He received many awards and wrote several books. Truth and Beauty from which"}',115);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_136109c1ab40','ch_b74a25ba3fd0','text','{"text": "‘Patterns of Creativity’ has been taken is a collection of seven lectures addressing aesthetics and motivation in the pursuit of science and contemplates patterns of scientific creativity. The extract is from The Nora and Edward Byerson Lecture titled ‘Shakespeare, Newton and Beethoven, or Patterns of Creativity’."}',116);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2620cf2f1fc5','ch_b74a25ba3fd0','heading','{"level": 2, "text": "Understanding The Text"}',117);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c5e2d6f9626','ch_b74a25ba3fd0','text','{"text": "1. How does Shelley’s attitude to science differ from that of Wordsworth and Keats?"}',118);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a9a9a40e3968','ch_b74a25ba3fd0','text','{"text": "2. ‘It is not an accident that the most discriminating literary criticism of Shelley’s thought and work is by a distinguished scientist, Desmond King-Hele.’ How does this statement bring out the meeting point of poetry and science?"}',119);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e06ba7cdbbd','ch_b74a25ba3fd0','text','{"text": "3. What do you infer from Darwin’s comment on his indifference to literature as he advanced in years?"}',120);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6aeeba59bba6','ch_b74a25ba3fd0','text','{"text": "4. How do the patterns of creativity displayed by scientists differ from those displayed by poets?"}',121);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b232f015ba53','ch_b74a25ba3fd0','text','{"text": "5. What is the central argument of the speaker?"}',122);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_74fd12b5b37f','bk_ncert_english','11-24-tribal-verse','11.24 Tribal Verse',NULL,'public',66,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec8bab4057c5','ch_74fd12b5b37f','heading','{"level": 2, "text": "Introduction"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_139a54bd399b','ch_74fd12b5b37f','text','{"text": "The roots of India’s literary traditions can be traced to the rich oral literatures of the tribes/adivasis. Usually in the form of songs or chanting, these verses are expressions of the close contact between the world of nature and the world of tribal existence. They have been orally transmitted from generation to generation and have survived for several ages. However, a large number of these are already lost due to the very fact of their orality."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_049f76758a08','ch_74fd12b5b37f','text','{"text": "The forces of urbanisation, print culture and commerce have resulted in not just the marginalisation of these communities but also of their languages and literary cultures. Though some attempts have been made for the collection and conservation of tribal languages and their literatures, without more concerted efforts at an acelerated pace, we are in danger of losing an invaluable part of our history and rich literary heritage."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b93588f4e4c2','ch_74fd12b5b37f','text','{"text": "This section is a small attempt to familiarise students with some aspects of the enormous wealth of oral tribal literature. It begins with an extract from an essay by G.N. Devy in which he discusses the need to create a space for the study of tribal literature within the framework of canonized written texts. What he argues for is the need for a new method to identify and read literature in which orality is not dismissed as casual utterances in different dialects."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_605cc5f1496a','ch_74fd12b5b37f','text','{"text": "This is followed by two songs—one sung on the occasion of childbirth by the Munda tribals and the other on the occasion of death by the Kondh tribals. The third verse is a chanting in the ritualistic religious language of the Adi tribe, not the same as their language of conversation. Even though this is merely a small representation of a treasure of tribal/adivasi songs, it indicates the immense diversity that exists amongst tribal groups."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9341a05e505','ch_74fd12b5b37f','text','{"text": "Inevitably influenced by their very specific historical, cultural and geographical locations, tribal societies continue to retain and reproduce their distinctive traditions which usually find expression through their different languages. However, it is equally true that though possessing their very specific languages, most tribal societies such as Munda, Kondh, Adi and Bondo are bilingual."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e386114ab46','ch_74fd12b5b37f','text','{"text": "Moreover, while tribal groups like the Santhal become important subjects in dominant literary streams such as Bangla literature, there is a fairly well developed Santhali literature too. Besides this, tribes like Santhal and Munda have also played a prominent role in the sociopolitical movements of their regions. [Birsa Munda (1874–1901) spent his whole life fighting against colonialism and the exploitation of labourers]."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1ce1ba4e4cbc','ch_74fd12b5b37f','text','{"text": "The Santhals have emerged as a prominent group at the regional and state levels through their participation in the Jharkhand Movement. The three selected songs give us a small glimpse into the rich repository of folk songs that is an expression of the tribal vision of life. Their close connection with nature is evident from their belief in the interdependence between human beings and nature."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe037b80537d','ch_74fd12b5b37f','text','{"text": "Nature for them is living and responsive to human existence and human actions, demanding respect essential for any kind of coexistence. The songs exist originally in the native languages of the tribals and are sung or chanted. The effort to bring them to students in English naturally involves some loss of the original flavour and spirit but that is a problem of all translation and constant attempts need to be made to minimise this loss."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df76c655e22b','ch_74fd12b5b37f','text','{"text": "But for some conscious effort being made to first preserve these songs, these pieces of literature would have been lost to us completely. However limitedly, it is only through translation that we are able to even access these works."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bedefd796958','ch_74fd12b5b37f','text','{"text": "‘INTRODUCTION’ TO PAINTED WORDS ..."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea6a6d64a006','ch_74fd12b5b37f','text','{"text": "Most tribal communities in India are culturally similar to tribal communities elsewhere in the world. They live in groups that are cohesive and organically unified. They show very little interest in accumulating wealth or in using labour as a device to gather interest and capital. They accept a world-view in which nature, human beings and God are intimately linked and they believe in the human ability to spell and interpret truth."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5d4c0bbba19','ch_74fd12b5b37f','text','{"text": "They live more by intuition than reason, they consider the space around them more sacred than secular, and their sense of time is personal rather than objective. The world of the tribal imagination, therefore, is radically different from that of modern Indian society. Once a society accepts a secular mode of creativity within which the creator replaces God, imaginative transactions assume a self-conscious form."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b40187ceef04','ch_74fd12b5b37f','text','{"text": "The tribal imagination, on the other hand, is still, to a large extent, dreamlike and hallucinatory. It admits fusion between various planes of existence and levels of time in a natural way. In tribal stories, oceans fly in the sky as birds, mountains swim in the water as fish, animals speak as humans and stars grow like plants. Spatial order and temporal sequence do not restrict the narrative."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3de8b56ce200','ch_74fd12b5b37f','text','{"text": "This is not to say that tribal creations have no conventions or rules but simply that they admit the principle of association between emotion and the narrative motif. Thus stars, seas, mountains, trees, men and animals, can be angry, sad or happy. It might be said that tribal artists work more on the basis of their racial and sensory memory than on the basis of a cultivated imagination. In order to understand this distinction, we must understand the difference between imagination and memory."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d26f2df40b2','ch_74fd12b5b37f','text','{"text": "In the animate world, consciousness meets two immediate material realities: space and time. We put meaning into space by perceiving it in terms of images. The image making faculty is a genetic gift to the human mind—this power of imagination helps us understand the space that envelops us. In the case of time, we make connections with the help of memory;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adca713cc264','ch_74fd12b5b37f','text','{"text": "one remembers being the same person as one was yesterday. The tribal mind has a more acute sense of time than sense of space."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7508f6992cc','ch_74fd12b5b37f','text','{"text": "Somewhere along the history of human civilization, tribal communities seem to have realised that domination over territorial space was not their lot. Thus, they seem to have turned almost obsessively to gaining domination over time."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05f5551bef02','ch_74fd12b5b37f','text','{"text": "This urge is substantiated in their ritual of conversing with their dead ancestors: year after year, tribals in many parts of India worship terracotta, or carved-wood objects, representing their ancestors, aspiring to enter a trance in which they can converse with the dead. Over the centuries, an amazingly sharp memory has helped tribals classify material and natural objects into a highly complex system of knowledge."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb25e0587ffb','ch_74fd12b5b37f','text','{"text": "The importance of memory in tribal systems of knowledge has not yet been sufficiently recognised but the aesthetic proportions of the houses that tribals build, the objects they make and the rituals they perform fascinate the curious onlooker. It can be hard to understand how, without any institutional training or tutoring, tribals are able to dance, sing, craft, build and speak so well ..."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1801d088135','ch_74fd12b5b37f','text','{"text": "A vast number of Indian languages have yet remained only spoken, with the result that literary compositions in these languages are not considered ‘literature’. They are a feast for the folklorist, anthropologist and linguist but, to a literary critic, they generally mean nothing. Similarly, several nomadic Indian communities are broken up and spread over long distances but survive as communities because they are bound by their oral epics. The wealth and variety of these works is so enormous that one discovers their neglect with a sense of pure shame."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4023e10e61c6','ch_74fd12b5b37f','text','{"text": "Some of the songs and stories I heard from itinerant street singers in my childhood are no longer available anywhere. For some years now I have been collecting songs and stories that circulate in India’s tribal languages, and I am continually overwhelmed by their number and their profound influence on the tribal communities. The result is that I, for one, can no longer think of literature as something written."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_191cb21f4523','ch_74fd12b5b37f','text','{"text": "Of course I do not dispute the claim of written compositions and texts to the status of literature;"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2db9d78b72e0','ch_74fd12b5b37f','text','{"text": "but surely it is time we realise that unless we modify the established notion of literature as something written, we will silently witness the decline of various Indian oral traditions. That literature is a lot more than writing is a reminder necessary for our times."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2f44a9bcbd4','ch_74fd12b5b37f','text','{"text": "One of the main characteristics of tribal arts is their distinct manner of constructing space and imagery, which might be described as ‘hallucinatory’. In both oral and visual forms of representation, tribal artists seem to interpret verbal or pictorial space as demarcated by an extremely flexible ‘frame’. The boundaries between art and non-art become almost invisible. A tribal epic can begin its narration from a trivial everyday event;"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c37610fac7b','ch_74fd12b5b37f','text','{"text": "tribal paintings merge with living space as if the two were one and the same. And within the narrative itself, or within the painted imagery, there is no deliberate attempt to follow a sequence. The episodes retold and the images created take on the apparently chaotic shapes of dreams."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6f0f29f4ef4','ch_74fd12b5b37f','text','{"text": "In a tribal Ramayan, an episode from the Mahabharat makes a sudden and surprising appearance;"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42e16a3a71db','ch_74fd12b5b37f','text','{"text": "tribal paintings contain a curious mixture of traditional and modern imagery. In a way, the syntax of language and the grammar of painting are the same, as if literature were painted words and painting were a song of images. Yet it is not safe to assume that the tribal arts do not employ any ordering principles. On the contrary, the ordering principles are very strict."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_42965daf2d05','ch_74fd12b5b37f','text','{"text": "The most important among these is convention. Though the casual spectator may not notice, every tribal performance and creation has, at its back, another such performance or creation belonging to a previous occasion. The creativity of the tribal artist lies in adhering to the past while, at the same time, slightly subverting it. The subversions are more playful than ironic. Indeed, playfulness is the soul of tribal arts."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c5ec8ec9e21','ch_74fd12b5b37f','text','{"text": "Though oral and pictorial tribal art creations are intimately related to rituals—the sacred can never be left out—the tribal arts rarely assume a serious or pretentious tone. The artist rarely plays the role of the Creator. Listening to tribal epics can be great fun as even the heroes are not spared the occasional shock of the artist’s humour. One reason for this unique mixture of the sacred and the ordinary may be that tribal works of art are not created specifically for sale."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b33bb3b72c3','ch_74fd12b5b37f','text','{"text": "Artists do expect a certain amount of patronage from the community, like artists in any other context; but, since those performing rituals are very often artists themselves, there is no element of competition in the patron-artist relationship. The tribal arts are, therefore, relaxed, never tense... One question invariably asked about the tribal arts is whether they are static—frozen in tradition— or dynamic."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57777aac25f8','ch_74fd12b5b37f','text','{"text": "A general misconception is that the orally transmitted arts are entirely tradition-bound, with little scope for individual experimentation beyond the small freedom to distort the previously created text. This misconception arises from the habit of seeing art only with reference to the text but the tribal arts involve not just text but performance and audience reception. Experimentation in the tribal arts can be understood only when they are approached as performing arts."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b716dd7f073','ch_74fd12b5b37f','text','{"text": "Non-tribals usually fail to notice that all of India’s tribal communities are basically bilingual. All bilingual communities have an innate capacity to assimilate outside influences and, in this case, a highly evolved mechanism for responding to the non-tribal world. The tribal oral stories and songs employ bilingualism in such a complex manner that a linguist who is not alert to this complexity is in danger of dismissing the tribal languages altogether as dialects of India’s major tongues..."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc7ae043f273','ch_74fd12b5b37f','text','{"text": "The language into which the works have been translated, English, carries massive colonial baggage. When the works of contemporary Indian writers—who inherit a multilingual tradition several thousand years old—were classified as ‘new literature’, Western academics had no idea how comical this classification looked to the literary community in India. Hence it is neccessary to assert that the literature of the adivasis is not a new ‘movement’ or a fresh ‘trend’ in the field of literature;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72997ed0328f','ch_74fd12b5b37f','text','{"text": "most people have simply been unaware of its existence and that is not the fault of the tribals themselves. What might be new is the present attempt to see imaginative expression in tribal language not as ‘folklore’ but as literature and to hear tribal speech not as a dialect but as a language. This attitude may be somewhat unconventional but only until we recall that scripts themselves are relatively new, and that the printing of literary text goes no further back than a few centuries—in comparison with creative experiments with the human ability to produce speech in such a way that it transcends time. In fact, every written piece of literature contains substantial layers of orality."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b059f670464','ch_74fd12b5b37f','text','{"text": "This is particularly true for poetry and drama but, even in prose fiction, the elements of orality need to be significant if the work is to be effective."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f2434aabf4a','ch_74fd12b5b37f','heading','{"level": 2, "text": "1. A Munda Song: Song Of Birth And Death"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52ec053fa3b2','ch_74fd12b5b37f','text','{"text": "My mother, the sun rose"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40723908ae3e','ch_74fd12b5b37f','text','{"text": "A son was born."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ab73cd302b9','ch_74fd12b5b37f','text','{"text": "My mother, the moon rose"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3bed8c827eb2','ch_74fd12b5b37f','text','{"text": "A daughter was born."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d2a4be0d2d8','ch_74fd12b5b37f','text','{"text": "A son was born"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c8f51f9a151','ch_74fd12b5b37f','text','{"text": "The cowshed was depleted;"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_03a793b48358','ch_74fd12b5b37f','text','{"text": "A daughter was born"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fa7bd0794fb5','ch_74fd12b5b37f','text','{"text": "The cowshed filled up."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1276cb04d172','ch_74fd12b5b37f','text','{"text": "(Translated from the original Mundari)"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58197050c22e','ch_74fd12b5b37f','text','{"text": "Note on the Munda Tribe"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62e030944f2e','ch_74fd12b5b37f','text','{"text": "The Munda tribals live in parts of Jharkhand, West Bengal, Assam, Tripura, Madhya Pradesh and Orissa. They are also known as Horohon or Mura, meaning headman of a village."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ab474be66e5','ch_74fd12b5b37f','text','{"text": "One of the most studied tribal communities of India, they also have an encyclopaedia on them, Encyclopaedia Mundarica (16 Volumes) by Reverend John Baptist Hoffman (1857–1928) and other Jesuit scholars. The Munda are probably the first of the adivasis to resist colonialism and they revolted repeatedly over agrarian issues. The Tamar insurrection of 1819–20 protested against the break-up of their agrarian system."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bd26eb1d356','ch_74fd12b5b37f','text','{"text": "In their quest to establish Munda Raj and reform their society to enable it to cope with the challenges of time, they organised the famous millennial movement under Birsa Munda (1874– 1901) where their leaders used ‘both Hindu and Christian idioms to create a Munda ideology and worldview’."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d28334c4a62b','ch_74fd12b5b37f','text','{"text": "However, the uprising was quelled by the British."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_175ba241d1a4','ch_74fd12b5b37f','text','{"text": "Note on the Munda Song"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b39c7054206f','ch_74fd12b5b37f','text','{"text": "Many ceremonies and rituals of the Munda are associated with birth, death and marriage. Living in close harmony with nature, their lives are synchronised with the changing rhythms of nature, the seasons, the rising and setting of the sun and so on, and not by clock time. The selected Munda song is sung to rhythmic folk tunes at the birth of a son or daughter and invariably communicates their close association with nature."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de5ab7cfba08','ch_74fd12b5b37f','text','{"text": "Cattle set off to the pastures in the morning and return to their sheds at sundown. The birth of a daughter is associated with a cowshed full of cows and that of the son with its depletion. Clearly the daughter is considered to be a more precious asset than the son. This is probably because, in Munda society, the women have a dominant role to play in the various economic, social and ritual activities."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60372767a911','ch_74fd12b5b37f','heading','{"level": 2, "text": "2. A Kondh Song"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdf7f4c034d8','ch_74fd12b5b37f','text','{"text": "This we offer to you."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9cd84937b62','ch_74fd12b5b37f','text','{"text": "We can,"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf80a3fe0dfa','ch_74fd12b5b37f','text','{"text": "Because we are still alive;"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b61aac659fd3','ch_74fd12b5b37f','text','{"text": "If not,"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d5268324271','ch_74fd12b5b37f','text','{"text": "How could we offer at all,"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8550d2accb62','ch_74fd12b5b37f','text','{"text": "And what ?"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4c352afeefd','ch_74fd12b5b37f','text','{"text": "We give a small baby fowl."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab6882ad9622','ch_74fd12b5b37f','text','{"text": "Take this and go away"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f8a23dec724','ch_74fd12b5b37f','text','{"text": "Whichever way you came."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e3f06ba43f6','ch_74fd12b5b37f','text','{"text": "Go back, return."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4b019e3448a','ch_74fd12b5b37f','text','{"text": "Don’t inflict pain on us"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f83ba75ebb0','ch_74fd12b5b37f','text','{"text": "After your departure."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0cd8d63e5da','ch_74fd12b5b37f','text','{"text": "(Translated from the original Kondh)"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c82010b07be8','ch_74fd12b5b37f','text','{"text": "A note on the Kondh Tribe"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f4b02a377c8','ch_74fd12b5b37f','text','{"text": "The term ‘Kondh’ is most probably derived from the Dravidian word, konda, meaning hill. Divided into several segments and distributed over the districts of Andhra Pradesh, Chattisgarh, Madhya Pradesh, Maharashtra and Orissa, these hill people speak the Kondh language though most of them are bilingual and so conversant with the major language of the state to which they belong. The Kondh religion is a mixture of the traditional faith of the adivasis and Hinduism."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1cd662e11a38','ch_74fd12b5b37f','text','{"text": "They do not have any dowry system but they do fix a bride price that the groom pays to the bride either in cash or in kind."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d0a9f76fd5d','ch_74fd12b5b37f','text','{"text": "A Note on the Kondh Song"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4800c0154b4a','ch_74fd12b5b37f','text','{"text": "The Kondhs observe a number of rituals in connection with birth, puberty, marriage and death, with specific folk dances and songs for each occasion. They believe in the existence of gods and spirits, both benevolent and malevolent. The song here is sung at the death of a person beseeching the spirit of the dead to stop troubling the living."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f21d0c5e2df5','ch_74fd12b5b37f','text','{"text": "It is based on the Kondh belief that people love their homes so much that their souls are reluctant to leave the hearth even after death. These spirits, though generally kind, can become harmful at times since they are now unable to participate in earthly life. It is, therefore, customary to make generous offerings to the spirit. The song begins by saying that the dead spirit will be able to receive offerings only if the others in the family continue to live and prosper."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a9d0216e872','ch_74fd12b5b37f','text','{"text": "They reveal their willingness to do anything to make the spirit happy but, in return, the spirit must also promise not to trouble them with its visits."}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2e9e68bc335','ch_74fd12b5b37f','heading','{"level": 2, "text": "3. Adi Song For The Recovery Of Lost Health"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6cb83b671be8','ch_74fd12b5b37f','text','{"text": "Oh my beloved one"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de126ba0f6b5','ch_74fd12b5b37f','text','{"text": "If you lost your health due to ill luck"}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76ffe1013ec1','ch_74fd12b5b37f','text','{"text": "I come forward here to save you"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1038af9a2d4e','ch_74fd12b5b37f','text','{"text": "With this Emul"}',80);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4da2d4f64b5c','ch_74fd12b5b37f','text','{"text": "To call back your lost health."}',81);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_311cb00b3267','ch_74fd12b5b37f','text','{"text": "Listen to the sound of this sweet ornament"}',82);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e25f2646f5a4','ch_74fd12b5b37f','text','{"text": "And follow me to your sweet home."}',83);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fe28062d952','ch_74fd12b5b37f','text','{"text": "I tie this Ridin creeper"}',84);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31579b839471','ch_74fd12b5b37f','text','{"text": "To fasten your soul to your body."}',85);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07af45ae7afb','ch_74fd12b5b37f','text','{"text": "Follow the footprint of this cock"}',86);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff9661e45fe0','ch_74fd12b5b37f','text','{"text": "Come, come with me to your home."}',87);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5ab527cbe20e','ch_74fd12b5b37f','text','{"text": "(Translated from the original Miri Agom)"}',88);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79800e8381d7','ch_74fd12b5b37f','text','{"text": "A Note on the Adi Tribe"}',89);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36a4aa3f9885','ch_74fd12b5b37f','text','{"text": "Adi is a generic term denoting hill people and it includes a number of groups. It may be applied to all the hill tribes around the Brahmaputra valley. The Adi are, however, concentrated in the East and West Siang district of Arunachal Pradesh."}',90);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6fef2f098a43','ch_74fd12b5b37f','text','{"text": "They believe that every object in the universe, be it human beings, animals, trees or birds, have a spirit that needs to be nourished and propitiated. Dependent on nature for many of their needs, they believe that equilibrium in nature must always be maintained. Even though hunting is considered not just a means of procuring food but also an expression of courage and skill, they still believe that human beings must hunt for survival and not for greed."}',91);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f398855a626','ch_74fd12b5b37f','text','{"text": "The Adi have two major languages that they use for two different purposes. The language for routine conversation is called Adi Agom. The second major language still in use is Miri Agom, a highly rhythmic language used for chanting during their rituals. The headman of the village is generally the best hunter as well as an expert in Miri Agom. Both languages are living languages and rituals and ceremonies provide the occasion for the teaching of Miri Agom to the younger generation."}',92);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3416ecea5c9c','ch_74fd12b5b37f','text','{"text": "A Note on the Adi Song"}',93);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d9725efcbb7c','ch_74fd12b5b37f','text','{"text": "The song selected here is actually a mantra that is chanted in Miri Agom to lure the spirit of good health back to the body of a sick person. The Adi believe that a person falls ill when the spirit of good health abandons the body due to some shock it may suffer. The above lines are chanted in a ritual performed by the maternal uncle of the sick person."}',94);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51b8b8edf110','ch_74fd12b5b37f','text','{"text": "Notes"}',95);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_929bcac6efc1','ch_74fd12b5b37f','text','{"text": "Beloved one: the loved nephew or niece who is ill."}',96);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c05939a9adbf','ch_74fd12b5b37f','text','{"text": "I come forward here to save you: the maternal uncle of the sick person comes forward to perform the ritual for the return of the spirit of good health."}',97);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffaed861d29f','ch_74fd12b5b37f','text','{"text": "Emul: amulet, here a healing ornament."}',98);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b4d2092fd98c','ch_74fd12b5b37f','text','{"text": "Listen to the sound of this ornament: this line and the ones that follow are addressed to the spirit of good health to request it to return to the ill body."}',99);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c12cff4603b9','ch_74fd12b5b37f','text','{"text": "Your sweet home: the ill body which is the real home of the spirit of good health."}',100);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88d7a8885a4a','ch_74fd12b5b37f','text','{"text": "Ridin: a creeper that is supposed to have special medicinal qualities."}',101);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60d093c92b3c','ch_74fd12b5b37f','text','{"text": "Fasten your soul to your body: the Ridin creeper will tie the spirit of good health to the body to ensure its continued presence."}',102);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96ea67f9c316','ch_74fd12b5b37f','text','{"text": "Follow the footprints of this cock: usually an offering like a cock or a hen is made to propitiate the spirit of good health and persuade it to return to the ill body."}',103);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bca0cc2c764d','ch_74fd12b5b37f','list','{"ordered": false, "items": ["G.N. Devy"]}',104);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_65926b857fcb','ch_74fd12b5b37f','heading','{"level": 2, "text": "About The Author"}',105);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_09af1f8cffc5','ch_74fd12b5b37f','text','{"text": "G.N. Devy, formerly professor of English at Maharaja Sayaji Rao University of Baroda, is the Founder Director of the Tribal Academy at Tejgarh, Gujarat. He is the Director of Sahitya Akademi’s Project on Literature in Tribal Languages and Oral Traditions. He received the Sahitya Akademi Award for his book After Amnesia and the SAARC Writer’s Foundation Award for his work on the ‘denotified tribes’."}',106);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_201b27acbdee','ch_74fd12b5b37f','heading','{"level": 2, "text": "Understanding The Text"}',107);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58865305ed43','ch_74fd12b5b37f','text','{"text": "1. Identify the common characteristics shared by tribal communities all over the world."}',108);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_930bc3ccf9b6','ch_74fd12b5b37f','text','{"text": "2. What distinguishes the tribal imagination from the secular imagination?"}',109);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52a1275cc5f3','ch_74fd12b5b37f','text','{"text": "3. How does G.N. Devy bring out the importance of the oral literary tradition?"}',110);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4a684b802d2','ch_74fd12b5b37f','text','{"text": "4. List the distinctive features of the tribal arts."}',111);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_242f69e0e039','ch_74fd12b5b37f','text','{"text": "5. ‘New literature’ is a misnomer for the wealth of the Indian literary tradition. How does G.N. Devy explain this?"}',112);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_534271444698','bk_ncert_english','11-25-what-is-a-good-book','11.25 What is a Good Book?',NULL,'public',67,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef3cb8ba5acf','ch_534271444698','text','{"text": "The good book of the hour, then—I do not speak of the bad ones—is simply the useful or pleasant talk of some person whom you cannot otherwise converse with, printed for you. Very useful often, telling you what you need to know; very pleasant often, as a sensible friend’s present talk would be."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e89a4082aef','ch_534271444698','text','{"text": "These bright accounts of travels; good-humoured and witty discussions of question; lively or pathetic story-telling in the form of novel; firm fact-telling by the real agents concerned in the events of passing history—all these books of the hour, multiplying among us as education becomes more general, are a peculiar characteristic and possession of the present age: we ought to be entirely thankful for them, and entirely ashamed of ourselves if we make no good use of them."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1abd2244881','ch_534271444698','text','{"text": "But we make the worst possible use if we allow them to usurp the place of true books: for, strictly speaking, they are not books at all but merely letters or newspapers in good print. Our friend’s letter may be delightful, or necessary, today: whether worth keeping or not, is to be considered. The newspaper may be entirely proper at breakfast time but, assuredly, it is not reading for all day."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5a738325b4c','ch_534271444698','text','{"text": "So, though bound up in a volume, the long letter which gives you so pleasant an account of the inns, and roads, and weather last year at such a place, or which tells you that amusing story or gives you the real circumstances of such and such events, however valuable for occasional reference, may not be, in the real sense of the word, a ‘book’ at all, nor, in the real sense, to be ‘read’. A book is essentially not a talked thing but a written thing; and written, not with the view of more communication, but of permanence. The book of talk is printed only because its author cannot speak to thousands of people at once; if he could, he would—the volume is mere ‘multiplication’ of his voice. You cannot talk to your friend in India;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_75274cc15a1a','ch_534271444698','text','{"text": "if you could, you would; you would write instead: that is mere ‘conveyance’ of voice. But a book is written, not to multiply the voice merely, not to carry it merely, but to preserve it. The author has something to say which he perceives to be true and useful, or helpfully beautiful. So far as he knows no one has yet said it;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e1b3911a5cba','ch_534271444698','text','{"text": "so far as he knows, no one else can say it. He is bound to say it, clearly and melodiously if he may; clearly, at all events."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97cd60663f3e','ch_534271444698','text','{"text": "In the sum of his life he finds this to be the thing or group of things, manifest to him— this is the piece of true knowledge, or sight, which his share of sunshine and earth has permitted him to seize. He would fain set it down forever, engrave it on a rock, if he could, saying, ‘This is the best of me;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_82eb38cc5f73','ch_534271444698','text','{"text": "for the rest, I ate, and drank, and slept, loved, and hated, like another;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c247f3f2446','ch_534271444698','text','{"text": "my life was as the vapour, and is not;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d93fd3bc972','ch_534271444698','text','{"text": "but this I saw and knew;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7e2a7a9eebb','ch_534271444698','text','{"text": "this, if anything, of mine, is worth your memory.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf3011f1140f','ch_534271444698','text','{"text": "That his ‘writing’, it is, in his small human way, and with whatever degree of true inspiration is in him, his inscription, or scripture.That is a"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_44b76f58b6f5','ch_534271444698','text','{"text": "‘Book’. Perhaps you think no books were ever so written? But, again, I ask you;"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_759fc289421b','ch_534271444698','text','{"text": "do you at all believe in honesty or, at all, in kindness? Or do you think there is never any honesty or benevolence in wise people? None of us, I hope, are so unhappy as to think that. Well, whatever bit of a wise man’s work is honestly and benevolently done, that bit is his book, or his piece of art. It is mixed always with evil fragments—ill-done, redundant, affected work."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41c98f3d57d2','ch_534271444698','text','{"text": "But if you read rightly, you will easily discover the true bits, and those are the book. Now books of this kind have been written in all ages by their greatest men—by great leaders, great statesmen and great thinkers. These are all at your choice; and life is short."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc14f2d570c1','ch_534271444698','text','{"text": "You have heard as much before;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c528ee7bc9d','ch_534271444698','text','{"text": "yet have you measured and mapped out this short life and its possibilities? Do you know, if you read this, that you cannot read that—that what you lose today you cannot gain tomorrow? Will you go and gossip with your housemaid, or your stable-boy, when you may talk with queens and kings;"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a03a484bc8c','ch_534271444698','text','{"text": "or flatter yourselves that it is with any worthy consciousness of your own claims to respect that you jostle with the common crowd for entrée here, an audience there, when all the while this eternal court is open to you, with its society wide as the world, multitudinous as its days, the chosen and the mighty, of every place and time? Into that you may enter always;"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3d0b8dc3d76','ch_534271444698','text','{"text": "in that you may take fellowship and rank according to your wish;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_799328d0a17f','ch_534271444698','text','{"text": "from that, once entered into it, you can never be outcast but by your own fault;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aec37cbf8668','ch_534271444698','text','{"text": "by your aristocracy of companionship there, your own inherent aristocracy will be assuredly tested and the motives with which you strive to take high place in the society of the living, measured, as to all the truth and sincerity that are in them, by the place you desire to take in this company of the Dead."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b37ca0b40b6','ch_534271444698','text','{"text": "‘The place you desire’, and the place you"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53d213aad33a','ch_534271444698','text','{"text": "‘fit yourself for’, I must also say;"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77ccf440d985','ch_534271444698','text','{"text": "because, observe, this court of the past differs from all living aristocracy in this—it is open to labour and to merit but to nothing else."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94ddbce35739','ch_534271444698','text','{"text": "No wealth will bribe, no name will overawe, no artifice will deceive the guardian of those Elysian gates. In the deep sense, no vile or vulgar person ever enters there. At the portieres of that silent Faubourg St. Germain, there is but brief question, ‘Do you deserve to enter? Pass. Do you ask to be the companion of nobles? Do you long for the conversation of the wise? Learn to understand it, and you shall hear it. But on other terms? No. If you will not rise to us, we cannot stoop to you."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b6e1a1601c9','ch_534271444698','text','{"text": "The living lord may assume courtesy, the living philosopher explain his thought to you with considerable pain;"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_29b1bb7b69c5','ch_534271444698','text','{"text": "but here we neither feign nor interpret;"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_400884f1abdc','ch_534271444698','text','{"text": "you must rise to the level of our thoughts if you would be gladdened by them, and share our feelings, if you would recognise our presence.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc8a81088dd6','ch_534271444698','text','{"text": "This, then, is what you have to do and I admit that it is much. You must, in a word, love these people if you are to be among them. No ambition is of any use. They scorn your ambition. You must love them and show your love by a true desire to be taught by them, and to enter their thoughts. To enter into theirs, observe;"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1f772c71972','ch_534271444698','text','{"text": "not to find your own expressed by them."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f56756d00dfd','ch_534271444698','text','{"text": "If the person who wrote the book is not wiser than you, you need not read it;"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_24317a42df40','ch_534271444698','text','{"text": "if he be, he will think differently from you in many respects. Very ready we are to say of a book, ‘How good this is— that’s exactly what I think!’ But the right feeling is, ‘How strange that is! I never thought of that before and yet I see it is true;"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69647c43b0a0','ch_534271444698','text','{"text": "or if I do not now, I hope I shall, some day.’"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca08d9bb354d','ch_534271444698','text','{"text": "But whether thus submissively or not, at least be sure that you go to the author to get at his meaning, not to find yours. Judge it afterwards, if you think yourself qualified to do so;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c94dc18babb1','ch_534271444698','text','{"text": "but ascertain it first. And be sure also, if the author is worth anything, that you will get at his meaning all at once;"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0644d7209a0d','ch_534271444698','text','{"text": "nay, that at his whole meaning you will not for a long time arrive in any wise."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9920c317cde2','ch_534271444698','text','{"text": "Not that he does not say what he means, and in strong words too;"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0206347a897','ch_534271444698','text','{"text": "but he cannot say it all;"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74e72c938cf8','ch_534271444698','text','{"text": "and what is more strange, will not, but in a hidden way and in parables, in order that he may be sure you want it. I cannot quite see the reason of this, nor analyse that cruel reticence in the breasts of wise men which makes them always hide their deeper thoughts. They do not give it to you by way of help, but of reward, and will make themselves sure that you deserve it before they allow you to reach it."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b222ffc22b9e','ch_534271444698','text','{"text": "But it is the same with the physical type of wisdom, gold. There seems, to you and me, no reason why the electric forces of the earth should not carry whatever there is of gold within it at once to the mountain tops, so that kings and people might know that all the gold they could get was there;"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48b2790b7df1','ch_534271444698','text','{"text": "and without any trouble of digging, or anxiety, or chance, or waste of time, cut it away, and coin as much as they needed. But nature does not manage it so."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dffec7bfa5a2','ch_534271444698','text','{"text": "She puts it in little fissures in the earth, nobody knows where: you may dig long and find none;"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52299e29c99d','ch_534271444698','text','{"text": "you must dig painfully to find any. And it is just the same with men’s best wisdom."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_522989fffd5f','ch_534271444698','text','{"text": "When you come to a good book, you must ask yourself, ‘Am I inclined to work as an Australian miner would? Are my pickaxes and shovels in good order and am I in good trim myself, my sleeves well up to the elbow, and my breath good, and my temper?’ And, keeping the figure a little longer, even at the cost of tiresomeness, for it is a thoroughly useful one, the metal you are in search of being the author’s mind or meaning, his words are as the rock which you have to crush and smelt in order to get at it. And your pickaxes are your own care, wit and learning;"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3aadb1779d8','ch_534271444698','text','{"text": "your smelting furnace is your own thoughtful soul. Do not hope to get at any good author’s meaning without these tools and that fire;"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_031caaf336b4','ch_534271444698','text','{"text": "often you will need sharpest, finest chiselling, and patientest fusing, before you can gather one grain of metal. And, therefore, first of all, I tell you, earnestly and authoritatively (I know I am right in this), you must get into the habit of looking intensely at words and assuring yourself of their meaning, syllable by syllable—nay, letter by letter. For, though it is only by reason of the opposition of letters in the function of signs, to sounds in the function of signs, that the study of books is called"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5a5341b89f03','ch_534271444698','text','{"text": "‘literature’, and that a man versed in it is called, by the consent of nations, a man of letters instead of a man of books, or of words, you may yet connect with that accidental nomenclature this real principle: that you might read all the books in the British Museum (if you could live long enough), and remain an utterly"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af5cc7ef7965','ch_534271444698','text','{"text": "‘illiterate’, uneducated person;"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2cc5377a4a0','ch_534271444698','text','{"text": "but that if you read ten pages of a good book, letter by letter—that is to say, with real accuracy—you are forever more in some measure with an educated person. The entire difference between education and non-education (as regards the merely intellectual part of it), consists in this accuracy. A well-educated gentleman may not know many languages— may not be able to speak any but his own—may have read very few books."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f1fa1111a30','ch_534271444698','text','{"text": "But whatever language he knows, he knows precisely;"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12ef4d04b438','ch_534271444698','text','{"text": "whatever word he pronounces, he pronounces rightly;"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bde1aab6884f','ch_534271444698','text','{"text": "above all, he is learned in the peerage of words;"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_111af337a461','ch_534271444698','text','{"text": "knows the words of true descent and ancient blood, at a glance, from words of modern canaille;"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e6c675e01d6','ch_534271444698','text','{"text": "remembers all their ancestry—their inter-marriages, distantest relationships, and the extent to which they were admitted, and offices they held, among the national noblesse of words at any time, and in any country."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d97643c0251','ch_534271444698','text','{"text": "But an uneducated person may know by memory any number of languages and talk them all, and yet truly not know a word of any—not a word even of his own. An ordinarily clever and sensible seaman will be able to make his way ashore at most ports;"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2b5287a4151','ch_534271444698','text','{"text": "yet he has only to speak a sentence of any language to be known for an illiterate person: so also the accent, or turn of expression of a single sentence will at once mark a scholar."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35a2f9f9cc48','ch_534271444698','text','{"text": "And this so strongly felt, so conclusively admitted, by educated persons, that a false accent or a mistaken syllable is enough, in the parliament of any civilized nation, to assign a man a certain degree of inferior standing forever. And this is right;"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac889cbcdeb3','ch_534271444698','text','{"text": "but it is a pity that the accuracy insisted on is not greater, and required to a serious purpose."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8972d21f9ecc','ch_534271444698','text','{"text": "It is right that a false Latin quantity should excite a smile in the House of Commons;"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6015b60f3905','ch_534271444698','text','{"text": "but it is wrong that a false English meaning should not excite a frown there. Let the accent of words be watched, by all means, but let the meaning be watched more closely still, and fewer will do the work. A few words, well chosen and well distinguished, will do work that a thousand cannot, when everyone is acting, equivocally, in the function of another."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2da5590f2a05','ch_534271444698','text','{"text": "Yes; and words, if they are not watched, will do deadly work sometimes."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d758fee14767','ch_534271444698','list','{"ordered": false, "items": ["John Ruskin"]}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01ff1a203b3f','ch_534271444698','heading','{"level": 2, "text": "About The Author"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fd55a42ee32','ch_534271444698','text','{"text": "John Ruskin (1819–1900) was a powerful and influential critic of the nineteenth century. He wrote on a variety of subjects: nature, art, architecture, politics, history. All his work is characterised by a clarity of vision. His first volume, Modern Painters, appeared in 1843—it defended modernism in the arts among the works of social criticism are Unto this Last (1862), and Sesame and Lilies (1871) from which this extract has been taken."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a07b8c226e32','ch_534271444698','text','{"text": "His ideas on architecture are presented in The Seven Lamps of Architecture (1849) and The Stones of Venice (1853)."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7912f0736c95','ch_534271444698','heading','{"level": 2, "text": "Understanding The Text"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6c1143cd4f4d','ch_534271444698','text','{"text": "1. What, according to Ruskin, are the limitations of the good book of the hour?"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_60d1055947c5','ch_534271444698','text','{"text": "2. What are the criteria that Ruskin feels that readers should fulfil to make themselves fit for the company of the Dead."}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9d661b71ffa','ch_534271444698','text','{"text": "3. Why does Ruskin feel that reading the work of a good author is a painstaking task?"}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_efb2f14d5302','ch_534271444698','text','{"text": "4. What is the emphasis placed by Ruskin on accuracy?"}',70);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_a136c979e32c','bk_ncert_english','11-26-the-story','11.26 The Story',NULL,'public',68,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35fda3914042','ch_a136c979e32c','text','{"text": "We shall all agree that the fundamental aspect of the novel is its story-telling aspect, but we shall voice our assent in different tones, and it is on the precise tone of voice we employ now that our subsequent conclusions will depend. Let us listen to three voices."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1843da786735','ch_a136c979e32c','text','{"text": "If you ask one type of man, ‘What does a novel do?’ he will reply placidly, ‘Well— I don’t know—it seems a funny sort of question to ask—a novel’s a novel—well, I don’t know—I suppose it kind of tells a story, so to speak’. He is quite good tempered and vague, and probably driving a motor-bus at the same time and paying no more attention to literature than it merits. Another man, whom I visualise as on a golf-course, will be aggressive and brisk."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e4018a6172b','ch_a136c979e32c','text','{"text": "He will reply, ‘What does a novel do? Why, tell a story of course and I’ve no use for it if it didn’t. I like a story. Very bad taste, on my part, no doubt, but I like a story. You can take your art, you can take your literature, you can take your music, but give me a good story. And I like a story to be a story, mind, and my wife’s the same.’"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64ff74302550','ch_a136c979e32c','text','{"text": "And a third man, he says in a sort of drooping regretful voice, ‘Yes—oh dear yes—the novel tells a story.’"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_90e79f29cb22','ch_a136c979e32c','text','{"text": "I respect and admire the first speaker. I detest and fear the second. And the third is myself. Yes—oh dear yes—the novel tells a story. That is the fundamental aspect without which it could not exist. That is the highest factor common to all novels, and I wish that it was not so, that it could be something different—melody, or perception of truth, not this low atavistic form."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb1fa74cb244','ch_a136c979e32c','text','{"text": "For, the more we look at the story (the story that is a story, mind) the more we disentangle it from the finer growths that it supports, the less shall we find to admire. It runs like a backbone—or may I say a tape-worm—for its beginning and end are arbitrary. It is immensely old—goes back to Neolithic times, perhaps to Palaeolithic. Neanderthal man listened to stories, if one may judge by the shape of his skull."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd7462927105','ch_a136c979e32c','text','{"text": "The primitive audience was an audience of shock-heads, gaping round the campfire, fatigued with contending against the mammoth or the woolly rhinoceros, and only kept awake by suspense. What would happen next? The novelist droned on and, as soon as the audience guessed what happened next, they either fell asleep or killed him. We can estimate the dangers incurred when we think of the career of Scheherazade in somewhat later times."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c04e32048f84','ch_a136c979e32c','text','{"text": "Scheherazade avoided her fate because she knew how to wield the weapon of suspense—the only literary tool that has any effect on tyrants and savages. Great novelist though she was—exquisite in her descriptions, tolerant in her judgements, ingenious in her incidents, advanced in her morality, vivid in her delineations of character, expert in her knowledge of three Oriental capitals—it was yet on none of these gifts that she relied when trying to save her life from her intolerable husband."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8ff6e314a8e','ch_a136c979e32c','text','{"text": "They were but incidental. She only survived because she managed to keep the king wondering what would happen next. Each time she saw the sun rising she stopped in the middle of a sentence, and left him gaping."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58e4d93eb777','ch_a136c979e32c','text','{"text": "‘At this moment Scheherazade saw the morning appearing and, discreet, was silent.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94de57bcc9f8','ch_a136c979e32c','text','{"text": "This uninteresting little phrase is the backbone of the One Thousand and One Nights, the tape-worm by which they are tied together and by which the life of a most accomplished princess was preserved. We are like Scheherazade’s husband in that we want to know what happens next. That is universal and that is why the backbone of a novel has to be a story."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32e0212904ca','ch_a136c979e32c','text','{"text": "Some of us want to know nothing else—there is nothing in us but primeval curiosity and, consequently, our other literary judgements are ludicrous. And now the story can be defined. It is a narrative of events arranged in their time sequence dinner coming after breakfast, Tuesday coming after Monday, decay after death, and so on. Qua story, it can only have one merit;"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f26134ef980','ch_a136c979e32c','text','{"text": "that of making the audience want to know what happens next."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97414a2a5a1c','ch_a136c979e32c','text','{"text": "And, conversely, it can have only one fault: that of making the audience not want to know what happens next. These are the only two criticisms that can be made on the story. It is the lowest and simplest of literary organisms. Yet it is the highest factor common to all the very complicated organisms known as novels."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_30c95132ade0','ch_a136c979e32c','text','{"text": "When we isolate the story like this from the nobler aspects through which it moves, and hold it out on forceps— wriggling and interminable, the naked worm of time—it presents an appearance that is both unlovely and dull. But we have much to learn from it. Let us begin by considering it in connection with daily life. Daily life is also full of the time sense."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c0c243ccaa4','ch_a136c979e32c','text','{"text": "We think one event occurs after or before another, the thought is often in our minds, and much of our talk and action proceeds from that assumption. Much of our talk and action, but not all;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48999323e3b9','ch_a136c979e32c','text','{"text": "there seems something else in life besides time, something which may conveniently be called"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74e7045c1e7d','ch_a136c979e32c','text','{"text": "‘value’, something which is measured not by minutes or hours, but by intensity, so that when we look at our past it does not stretch back evenly but piles up into a few pinnacles and when we look at the future it seems sometimes a wall, sometimes a cloud, sometimes a sun, but never a chronological chart."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ac4949ab165','ch_a136c979e32c','text','{"text": "Neither memory nor anticipation is much interested in Father Time, and all dreamers, artists and lovers are partially delivered from his tyranny;"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4deb0472ee92','ch_a136c979e32c','text','{"text": "he can kill them but he cannot secure their attention and, at the very moment of doom when the clock collected in the tower its strength and struck, they may be looking the other way. So daily life, whatever it may be really, is practically composed of two lives—the life in time and the life by values—and our conduct reveals a double allegiance."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccf6a6ca2bbf','ch_a136c979e32c','text','{"text": "‘I only saw her for five minutes, but it was worth it.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_676cb75034b2','ch_a136c979e32c','text','{"text": "There you have both allegiances in a single sentence. And what the story does is to narrate the life in time. And what the entire novel does—if it is a good novel—is to include the life by values as well;"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_137060503801','ch_a136c979e32c','text','{"text": "using devices hereafter to be examined. It, also, pays a double allegiance. But in it, the novel, the allegiance to time is imperative: no novel could be written without it."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f5d1c90cbca','ch_a136c979e32c','text','{"text": "Whereas, in daily life, the allegiance may not be necessary;"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9822b5bfdb46','ch_a136c979e32c','text','{"text": "we do not know, and the experience of certain mystics suggests, indeed, that it is not necessary, and that we are quite mistaken in supposing that Monday is followed by Tuesday, or death by decay. It is always possible for you or me in daily life to deny that time exists and act accordingly even if we become unintelligible and are sent by our fellow citizens to what they choose to call a lunatic asylum."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eec0d99fa317','ch_a136c979e32c','text','{"text": "But it is never possible for a novelist to deny time inside the fabric of his novel: he must cling, however lightly, to the thread of his story, he must touch the interminable tape-worm otherwise he becomes unintelligible, which, in his case, is a blunder. I am trying not to be philosophic about time for it is (experts assure us) a most dangerous hobby for an outsider, far more fatal than place;"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f81b9e68a47','ch_a136c979e32c','text','{"text": "and quite eminent metaphysicians have been dethroned through referring to it improperly."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bdbe2daf6f64','ch_a136c979e32c','text','{"text": "I am only trying to explain that as I lecture now I hear the clock ticking, I retain or lose the time sense;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c893cdbd64e','ch_a136c979e32c','text','{"text": "whereas, in a novel, there is always a clock. The author may dislike the clock. Emily Bronte in Wuthering Heights tried to hide hers. Sterne, in Tristram Shandy, turned it upside down. Marcel Proust, still more ingenious, kept altering the hands so that his hero was at the same time entertaining a mistress to supper and playing ball with his nurse in the park."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c39ff8418017','ch_a136c979e32c','text','{"text": "All these devices are legitimate but none of them contravene our thesis: the basis of a novel is a story and a story is a narrative of events in time sequence. From Aspects of the Novel : A Note These are some lectures (the Clark Lectures) which were delivered under the auspices of Trinity College, Cambridge, in the spring of 1927."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74038984f645','ch_a136c979e32c','text','{"text": "They were informal, indeed talkative, in their tone and it seemed safer when presenting them in book form not to mitigate the talk, in case nothing should be left at all. Words such as ‘I’, ‘you’ ‘one’, ‘we’, ‘curiously enough’, ‘so to speak’, ‘only imagine’ and ‘of course’ will consequently occur on every page and will rightly distress the sensitive reader; but he is asked to remember that if these words were removed, others, perhaps more distinguished, might escape through the orifices they left and that since the novel is itself often colloquial it may possibly withhold some of its secrets from the graver and grander streams of criticism and may reveal them to backwaters and shallows."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41d64e72ee21','ch_a136c979e32c','text','{"text": "The 1001 Arabian Nights The 1001 Arabian Nights is a collection of stories loosely linked together, narrated by a young girl Scheherazade. She was the daughter of the vizier, or minister, who had to serve a peculiar king. The king married on a daily basis: his wife was always beheaded after the wedding night. Scheherazade tells her father that she wished to marry the king. He reluctantly agrees."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f14ddf26cbf','ch_a136c979e32c','text','{"text": "She tells the king an interesting story on their wedding night, and makes sure to stop at an interesting point at the crack of dawn. The king is unwilling to execute her because he wants to hear the end of the story. This scheme was extremely risky, but Scheherazade is successful in continually linking stories over many nights until, finally, the king accepts her as his queen and stops the horrible practice of executing his wife."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8cff87d7d51','ch_a136c979e32c','list','{"ordered": false, "items": ["E.M. Forster"]}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb3f3ea7e51c','ch_a136c979e32c','heading','{"level": 2, "text": "About The Author"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f316ecd80c1d','ch_a136c979e32c','text','{"text": "E.M. Forster (1879–1970), a noted English author and critic, wrote a number of short stories, novels and essays. His first novel, Where Angels Fear to Tread, was published in 1905. This was followed by Howard’s End and A Passage to India and other well-known works. The Hill of Devi, a portrait of India with a commentary, appeared in 1953. The essay presented here is an excerpt from chapter two of Aspects of the Novel."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3d8c2216b73','ch_a136c979e32c','heading','{"level": 2, "text": "Understanding The Text"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da931ab01e12','ch_a136c979e32c','text','{"text": "1. What do you understand of the three voices in response to the question ‘What does a novel do’?"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e3dd61e0cad','ch_a136c979e32c','text','{"text": "2. What would you say are ‘the finer growths’ that the story supports in a novel?"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_adfc15470857','ch_a136c979e32c','text','{"text": "3. How does Forster trace the human interest in the story to primitive times?"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_980f6d20ba4c','ch_a136c979e32c','text','{"text": "4. Discuss the importance of time in the narration of a story."}',41);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_3b52f8e47407','bk_ncert_english','11-27-bridges','11.27 Bridges',NULL,'public',69,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_93e5cef6e033','ch_3b52f8e47407','text','{"text": "If my younger self could see me now she would be incredulous. That I would work in the field of dance or decipher and translate dance for my own comprehension, call it choreography if you wish, would have been unbelievable. In this respect, I am particularly envious of dancers who claim that they were"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba4418989ae1','ch_3b52f8e47407','text','{"text": "‘born to dance’, implying that it was clearly laid out for them from the beginning."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66b8f0550a07','ch_3b52f8e47407','text','{"text": "I must say, I find this assertion dubious;"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d53aefd71622','ch_3b52f8e47407','text','{"text": "it is rarely that easy. To dance means to struggle—I believe it is the same in any discipline because discipline itself is a struggle. I believe I was not simply born to dance;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1de876b8597e','ch_3b52f8e47407','text','{"text": "I was born to live. And now, as the patchwork of my life comes into clearer focus, I can see clear bridges between my life experiences and my work in dance. In all truth, as a child, I never did want to dance;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9274ba77ca1b','ch_3b52f8e47407','text','{"text": "it was forced upon me by a doting mother and a silent father."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f56c0924b1c','ch_3b52f8e47407','text','{"text": "My father probably kept his peace to avoid argument. From the beginning my lessons took place under trying conditions, though I believe that the conditions were more trying for my mother than for me. She travelled in local, overcrowded trains to dance class with an unwilling child, tired from a whole day at school. She waited a whole hour in the notsoclean anteroom of my guru’s house and then endured the same journey back."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a3e603e78ea4','ch_3b52f8e47407','text','{"text": "This was in Bombay, and my first dance lessons were with Guru Sunder Prasad who lived in Chowpatty while we lived in Khar. We took the train, then a bus and then walked, and the whole trip took roughly 45 minutes each way. Interestingly, it was the film industry that spurred my mother to enrol me in dance classes. When I was seven, we went to see a movie starring Mumtaz Ali, father of the comedian, Mehmood. Ali did a dance number in the film with which I became fascinated."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5321f039201f','ch_3b52f8e47407','text','{"text": "When we arrived home, I began prancing around the house imitating the film actor and my mother, who was quietly watching, was the one who said, ‘Kumudini, you are born to dance.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e67004f8cce','ch_3b52f8e47407','text','{"text": "Ironically, I have no recollection of this story;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ad59cbed6d5','ch_3b52f8e47407','text','{"text": "it was my mother who saw this innate ability in me. Her belief was so strong that she went through the gruelling exercise of taking me to dance class four days a week without complaint. However, my childhood education was composed of much more than just dance and academics. I did not live in a vacuum. I was surrounded by life and learnt many of my lessons there, lessons that I still carry with me."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_566be1ab78fb','ch_3b52f8e47407','text','{"text": "I grew up during a volatile era, a time of war, India’s independence movement compounded by World War II in which India played a role in military operations. My father, being an engineer, was called upon to build the cantonment areas first in Delhi, then in Naini and Allahabad. In Delhi we were allotted a sprawling house on Hardinge Avenue (now Tilak Marg) with Liaquat Ali (later, Prime Minister of Pakistan), as our neighbour."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e68aa7dd099','ch_3b52f8e47407','text','{"text": "Once his gardener caught me and my brother, Suresh, picking guavas from his tree. He grabbed us by the ear and presented us before the master for punishment. Liaquat Ali not only let us keep the guavas but extended an open invitation to pick the fruits whenever we wished! However, this generous offer was accompanied by the mali’s face which was so horrifying and revengeful that we never went near that garden again. It was one of my first lessons in the games that politicians play."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a72cef7481f','ch_3b52f8e47407','text','{"text": "Father would now have to move to wherever army construction was required. Therefore, when I was nine years old, the decision was made to send me to boarding school. After a lot of arguments, advice, consideration and research on the part of my parents, I was packed off to Queen Mary’s College (school) in Lahore (at that time in India)."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9d87b05e63fd','ch_3b52f8e47407','text','{"text": "I had not known a day away from home, but the idea of living with a lot of girls of my age and studying in a fancy school was both exciting and worrisome, as curiosity was mixed with sadness. No more shuffling to and from class, no more overbearing Guruji. No such luck. Mother sent a dance teacher, Radhelal Misra, Sunder Prasad’s nephew, along with me! She hired a small apartment for him in Lahore and arranged a schedule for my lessons. Despite her belief that I was"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d4e92e871a33','ch_3b52f8e47407','text','{"text": "‘born’ to dance, I didn’t enjoy dance classes. Quite frankly, they were no fun. I felt as if nothing progressed, that I was just doing what my guru ordered. I was always a curious child and I wanted to know and understand what I was doing. Why was I gyrating in this way? But my teacher could not, or would not, explain it to me. I was envious of other girls who were playing tennis and basketball while I was doing this thing called Kathak."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68b7830a2b15','ch_3b52f8e47407','text','{"text": "My mother convinced the principal, a Britisher, that to dance was a form of prayer and that she could not curb religious freedom! Having spent several years in a school where most of our teachers were British, I have come to like their form of discipline. Discipline in one’s daily routine does bring discipline in thinking. You begin to place your thoughts in neat little piles the way you do your uniforms and shoes."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7379e182cadb','ch_3b52f8e47407','text','{"text": "It was three weeks before the final school examinations—matriculation at that time—when my life changed dramatically. I was called to the Principal’s office. What had I done? The only reason one was called to Miss Cox’s office was because of some infraction. While she was a kind and diplomatic person, she was also strict and firm and later, when I myself became a teacher, I was influenced by her demeanour."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef8795c34705','ch_3b52f8e47407','text','{"text": "As I approached the office, I wondered— did I forget to put away the tennis racquets after morning play? Did I forget to lock the door of the dormitory?"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_79889a78f5c3','ch_3b52f8e47407','text','{"text": "‘May I come in, madam?’ I asked quietly."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a1408928dc1','ch_3b52f8e47407','text','{"text": "‘Yes do come in child,’ she answered with a voice full of such kindness that it made me suspicious, ‘You have to go home.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd4d7d51ee89','ch_3b52f8e47407','text','{"text": "‘But why? I have to study for my exams!’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e9789da4ce09','ch_3b52f8e47407','text','{"text": "‘Your father called to say that your mother is sick and he would like you to visit her.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d72ba0b48593','ch_3b52f8e47407','text','{"text": "During the walk back from Miss Cox’s office to my classroom I was overwhelmed with feelings of confusion, a state of mind I have never completely got over. Even today, when I want to create a new piece, the first theme that comes to my mind vibrates with confusion. Mother was already dead when I arrived, 36 hours and three trainrides later. When I saw her, motionless and colourless, I finally understood why I had been summoned home. I was 14 years old. The air was still and nobody looked at me."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_116dfc4a6e37','ch_3b52f8e47407','text','{"text": "I did not know where to turn or what to do with my hands, which hung loose from my body. Then suddenly they clutched my stomach. Hunger pangs? I hadn’t eaten for three days and there was an emptiness I wanted to fill. I was afraid of appearing greedy, so I underplayed my emotions, though all kinds of yearning gnawed my insides. Even today I mistake the different kinds of hunger inside me, and this is something that shows up in my work. The dangling arms find expression in my choreography."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2670906f69c','ch_3b52f8e47407','text','{"text": "In Duvidha or Conflict, I examined the plight of a middleclass woman who is chained to the traditions of Indian life. She is restricted to domestic circles, is forbidden from wearing sleeveless blouses, must wear her hair in a bun and must cater to her husband."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dff26edeb06','ch_3b52f8e47407','text','{"text": "Yet, from a small window she sees the newspaperman waving images of a woman with a bold streak of white in her short hair, who wears sleeveless blouses, is surrounded by men who listen to her intently, is widowed but wears colourful saris. Moreover, she commands a country with millions of people. Yet, while the woman looking out of the window is intrigued by this image, she experiences conflicting emotions."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bcd8c3cfb47f','ch_3b52f8e47407','text','{"text": "The character in Duvidha is torn between two lives—she feels an emptiness within her but is not sure what she is hungry for, what kind of life she wants. This is something I have felt often, yet now that I have so much behind me, I am more certain of where to place my hands. My exams yielded surprisingly good results. So, now what? Where do I go from here? This question has cropped up throughout my life, and many years later took shape in my composition, Atah Kim."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6899d7bb2e7c','ch_3b52f8e47407','text','{"text": "It’s funny how we store our experiences in our brains as if we are prerecorded cassettes. The right cassette seems to fall into place when you least expect it to. Upon finishing school, I was at a crossroads and the path ahead was not clear to me. I had lots of ideas about what I wanted to do with my life, and dance was not always a priority. I was always driven, and that partly stems from the fact that I had a relatively subdued childhood."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_15e43a484417','ch_3b52f8e47407','text','{"text": "I was enveloped by a great mist of protection and I wanted to emerge from that mist and discover myself. In particular, I wanted to feel powerful;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68edad6b03ea','ch_3b52f8e47407','text','{"text": "to control a large group of people. In Atah Kim I address this desire for power and, yet, once you possess it, what do you do with it? Once you reach your goal, where do you go from there? It’s a question without an answer but I believe the question must be asked. At the age of 15, I had many options."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a42abd802d8d','ch_3b52f8e47407','text','{"text": "It would have been easy enough to join college for a bachelor’s or master’s degree in psychology or English literature. But everyone does that."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed39b755f3ec','ch_3b52f8e47407','text','{"text": "‘You have to do something that is offbeat, different from the done thing,’ my father said to me."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec88bfa08cff','ch_3b52f8e47407','text','{"text": "So it was that I decided to attend an agriculture college in Naini, Allahabad. There were twentynine boys and I, in a class of thirty. Having spent my school years in a girls’ school, I knew little about the behaviour of boys. My brother was seven years younger so his friends were no help. However, at the agriculture college, I got a taste of relations between boys and girls. We had to travel for miles in the fields on bicycles."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_019739f96dde','ch_3b52f8e47407','text','{"text": "The boys deflated the tires of my bicycle so that they could walk back with me, resulting in miles and miles of worthless conversation about the latest film songs and actors, none of which interested me. Also, I was fascinated by the professors, mostly American, who wore shorts because we worked in fields with clay, crops, manure and insecticides."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f01133fa92ae','ch_3b52f8e47407','text','{"text": "One day, I also turned up in shorts and had 58 eyes peering at my legs! My grandmother had always said that girls must never push their chests out or uncover their legs. I now realised what she meant but couldn’t accept it as valid."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcb3a0e8d789','ch_3b52f8e47407','text','{"text": "‘What about the short blouses you wear, with your midriff showing?’ I asked her."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb9adfb1ac7f','ch_3b52f8e47407','text','{"text": "‘Don’t argue,’ was her reply. When will we understand the dignity of the female body? A dancer has to move with dignity, a quality much desired amongst dancers but sadly missing in most, especially women, as they are taught to underplay their bodies most of their lives. My grandmother, of course, was not completely to blame for this attitude. It is a problem that goes deep into the texture of our society. We must embrace our senses and use them to the fullest, rather than try to inhibit them."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab6f1435bb6b','ch_3b52f8e47407','text','{"text": "Another argument I often had with my grandmother was about religion and visiting temples."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27e9b6ce7d36','ch_3b52f8e47407','text','{"text": "‘Go to the temple before your exams, God will give you strength to do well,’ she would say."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_838a148fcf8e','ch_3b52f8e47407','text','{"text": "I took issue with the idea that an outside force must be bargained with in order to obtain desirable results. Doesn’t this strength come from within? I had a hard time believing that it was God alone who endowed me with this ability. Visiting temples activates your senses, though we often take this for granted. You see the grandeur of the architecture and can feel the curve of the stones. The scent of incense, flowers and sandalwood mingle together."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f8992dd7b968','ch_3b52f8e47407','text','{"text": "You hear the ringing of the bells and taste the panchamrut. With your palms and the soles of your feet you touch the different surfaces. What an experience! Why do I have to bargain with God as if he is some kind of agent for a trading company? Yet these arguments with my grandmother were useful in that they made me differentiate between sensitivity and sentimentality. Later, I created a piece called Panch Paras, the five senses, to explore this realm."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3dc143027727','ch_3b52f8e47407','text','{"text": "After graduating with a degree in agriculture at the age of 18, I was left with few job prospects and was again at a crossroads. Luckily, good fortune came to me without much beckoning. It happened in Bombay. I had gone to the train station to see off Suresh who was studying at Sherwood College in Nainital. While I was waving to the train that had now disappeared, there was a tap on my shoulder. I turned around and the woman who stood there changed the course of my life."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e62270fd2b93','ch_3b52f8e47407','text','{"text": "All those tedious hours of dance lessons fused into a new synergy. She was Komlata Dutt, a friend of my father’s and, more importantly, the person who introduced Uday Shankar to the dance legend, Anna Pavlova, in Paris."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3702120ba377','ch_3b52f8e47407','text','{"text": "And here she was, telling me to join the Ram Gopal Dance Company based in London! It took some learning to adjust to working with a group of professional dancers and musicians, on the move all the time, and the opportunity exposed me to a very different aspect of dance education—there was a lot of dance to be learnt as well—kummi of Kerala, ghumar of Rajasthan, dandia of Gujarat—all were part of the troupe’s repertoire."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_251c69512ac9','ch_3b52f8e47407','text','{"text": "What I enjoyed most was learning the classical Bharatanatyam from Ram Gopal himself who was a strict disciplinarian and had a fetish for perfection of line. However, in the end he would say, ‘You’ve perfected the technique, now throw it overboard and dance’. This is a lesson I have tried to teach my own students—before you begin experimenting, you need to perfect the technique with which you experiment."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b3c3ca503fe','ch_3b52f8e47407','text','{"text": "Touring with Ram Gopal not only taught me more about dance, I discovered new things about my own personality. Encountering people from different countries gives you a chance to look at yourself in a new light. More often than not, I found that my weaknesses were brought glaringly into focus. I came to realise the importance of context— how things change when you change their placement. One of the most striking moments of that tour was my time in postwar Germany. It was an unbelievably sad place."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_073ea65f19e6','ch_3b52f8e47407','text','{"text": "Hungry children begging for food is a common sight in India, yet, in Germany the same sight created a different sensation. It amazed me how the same situation in a different environment evokes quite different reactions, and the same is true in dance. One changes the placement of a choreographic piece on stage and it looks quite different. I myself was a changed person when placed in different surroundings. Still, a long tour of many countries in Europe and America is exhausting."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f56fb8c338a1','ch_3b52f8e47407','text','{"text": "I was constantly travelling between India and various parts of the globe. In all, I was abroad for three years and by the end, I needed to go home. But where was home? And how does one make a home for oneself? Buy a house, get married, have children, make friends? I had only the last item on the agenda. While in school in Lahore, I had made a lot of friends, but they now lived in a different country—Pakistan. I had to obtain a visa to visit my closest friend over a weekend."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e369a51980c','ch_3b52f8e47407','text','{"text": "I would like to say I am apolitical but I’ve discovered that politics makes its presence felt even when uninvited. On my return, the last of many returns, what ultimately awaited me were marriage, children and a flat in Bombay. Finally I had a home, but it came with strings attached—I now had to manage this new home. In a society like ours, where a woman wanting to work outside the home must do so in addition to her domestic responsibilities, it is easy to feel overwhelmed."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_602412a96d10','ch_3b52f8e47407','text','{"text": "Still, I didn’t do too badly thanks to my supportive husband, Rajanikant. In spite of his own background in a family where men are treated as a special breed, he was a good man, with the extraordinary quality of believing everything. The word"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83c570e22ca4','ch_3b52f8e47407','text','{"text": "‘suspicion’ was absent from his vocabulary. This made him popular but unsuccessful, both as a professional and a parent, but a very accommodating husband. My biggest benefit from my association with him was the love of music he instilled in me. If he had chosen music as a profession he would have done better in life, but his baratlaw from Lincoln’s Inn in London pushed him into the wrong line of work."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49cf2588224d','ch_3b52f8e47407','text','{"text": "I must say, I am blessed with a wonderful family, two normal and healthy children, my son Shriraj and daughter Maitreyi, now married with their own children. Looking back, I keep wondering what my contribution was as a mother, but it must have been satisfactory to attain these results. And yet, both are completely different in their attitudes and philosophies—one has an extended sense of ambition and the other allows things to transpire as they are destined to."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_608231c80381','ch_3b52f8e47407','text','{"text": "The only point on which they agree is that they disagree with my profession! It is interesting to have this kind of variety in a family. Living with a group of different personalities beneath one roof is like performing with other artistes on stage. The equation, the space factor, vibrations and relationships must be taken into serious consideration. You are no longer performing solo. You belong to a larger image and must develop a new set of performing skills."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23da7d2d55a0','ch_3b52f8e47407','list','{"ordered": false, "items": ["Kumudini Lakhia"]}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c40dd38b397','ch_3b52f8e47407','heading','{"level": 2, "text": "About The Author"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d44028e9932f','ch_3b52f8e47407','text','{"text": "Kumudini Lakhia (born 1930) is a renowned Kathak dancer and choreographer who was taught and influenced by the famous Ram Gopal. She has performed in over 40 countries, but chose to give up her career as a solo performer to start the Kadamb Dance Centre in Ahmedabad, where she trains students in the art of classical Kathak dance. Her other achievements include choreographing for two very successful Hindi films, Umrao Jaan and Sur Sangam."}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e8197ceeb07d','ch_3b52f8e47407','text','{"text": "Her awards include the All India Sangeet Natya Kala Award (1977);"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_908ee60c75f1','ch_3b52f8e47407','text','{"text": "Sangeet Natak Akademi National Award (1982);"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4033ea2c35b','ch_3b52f8e47407','text','{"text": "Kala Ratna Award;"}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee7ac223789c','ch_3b52f8e47407','text','{"text": "Sangeet Kala Sangam (1982);"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca6f7b79de95','ch_3b52f8e47407','text','{"text": "and the Padma Shri in 1987. On the occasion of 50 years of Independence, the city of Ahmedabad awarded her with the Nagar Bhushan."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a123a59df6b1','ch_3b52f8e47407','heading','{"level": 2, "text": "Understanding The Text"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_febfe4d7e953','ch_3b52f8e47407','text','{"text": "1. How did the author feel about her mother’s passion to make her a dancer?"}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e088a86e4ee8','ch_3b52f8e47407','text','{"text": "2. What were the lessons of life learnt in her younger days that Kumudini carried into her adult life?"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f9e879ccbf9','ch_3b52f8e47407','text','{"text": "3. How did Kumudini react to her mother’s death?"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d94f16c2540f','ch_3b52f8e47407','text','{"text": "4. What were the concepts that Kumidini Lakhia represent through Duvidha, Atah Kim and Panch Paras?"}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b163af1afcb4','ch_3b52f8e47407','text','{"text": "5. How does Kumudini Lakhia describe her guru Ramgopal’s influence on her?"}',68);
